BEGIN TRANSACTION;
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (1, 'Bulbasaur', 'Grass', 'Poison', 'Kanto', 'KANTO', 'A strange seed was planted on its back at birth. The plant sprouts and grows with this POKéMON.', 'romfs:/sprites/001.png', 45, 49, 49, 65, 65, 45, 'medium-slow', 'overgrow', 'chlorophyll', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (2, 'Ivysaur', 'Grass', 'Poison', 'Kanto', 'KANTO', 'When the bulb on its back grows large, it appears to lose the ability to stand on its hind legs.', 'romfs:/sprites/002.png', 60, 62, 63, 80, 80, 60, 'medium-slow', 'overgrow', 'chlorophyll', NULL, 16);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (3, 'Venusaur', 'Grass', 'Poison', 'Kanto', 'KANTO', 'The plant blooms when it is absorbing solar energy. It stays on the move to seek sunlight.', 'romfs:/sprites/003.png', 80, 82, 83, 100, 100, 80, 'medium-slow', 'overgrow', 'chlorophyll', NULL, 32);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (4, 'Charmander', 'Fire', NULL, 'Kanto', 'KANTO', 'Obviously prefers hot places. When it rains, steam is said to spout from the tip of its tail.', 'romfs:/sprites/004.png', 39, 52, 43, 60, 50, 65, 'medium-slow', 'blaze', 'solar-power', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (5, 'Charmeleon', 'Fire', NULL, 'Kanto', 'KANTO', 'When it swings its burning tail, it elevates the temperature to unbearably high levels.', 'romfs:/sprites/005.png', 58, 64, 58, 80, 65, 80, 'medium-slow', 'blaze', 'solar-power', NULL, 16);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (6, 'Charizard', 'Fire', 'Flying', 'Kanto', 'KANTO', 'Spits fire that is hot enough to melt boulders. Known to cause forest fires unintentionally.', 'romfs:/sprites/006.png', 78, 84, 78, 109, 85, 100, 'medium-slow', 'blaze', 'solar-power', NULL, 36);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (7, 'Squirtle', 'Water', NULL, 'Kanto', 'KANTO', 'After birth, its back swells and hardens into a shell. Powerfully sprays foam from its mouth.', 'romfs:/sprites/007.png', 44, 48, 65, 50, 64, 43, 'medium-slow', 'torrent', 'rain-dish', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (8, 'Wartortle', 'Water', NULL, 'Kanto', 'KANTO', 'Often hides in water to stalk unwary prey. For swimming fast, it moves its ears to maintain balance.', 'romfs:/sprites/008.png', 59, 63, 80, 65, 80, 58, 'medium-slow', 'torrent', 'rain-dish', NULL, 16);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (9, 'Blastoise', 'Water', NULL, 'Kanto', 'KANTO', 'A brutal POKéMON with pressurized water jets on its shell. They are used for high speed tackles.', 'romfs:/sprites/009.png', 79, 83, 100, 85, 105, 78, 'medium-slow', 'torrent', 'rain-dish', NULL, 36);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (10, 'Caterpie', 'Bug', NULL, 'Kanto', 'KANTO', 'Its short feet are tipped with suction pads that enable it to tirelessly climb slopes and walls.', 'romfs:/sprites/010.png', 45, 30, 35, 20, 20, 45, 'medium', 'shield-dust', 'run-away', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (11, 'Metapod', 'Bug', NULL, 'Kanto', 'KANTO', 'This POKéMON is vulnerable to attack while its shell is soft, exposing its weak and tender body.', 'romfs:/sprites/011.png', 50, 20, 55, 25, 25, 30, 'medium', 'shed-skin', NULL, NULL, 7);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (12, 'Butterfree', 'Bug', 'Flying', 'Kanto', 'KANTO', 'In battle, it flaps its wings at high speed to release highly toxic dust into the air.', 'romfs:/sprites/012.png', 60, 45, 50, 90, 80, 70, 'medium', 'compound-eyes', 'tinted-lens', NULL, 10);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (13, 'Weedle', 'Bug', 'Poison', 'Kanto', 'KANTO', 'Often found in forests, eating leaves. It has a sharp venomous stinger on its head.', 'romfs:/sprites/013.png', 40, 35, 30, 20, 20, 50, 'medium', 'shield-dust', 'run-away', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (14, 'Kakuna', 'Bug', 'Poison', 'Kanto', 'KANTO', 'Almost incapable of moving, this POKéMON can only harden its shell to protect itself from predators.', 'romfs:/sprites/014.png', 45, 25, 50, 25, 25, 35, 'medium', 'shed-skin', NULL, NULL, 7);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (15, 'Beedrill', 'Bug', 'Poison', 'Kanto', 'KANTO', 'It has three poisonous stingers on its forelegs and its tail. They are used to jab its enemy repeatedly.', 'romfs:/sprites/015.png', 65, 90, 40, 45, 80, 75, 'medium', 'swarm', 'sniper', NULL, 10);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (16, 'Pidgey', 'Normal', 'Flying', 'Kanto', 'KANTO', 'A common sight in forests and woods. It flaps its wings at ground level to kick up blinding sand.', 'romfs:/sprites/016.png', 40, 45, 40, 35, 35, 56, 'medium-slow', 'keen-eye', 'tangled-feet', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (17, 'Pidgeotto', 'Normal', 'Flying', 'Kanto', 'KANTO', 'Very protective of its sprawling territorial area, this POKéMON will fiercely peck at any intruder.', 'romfs:/sprites/017.png', 63, 60, 55, 50, 50, 71, 'medium-slow', 'keen-eye', 'tangled-feet', NULL, 18);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (18, 'Pidgeot', 'Normal', 'Flying', 'Kanto', 'KANTO', 'When hunting, it skims the surface of water at high speed to pick off unwary prey such as MAGIKARP.', 'romfs:/sprites/018.png', 83, 80, 75, 70, 70, 101, 'medium-slow', 'keen-eye', 'tangled-feet', NULL, 36);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (19, 'Rattata', 'Normal', NULL, 'Kanto', 'KANTO', 'Bites anything when it attacks. Small and very quick, it is a common sight in many places.', 'romfs:/sprites/019.png', 30, 56, 35, 25, 35, 72, 'medium', 'run-away', 'guts', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (20, 'Raticate', 'Normal', NULL, 'Kanto', 'KANTO', 'It uses its whis­ kers to maintain its balance. It apparently slows down if they are cut off.', 'romfs:/sprites/020.png', 55, 81, 60, 50, 70, 97, 'medium', 'run-away', 'guts', NULL, 20);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (21, 'Spearow', 'Normal', 'Flying', 'Kanto', 'KANTO', 'It flaps its small wings busily to fly. Using its beak, it searches in grass for prey.', 'romfs:/sprites/021.png', 40, 60, 30, 31, 31, 70, 'medium', 'keen-eye', 'sniper', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (22, 'Fearow', 'Normal', 'Flying', 'Kanto', 'KANTO', 'With its huge and magnificent wings, it can keep aloft without ever having to land for rest.', 'romfs:/sprites/022.png', 65, 90, 65, 61, 61, 100, 'medium', 'keen-eye', 'sniper', NULL, 20);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (23, 'Ekans', 'Poison', NULL, 'Kanto', 'KANTO', 'Moves silently and stealthily. Eats the eggs of birds, such as PIDGEY and SPEAROW, whole.', 'romfs:/sprites/023.png', 35, 60, 44, 40, 54, 55, 'medium', 'intimidate', 'shed-skin', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (24, 'Arbok', 'Poison', NULL, 'Kanto', 'KANTO', 'It is rumored that the ferocious warning markings on its belly differ from area to area.', 'romfs:/sprites/024.png', 60, 95, 69, 65, 79, 80, 'medium', 'intimidate', 'shed-skin', NULL, 22);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (25, 'Pikachu', 'Electric', NULL, 'Kanto', 'KANTO', 'When several of these POKéMON gather, their electricity could build and cause lightning storms.', 'romfs:/sprites/025.png', 35, 55, 40, 50, 50, 90, 'medium', 'static', 'lightning-rod', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (26, 'Raichu', 'Electric', NULL, 'Kanto', 'KANTO', 'Its long tail serves as a ground to protect itself from its own high-voltage power.', 'romfs:/sprites/026.png', 60, 90, 55, 90, 80, 110, 'medium', 'static', 'lightning-rod', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (27, 'Sandshrew', 'Ground', NULL, 'Kanto', 'KANTO', 'Burrows deep underground in arid locations far from water. It only emerges to hunt for food.', 'romfs:/sprites/027.png', 50, 75, 85, 20, 30, 40, 'medium', 'sand-veil', 'sand-rush', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (28, 'Sandslash', 'Ground', NULL, 'Kanto', 'KANTO', 'Curls up into a spiny ball when threatened. It can roll while curled up to attack or escape.', 'romfs:/sprites/028.png', 75, 100, 110, 45, 55, 65, 'medium', 'sand-veil', 'sand-rush', NULL, 22);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (29, 'Nidoran-f', 'Poison', NULL, 'Kanto', 'KANTO', 'Although small, its venomous barbs render this POKéMON dangerous. The female has smaller horns.', 'romfs:/sprites/029.png', 55, 47, 52, 40, 40, 41, 'medium-slow', 'poison-point', 'rivalry', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (30, 'Nidorina', 'Poison', NULL, 'Kanto', 'KANTO', 'The female''s horn develops slowly. Prefers physical attacks such as clawing and biting.', 'romfs:/sprites/030.png', 70, 62, 67, 55, 55, 56, 'medium-slow', 'poison-point', 'rivalry', NULL, 16);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (31, 'Nidoqueen', 'Poison', 'Ground', 'Kanto', 'KANTO', 'Its hard scales provide strong protection. It uses its hefty bulk to execute powerful moves.', 'romfs:/sprites/031.png', 90, 92, 87, 75, 85, 76, 'medium-slow', 'poison-point', 'rivalry', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (32, 'Nidoran-m', 'Poison', NULL, 'Kanto', 'KANTO', 'Stiffens its ears to sense danger. The larger its horns, the more powerful its secreted venom.', 'romfs:/sprites/032.png', 46, 57, 40, 40, 40, 50, 'medium-slow', 'poison-point', 'rivalry', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (33, 'Nidorino', 'Poison', NULL, 'Kanto', 'KANTO', 'An aggressive POKéMON that is quick to attack. The horn on its head secretes a powerful venom.', 'romfs:/sprites/033.png', 61, 72, 57, 55, 55, 65, 'medium-slow', 'poison-point', 'rivalry', NULL, 16);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (34, 'Nidoking', 'Poison', 'Ground', 'Kanto', 'KANTO', 'It uses its powerful tail in battle to smash, constrict, then break the prey''s bones.', 'romfs:/sprites/034.png', 81, 102, 77, 85, 75, 85, 'medium-slow', 'poison-point', 'rivalry', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (35, 'Clefairy', 'Fairy', NULL, 'Kanto', 'KANTO', 'Its magical and cute appeal has many admirers. It is rare and found only in certain areas.', 'romfs:/sprites/035.png', 70, 45, 48, 60, 65, 35, 'fast', 'cute-charm', 'magic-guard', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (36, 'Clefable', 'Fairy', NULL, 'Kanto', 'KANTO', 'A timid fairy POKéMON that is rarely seen. It will run and hide the moment it senses people.', 'romfs:/sprites/036.png', 95, 70, 73, 95, 90, 60, 'fast', 'cute-charm', 'magic-guard', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (37, 'Vulpix', 'Fire', NULL, 'Kanto', 'KANTO', 'At the time of birth, it has just one tail. The tail splits from its tip as it grows older.', 'romfs:/sprites/037.png', 38, 41, 40, 50, 65, 65, 'medium', 'flash-fire', 'drought', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (38, 'Ninetales', 'Fire', NULL, 'Kanto', 'KANTO', 'Very smart and very vengeful. Grabbing one of its many tails could result in a 1000-year curse.', 'romfs:/sprites/038.png', 73, 76, 75, 81, 100, 100, 'medium', 'flash-fire', 'drought', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (39, 'Jigglypuff', 'Normal', 'Fairy', 'Kanto', 'KANTO', 'When its huge eyes light up, it sings a mysteriously soothing melody that lulls its enemies to sleep.', 'romfs:/sprites/039.png', 115, 45, 20, 45, 25, 20, 'fast', 'cute-charm', 'competitive', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (40, 'Wigglytuff', 'Normal', 'Fairy', 'Kanto', 'KANTO', 'The body is soft and rubbery. When angered, it will suck in air and inflate itself to an enormous size.', 'romfs:/sprites/040.png', 140, 70, 45, 85, 50, 45, 'fast', 'cute-charm', 'competitive', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (41, 'Zubat', 'Poison', 'Flying', 'Kanto', 'KANTO', 'Forms colonies in perpetually dark places. Uses ultrasonic waves to identify and approach targets.', 'romfs:/sprites/041.png', 40, 45, 35, 30, 40, 55, 'medium', 'inner-focus', 'infiltrator', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (42, 'Golbat', 'Poison', 'Flying', 'Kanto', 'KANTO', 'Once it strikes, it will not stop draining energy from the victim even if it gets too heavy to fly.', 'romfs:/sprites/042.png', 75, 80, 70, 65, 75, 90, 'medium', 'inner-focus', 'infiltrator', NULL, 22);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (43, 'Oddish', 'Grass', 'Poison', 'Kanto', 'KANTO', 'During the day, it keeps its face buried in the ground. At night, it wanders around sowing its seeds.', 'romfs:/sprites/043.png', 45, 50, 55, 75, 65, 30, 'medium-slow', 'chlorophyll', 'run-away', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (44, 'Gloom', 'Grass', 'Poison', 'Kanto', 'KANTO', 'The fluid that oozes from its mouth isn''t drool. It is a nectar that is used to attract prey.', 'romfs:/sprites/044.png', 60, 65, 70, 85, 75, 40, 'medium-slow', 'chlorophyll', 'stench', NULL, 21);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (45, 'Vileplume', 'Grass', 'Poison', 'Kanto', 'KANTO', 'It has the world’s largest petals. With every step, the petals shake out heavy clouds of toxic pollen.', 'romfs:/sprites/045.png', 75, 80, 85, 110, 90, 50, 'medium-slow', 'chlorophyll', 'effect-spore', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (46, 'Paras', 'Bug', 'Grass', 'Kanto', 'KANTO', 'Burrows to suck tree roots. The mushrooms on its back grow by draw­ ing nutrients from the bug host.', 'romfs:/sprites/046.png', 35, 70, 55, 45, 55, 25, 'medium', 'effect-spore', 'dry-skin', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (47, 'Parasect', 'Bug', 'Grass', 'Kanto', 'KANTO', 'A host-parasite pair in which the parasite mushroom has taken over the host bug. Prefers damp places.', 'romfs:/sprites/047.png', 60, 95, 80, 60, 80, 30, 'medium', 'effect-spore', 'dry-skin', NULL, 24);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (48, 'Venonat', 'Bug', 'Poison', 'Kanto', 'KANTO', 'Lives in the shadows of tall trees where it eats insects. It is attracted by light at night.', 'romfs:/sprites/048.png', 60, 55, 50, 40, 55, 45, 'medium', 'compound-eyes', 'tinted-lens', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (49, 'Venomoth', 'Bug', 'Poison', 'Kanto', 'KANTO', 'The dustlike scales covering its wings are color-coded to indicate the kinds of poison it has.', 'romfs:/sprites/049.png', 70, 65, 60, 90, 75, 90, 'medium', 'shield-dust', 'tinted-lens', NULL, 31);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (50, 'Diglett', 'Ground', NULL, 'Kanto', 'KANTO', 'Lives about one yard underground where it feeds on plant roots. It sometimes appears above ground.', 'romfs:/sprites/050.png', 10, 55, 25, 35, 45, 95, 'medium', 'sand-veil', 'arena-trap', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (51, 'Dugtrio', 'Ground', NULL, 'Kanto', 'KANTO', 'A team of DIGLETT triplets. It triggers huge earthquakes by burrowing 60 miles underground.', 'romfs:/sprites/051.png', 35, 100, 50, 50, 70, 120, 'medium', 'sand-veil', 'arena-trap', NULL, 26);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (52, 'Meowth', 'Normal', NULL, 'Kanto', 'KANTO', 'It washes its face regularly to keep the coin on its forehead spotless. It doesn’t get along with Galarian Meowth.', 'romfs:/sprites/052.png', 40, 45, 35, 40, 40, 90, 'medium', 'pickup', 'technician', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (53, 'Persian', 'Normal', NULL, 'Kanto', 'KANTO', 'Although its fur has many admirers, it is tough to raise as a pet because of its fickle meanness.', 'romfs:/sprites/053.png', 65, 70, 60, 65, 65, 115, 'medium', 'limber', 'technician', NULL, 28);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (54, 'Psyduck', 'Water', NULL, 'Kanto', 'KANTO', 'While lulling its enemies with its vacant look, this wily POKéMON will use psychokinetic powers.', 'romfs:/sprites/054.png', 50, 52, 48, 65, 50, 55, 'medium', 'damp', 'cloud-nine', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (55, 'Golduck', 'Water', NULL, 'Kanto', 'KANTO', 'Often seen swim­ ming elegantly by lake shores. It is often mistaken for the Japanese monster, Kappa.', 'romfs:/sprites/055.png', 80, 82, 78, 95, 80, 85, 'medium', 'damp', 'cloud-nine', NULL, 33);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (56, 'Mankey', 'Fighting', NULL, 'Kanto', 'KANTO', 'Extremely quick to anger. It could be docile one moment then thrashing away the next instant.', 'romfs:/sprites/056.png', 40, 80, 35, 35, 45, 70, 'medium', 'vital-spirit', 'anger-point', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (57, 'Primeape', 'Fighting', NULL, 'Kanto', 'KANTO', 'Always furious and tenacious to boot. It will not abandon chasing its quarry until it is caught.', 'romfs:/sprites/057.png', 65, 105, 60, 60, 70, 95, 'medium', 'vital-spirit', 'anger-point', NULL, 28);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (58, 'Growlithe', 'Fire', NULL, 'Kanto', 'KANTO', 'Very protective of its territory. It will bark and bite to repel intruders from its space.', 'romfs:/sprites/058.png', 55, 70, 45, 70, 50, 60, 'slow', 'intimidate', 'flash-fire', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (59, 'Arcanine', 'Fire', NULL, 'Kanto', 'KANTO', 'A POKéMON that has been admired since the past for its beauty. It runs agilely as if on wings.', 'romfs:/sprites/059.png', 90, 110, 80, 100, 80, 95, 'slow', 'intimidate', 'flash-fire', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (60, 'Poliwag', 'Water', NULL, 'Kanto', 'KANTO', 'Its newly grown legs prevent it from running. It appears to prefer swimming than trying to stand.', 'romfs:/sprites/060.png', 40, 50, 40, 40, 40, 90, 'medium-slow', 'water-absorb', 'damp', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (61, 'Poliwhirl', 'Water', NULL, 'Kanto', 'KANTO', 'Capable of living in or out of water. When out of water, it sweats to keep its body slimy.', 'romfs:/sprites/061.png', 65, 65, 65, 50, 50, 90, 'medium-slow', 'water-absorb', 'damp', NULL, 25);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (62, 'Poliwrath', 'Water', 'Fighting', 'Kanto', 'KANTO', 'An adept swimmer at both the front crawl and breast stroke. Easily overtakes the best human swimmers.', 'romfs:/sprites/062.png', 90, 95, 95, 70, 90, 70, 'medium-slow', 'water-absorb', 'damp', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (63, 'Abra', 'Psychic', NULL, 'Kanto', 'KANTO', 'Using its ability to read minds, it will identify impending danger and TELEPORT to safety.', 'romfs:/sprites/063.png', 25, 20, 15, 105, 55, 90, 'medium-slow', 'synchronize', 'inner-focus', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (64, 'Kadabra', 'Psychic', NULL, 'Kanto', 'KANTO', 'It emits special alpha waves from its body that induce headaches just by being close by.', 'romfs:/sprites/064.png', 40, 35, 30, 120, 70, 105, 'medium-slow', 'synchronize', 'inner-focus', NULL, 16);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (65, 'Alakazam', 'Psychic', NULL, 'Kanto', 'KANTO', 'Its brain can out­ perform a super­ computer. Its intelligence quotient is said to be 5,000.', 'romfs:/sprites/065.png', 55, 50, 45, 135, 95, 120, 'medium-slow', 'synchronize', 'inner-focus', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (66, 'Machop', 'Fighting', NULL, 'Kanto', 'KANTO', 'Loves to build its muscles. It trains in all styles of martial arts to become even stronger.', 'romfs:/sprites/066.png', 70, 80, 50, 35, 35, 35, 'medium-slow', 'guts', 'no-guard', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (67, 'Machoke', 'Fighting', NULL, 'Kanto', 'KANTO', 'Its muscular body is so powerful, it must wear a power save belt to be able to regulate its motions.', 'romfs:/sprites/067.png', 80, 100, 70, 50, 60, 45, 'medium-slow', 'guts', 'no-guard', NULL, 28);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (68, 'Machamp', 'Fighting', NULL, 'Kanto', 'KANTO', 'Using its heavy muscles, it throws powerful punches that can send the victim clear over the horizon.', 'romfs:/sprites/068.png', 90, 130, 80, 65, 85, 55, 'medium-slow', 'guts', 'no-guard', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (69, 'Bellsprout', 'Grass', 'Poison', 'Kanto', 'KANTO', 'A carnivorous POKéMON that traps and eats bugs. It uses its root feet to soak up needed moisture.', 'romfs:/sprites/069.png', 50, 75, 35, 70, 30, 40, 'medium-slow', 'chlorophyll', 'gluttony', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (70, 'Weepinbell', 'Grass', 'Poison', 'Kanto', 'KANTO', 'It spits out POISONPOWDER to immobilize the enemy and then finishes it with a spray of ACID.', 'romfs:/sprites/070.png', 65, 90, 50, 85, 45, 55, 'medium-slow', 'chlorophyll', 'gluttony', NULL, 21);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (71, 'Victreebel', 'Grass', 'Poison', 'Kanto', 'KANTO', 'Said to live in huge colonies deep in jungles, although no one has ever returned from there.', 'romfs:/sprites/071.png', 80, 105, 65, 100, 70, 70, 'medium-slow', 'chlorophyll', 'gluttony', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (72, 'Tentacool', 'Water', 'Poison', 'Kanto', 'KANTO', 'Drifts in shallow seas. Anglers who hook them by accident are often punished by its stinging acid.', 'romfs:/sprites/072.png', 40, 40, 35, 50, 100, 70, 'slow', 'clear-body', 'liquid-ooze', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (73, 'Tentacruel', 'Water', 'Poison', 'Kanto', 'KANTO', 'The tentacles are normally kept short. On hunts, they are extended to ensnare and immobilize prey.', 'romfs:/sprites/073.png', 80, 70, 65, 80, 120, 100, 'slow', 'clear-body', 'liquid-ooze', NULL, 30);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (74, 'Geodude', 'Rock', 'Ground', 'Kanto', 'KANTO', 'Found in fields and mountains. Mistaking them for boulders, people often step or trip on them.', 'romfs:/sprites/074.png', 40, 80, 100, 30, 30, 20, 'medium-slow', 'rock-head', 'sturdy', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (75, 'Graveler', 'Rock', 'Ground', 'Kanto', 'KANTO', 'Rolls down slopes to move. It rolls over any obstacle without slowing or changing its direction.', 'romfs:/sprites/075.png', 55, 95, 115, 45, 45, 35, 'medium-slow', 'rock-head', 'sturdy', NULL, 25);
