INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (77, 'Ponyta', 'Fire', NULL, 'Kanto', 'KANTO', 'Its hooves are 10 times harder than diamonds. It can trample anything completely flat in little time.', 'romfs:/sprites/077.png', 50, 85, 55, 65, 65, 90, 'medium', 'run-away', 'flash-fire', NULL, NULL);
