INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (80, 'Slowbro', 'Water', 'Psychic', 'Kanto', 'KANTO', 'The SHELLDER that is latched onto SLOWPOKE''s tail is said to feed on the host''s left over scraps.', 'romfs:/sprites/080.png', 95, 75, 110, 100, 80, 30, 'medium', 'oblivious', 'own-tempo', NULL, 37);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (81, 'Magnemite', 'Electric', 'Steel', 'Kanto', 'KANTO', 'Uses anti-gravity to stay suspended. Appears without warning and uses THUNDER WAVE and similar moves.', 'romfs:/sprites/081.png', 25, 35, 70, 95, 55, 45, 'medium', 'magnet-pull', 'sturdy', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (82, 'Magneton', 'Electric', 'Steel', 'Kanto', 'KANTO', 'Formed by several MAGNEMITEs linked together. They frequently appear when sunspots flare up.', 'romfs:/sprites/082.png', 50, 60, 95, 120, 70, 70, 'medium', 'magnet-pull', 'sturdy', NULL, 30);
