INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (84, 'Doduo', 'Normal', 'Flying', 'Kanto', 'KANTO', 'A bird that makes up for its poor flying with its fast foot speed. Leaves giant footprints.', 'romfs:/sprites/084.png', 35, 85, 45, 35, 35, 75, 'medium', 'run-away', 'early-bird', NULL, NULL);
