INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (86, 'Seel', 'Water', NULL, 'Kanto', 'KANTO', 'The protruding horn on its head is very hard. It is used for bashing through thick ice.', 'romfs:/sprites/086.png', 65, 45, 55, 45, 70, 45, 'medium', 'thick-fat', 'hydration', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (87, 'Dewgong', 'Water', 'Ice', 'Kanto', 'KANTO', 'Stores thermal energy in its body. Swims at a steady 8 knots even in intensely cold waters.', 'romfs:/sprites/087.png', 90, 70, 80, 70, 95, 70, 'medium', 'thick-fat', 'hydration', NULL, 34);
