INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (90, 'Shellder', 'Water', NULL, 'Kanto', 'KANTO', 'Its hard shell repels any kind of attack. It is vulnerable only when its shell is open.', 'romfs:/sprites/090.png', 30, 65, 100, 45, 25, 40, 'slow', 'shell-armor', 'skill-link', NULL, NULL);
