INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (93, 'Haunter', 'Ghost', 'Poison', 'Kanto', 'KANTO', 'Because of its ability to slip through block walls, it is said to be from an­ other dimension.', 'romfs:/sprites/093.png', 45, 50, 45, 115, 55, 95, 'medium-slow', 'levitate', NULL, NULL, 25);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (94, 'Gengar', 'Ghost', 'Poison', 'Kanto', 'KANTO', 'Under a full moon, this POKéMON likes to mimic the shadows of people and laugh at their fright.', 'romfs:/sprites/094.png', 60, 65, 60, 130, 75, 110, 'medium-slow', 'cursed-body', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (95, 'Onix', 'Rock', 'Ground', 'Kanto', 'KANTO', 'As it grows, the stone portions of its body harden to become similar to a diamond, but colored black.', 'romfs:/sprites/095.png', 35, 45, 160, 30, 45, 70, 'medium', 'rock-head', 'sturdy', NULL, NULL);
