INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (98, 'Krabby', 'Water', NULL, 'Kanto', 'KANTO', 'Its pincers are not only powerful weapons, they are used for balance when walking sideways.', 'romfs:/sprites/098.png', 30, 105, 90, 25, 25, 50, 'medium', 'hyper-cutter', 'shell-armor', NULL, NULL);
