INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (151, 'Mew', 'Psychic', NULL, 'Kanto', 'KANTO', 'So rare that it is still said to be a mirage by many experts. Only a few people have seen it worldwide.', 'romfs:/sprites/151.png', 100, 100, 100, 100, 100, 100, 'medium-slow', 'synchronize', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (152, 'Chikorita', 'Grass', NULL, 'Johto', 'JOHTO', 'A sweet aroma gently wafts from the leaf on its head. It is docile and loves to soak up the sun''s rays.', 'romfs:/sprites/152.png', 45, 49, 65, 49, 65, 45, 'medium-slow', 'overgrow', 'leaf-guard', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (153, 'Bayleef', 'Grass', NULL, 'Johto', 'JOHTO', 'The scent of spices comes from around its neck. Somehow, sniffing it makes you want to fight.', 'romfs:/sprites/153.png', 60, 62, 80, 63, 80, 60, 'medium-slow', 'overgrow', 'leaf-guard', NULL, 16);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (154, 'Meganium', 'Grass', NULL, 'Johto', 'JOHTO', 'The aroma that rises from its petals contains a substance that calms aggressive feelings.', 'romfs:/sprites/154.png', 80, 82, 100, 83, 100, 80, 'medium-slow', 'overgrow', 'leaf-guard', NULL, 32);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (155, 'Cyndaquil', 'Fire', NULL, 'Johto', 'JOHTO', 'It has a timid nature. If it is startled, the flames on its back burn more vigorously.', 'romfs:/sprites/155.png', 39, 52, 43, 60, 50, 65, 'medium-slow', 'blaze', 'flash-fire', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (156, 'Quilava', 'Fire', NULL, 'Johto', 'JOHTO', 'Be careful if it turns its back during battle. It means that it will attack with the fire on its back.', 'romfs:/sprites/156.png', 58, 64, 58, 80, 65, 80, 'medium-slow', 'blaze', 'flash-fire', NULL, 14);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (157, 'Typhlosion', 'Fire', NULL, 'Johto', 'JOHTO', 'If its rage peaks, it becomes so hot that anything that touches it will instantly go up in flames.', 'romfs:/sprites/157.png', 78, 84, 78, 109, 85, 100, 'medium-slow', 'blaze', 'flash-fire', NULL, 36);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (158, 'Totodile', 'Water', NULL, 'Johto', 'JOHTO', 'Its well-developed jaws are powerful and capable of crushing anything. Even its trainer must be careful.', 'romfs:/sprites/158.png', 50, 65, 64, 44, 48, 43, 'medium-slow', 'torrent', 'sheer-force', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (159, 'Croconaw', 'Water', NULL, 'Johto', 'JOHTO', 'If it loses a fang, a new one grows back in its place. There are always 48 fangs lining its mouth.', 'romfs:/sprites/159.png', 65, 80, 80, 59, 63, 58, 'medium-slow', 'torrent', 'sheer-force', NULL, 18);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (160, 'Feraligatr', 'Water', NULL, 'Johto', 'JOHTO', 'When it bites with its massive and powerful jaws, it shakes its head and savagely tears its victim up.', 'romfs:/sprites/160.png', 85, 105, 100, 79, 83, 78, 'medium-slow', 'torrent', 'sheer-force', NULL, 30);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (161, 'Sentret', 'Normal', NULL, 'Johto', 'JOHTO', 'A very cautious POKéMON, it raises itself up using its tail to get a better view of its surroundings.', 'romfs:/sprites/161.png', 35, 46, 34, 35, 45, 20, 'medium', 'run-away', 'keen-eye', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (162, 'Furret', 'Normal', NULL, 'Johto', 'JOHTO', 'It makes a nest to suit its long and skinny body. The nest is impossible for other POKéMON to enter.', 'romfs:/sprites/162.png', 85, 76, 64, 45, 55, 90, 'medium', 'run-away', 'keen-eye', NULL, 15);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (163, 'Hoothoot', 'Normal', 'Flying', 'Johto', 'JOHTO', 'It always stands on one foot. It changes feet so fast, the movement can rarely be seen.', 'romfs:/sprites/163.png', 60, 30, 30, 36, 56, 50, 'medium', 'insomnia', 'keen-eye', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (164, 'Noctowl', 'Normal', 'Flying', 'Johto', 'JOHTO', 'Its eyes are specially adapted. They concentrate even faint light and enable it to see in the dark.', 'romfs:/sprites/164.png', 100, 50, 50, 86, 96, 70, 'medium', 'insomnia', 'keen-eye', NULL, 20);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (165, 'Ledyba', 'Bug', 'Flying', 'Johto', 'JOHTO', 'It is very timid. It will be afraid to move if it is alone. But it will be active if it is in a group.', 'romfs:/sprites/165.png', 40, 20, 30, 40, 80, 55, 'fast', 'swarm', 'early-bird', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (166, 'Ledian', 'Bug', 'Flying', 'Johto', 'JOHTO', 'When the stars flicker in the night sky, it flutters about, scattering a glowing powder.', 'romfs:/sprites/166.png', 55, 35, 50, 55, 110, 85, 'fast', 'swarm', 'early-bird', NULL, 18);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (167, 'Spinarak', 'Bug', 'Poison', 'Johto', 'JOHTO', 'It lies still in the same pose for days in its web, waiting for its unsuspecting prey to wander close.', 'romfs:/sprites/167.png', 40, 60, 40, 40, 40, 30, 'fast', 'swarm', 'insomnia', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (168, 'Ariados', 'Bug', 'Poison', 'Johto', 'JOHTO', 'It spins string not only from its rear but also from its mouth. It is hard to tell which end is which.', 'romfs:/sprites/168.png', 70, 90, 70, 60, 70, 40, 'fast', 'swarm', 'insomnia', NULL, 22);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (169, 'Crobat', 'Poison', 'Flying', 'Johto', 'JOHTO', 'It flies so si­ lently through the dark on its four wings that it may not be noticed even when nearby.', 'romfs:/sprites/169.png', 85, 90, 80, 70, 80, 130, 'medium', 'inner-focus', 'infiltrator', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (170, 'Chinchou', 'Water', 'Electric', 'Johto', 'JOHTO', 'Chinchou blink their shining antennae at one another to claim their respective turf.', 'romfs:/sprites/170.png', 75, 38, 38, 56, 56, 67, 'slow', 'volt-absorb', 'illuminate', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (171, 'Lanturn', 'Water', 'Electric', 'Johto', 'JOHTO', 'The light it emits is so bright that it can illuminate the sea''s surface from a depth of over three miles.', 'romfs:/sprites/171.png', 125, 58, 58, 76, 76, 67, 'slow', 'volt-absorb', 'illuminate', NULL, 27);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (172, 'Pichu', 'Electric', NULL, 'Johto', 'JOHTO', 'It is not yet skilled at storing electricity. It may send out a jolt if amused or startled.', 'romfs:/sprites/172.png', 20, 40, 15, 35, 35, 60, 'medium', 'static', 'lightning-rod', NULL, NULL);
