INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (189, 'Jumpluff', 'Grass', 'Flying', 'Johto', 'JOHTO', 'Once it catches the wind, it deft­ ly controls its cotton-puff spores to float, even around the world.', 'romfs:/sprites/189.png', 75, 55, 70, 55, 95, 110, 'medium-slow', 'chlorophyll', 'leaf-guard', NULL, 27);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (190, 'Aipom', 'Normal', NULL, 'Johto', 'JOHTO', 'Its tail is so powerful that it can use it to grab a tree branch and hold itself up in the air.', 'romfs:/sprites/190.png', 55, 70, 55, 40, 55, 85, 'fast', 'run-away', 'pickup', NULL, NULL);
