INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (193, 'Yanma', 'Bug', 'Flying', 'Johto', 'JOHTO', 'If it flaps its wings really fast, it can generate shock waves that will shatter win­ dows in the area.', 'romfs:/sprites/193.png', 65, 65, 45, 75, 45, 95, 'medium', 'speed-boost', 'compound-eyes', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (194, 'Wooper', 'Water', 'Ground', 'Johto', 'JOHTO', 'This POKéMON lives in cold water. It will leave the water to search for food when it gets cold outside.', 'romfs:/sprites/194.png', 55, 45, 45, 25, 25, 15, 'medium', 'damp', 'water-absorb', NULL, NULL);
