INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (196, 'Espeon', 'Psychic', NULL, 'Johto', 'JOHTO', 'It uses the fine hair that covers its body to sense air currents and predict its ene­ my''s actions.', 'romfs:/sprites/196.png', 65, 65, 60, 130, 95, 110, 'medium', 'synchronize', 'magic-bounce', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (197, 'Umbreon', 'Dark', NULL, 'Johto', 'JOHTO', 'When agitated, this POKéMON pro­ tects itself by spraying poisonous sweat from its pores.', 'romfs:/sprites/197.png', 95, 65, 110, 60, 130, 65, 'medium', 'synchronize', 'inner-focus', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (198, 'Murkrow', 'Dark', 'Flying', 'Johto', 'JOHTO', 'Feared and loathed by many, it is believed to bring misfortune to all those who see it at night.', 'romfs:/sprites/198.png', 60, 85, 42, 85, 42, 91, 'medium-slow', 'insomnia', 'super-luck', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (199, 'Slowking', 'Water', 'Psychic', 'Johto', 'JOHTO', 'It has incredible intellect and in­ tuition. Whatever the situation, it remains calm and collected.', 'romfs:/sprites/199.png', 95, 75, 80, 100, 110, 30, 'medium', 'oblivious', 'own-tempo', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (200, 'Misdreavus', 'Ghost', NULL, 'Johto', 'JOHTO', 'It likes playing mischievous tricks such as screaming and wailing to startle people at night.', 'romfs:/sprites/200.png', 60, 60, 60, 85, 85, 85, 'fast', 'levitate', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (201, 'Unown', 'Psychic', NULL, 'Johto', 'JOHTO', 'Their shapes look like hieroglyphs on ancient tab­ lets. It is said that the two are somehow related.', 'romfs:/sprites/201.png', 48, 72, 48, 72, 48, 48, 'medium', 'levitate', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (202, 'Wobbuffet', 'Psychic', NULL, 'Johto', 'JOHTO', 'It hates light and shock. If attack­ ed, it inflates its body to pump up its counter­ strike.', 'romfs:/sprites/202.png', 190, 33, 58, 33, 58, 33, 'medium', 'shadow-tag', 'telepathy', NULL, 15);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (203, 'Girafarig', 'Normal', 'Psychic', 'Johto', 'JOHTO', 'Its tail has a small brain of its own. Beware! If you get close, it may react to your scent and bite.', 'romfs:/sprites/203.png', 70, 80, 65, 90, 65, 85, 'medium', 'inner-focus', 'early-bird', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (204, 'Pineco', 'Bug', NULL, 'Johto', 'JOHTO', 'It likes to make its shell thicker by adding layers of tree bark. The additional weight doesn''t bother it.', 'romfs:/sprites/204.png', 50, 65, 90, 35, 35, 15, 'medium', 'sturdy', 'overcoat', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (205, 'Forretress', 'Bug', 'Steel', 'Johto', 'JOHTO', 'Its entire body is shielded by a steel-hard shell. What lurks inside the armor is a total mystery.', 'romfs:/sprites/205.png', 75, 90, 140, 60, 60, 40, 'medium', 'sturdy', 'overcoat', NULL, 31);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (206, 'Dunsparce', 'Normal', NULL, 'Johto', 'JOHTO', 'When spotted, this POKéMON escapes backward by furi­ ously boring into the ground with its tail.', 'romfs:/sprites/206.png', 100, 70, 70, 65, 65, 45, 'medium', 'serene-grace', 'run-away', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (207, 'Gligar', 'Ground', 'Flying', 'Johto', 'JOHTO', 'It flies straight at its target''s face then clamps down on the star­ tled victim to inject poison.', 'romfs:/sprites/207.png', 65, 75, 105, 35, 65, 85, 'medium-slow', 'hyper-cutter', 'sand-veil', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (208, 'Steelix', 'Steel', 'Ground', 'Johto', 'JOHTO', 'It is thought its body transformed as a result of iron accumulating internally from swallowing soil.', 'romfs:/sprites/208.png', 75, 85, 200, 55, 65, 30, 'medium', 'rock-head', 'sturdy', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (209, 'Snubbull', 'Fairy', NULL, 'Johto', 'JOHTO', 'Although it looks frightening, it is actually kind and affectionate. It is very popular among women.', 'romfs:/sprites/209.png', 60, 80, 50, 40, 40, 30, 'fast', 'intimidate', 'run-away', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (210, 'Granbull', 'Fairy', NULL, 'Johto', 'JOHTO', 'It is actually timid and easily spooked. If at­ tacked, it flails about to fend off its attacker.', 'romfs:/sprites/210.png', 90, 120, 75, 60, 60, 45, 'fast', 'intimidate', 'quick-feet', NULL, 23);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (211, 'Qwilfish', 'Water', 'Poison', 'Johto', 'JOHTO', 'To fire its poison spikes, it must inflate its body by drinking over 2.6 gallons of water all at once.', 'romfs:/sprites/211.png', 65, 95, 85, 55, 55, 85, 'medium', 'poison-point', 'swift-swim', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (212, 'Scizor', 'Bug', 'Steel', 'Johto', 'JOHTO', 'It has a steel-hard body. It intimidates foes by upraising its eye-patterned pincers.', 'romfs:/sprites/212.png', 70, 130, 100, 55, 80, 65, 'medium', 'swarm', 'technician', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (213, 'Shuckle', 'Bug', 'Rock', 'Johto', 'JOHTO', 'The BERRIES it stores in its vase-like shell decompose and become a gooey liquid.', 'romfs:/sprites/213.png', 20, 10, 230, 10, 230, 5, 'medium-slow', 'sturdy', 'gluttony', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (214, 'Heracross', 'Bug', 'Fighting', 'Johto', 'JOHTO', 'It is usually docile, but if it is disturbed while sipping honey, it chases off the intruder with its horn.', 'romfs:/sprites/214.png', 80, 125, 75, 40, 95, 85, 'slow', 'swarm', 'guts', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (215, 'Sneasel', 'Dark', 'Ice', 'Johto', 'JOHTO', 'Its paws conceal sharp claws. If attacked, it sud­ denly extends the claws and startles its enemy.', 'romfs:/sprites/215.png', 55, 95, 55, 35, 75, 115, 'medium-slow', 'inner-focus', 'keen-eye', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (216, 'Teddiursa', 'Normal', NULL, 'Johto', 'JOHTO', 'If it finds honey, its crescent mark glows. It always licks its paws because they are soaked with honey.', 'romfs:/sprites/216.png', 60, 80, 50, 50, 50, 40, 'medium', 'pickup', 'quick-feet', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (217, 'Ursaring', 'Normal', NULL, 'Johto', 'JOHTO', 'Although it is a good climber, it prefers to snap trees with its forelegs and eat fallen BERRIES.', 'romfs:/sprites/217.png', 90, 130, 75, 75, 75, 55, 'medium', 'guts', 'quick-feet', NULL, 30);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (218, 'Slugma', 'Fire', NULL, 'Johto', 'JOHTO', 'It never sleeps. It has to keep moving because if it stopped, its magma body would cool and harden.', 'romfs:/sprites/218.png', 40, 40, 40, 70, 40, 20, 'medium', 'magma-armor', 'flame-body', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (219, 'Magcargo', 'Fire', 'Rock', 'Johto', 'JOHTO', 'The shell on its back is just skin that has cooled and hardened. It breaks easily with a slight touch.', 'romfs:/sprites/219.png', 60, 50, 120, 90, 80, 30, 'medium', 'magma-armor', 'flame-body', NULL, 38);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (220, 'Swinub', 'Ice', 'Ground', 'Johto', 'JOHTO', 'It rubs its snout on the ground to find and dig up food. It sometimes discovers hot springs.', 'romfs:/sprites/220.png', 50, 50, 40, 30, 30, 50, 'slow', 'oblivious', 'snow-cloak', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (221, 'Piloswine', 'Ice', 'Ground', 'Johto', 'JOHTO', 'Because the long hair all over its body obscures its sight, it just keeps charging repeatedly.', 'romfs:/sprites/221.png', 100, 100, 80, 60, 60, 50, 'slow', 'oblivious', 'snow-cloak', NULL, 33);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (222, 'Corsola', 'Water', 'Rock', 'Johto', 'JOHTO', 'It continuously sheds and grows. The tip of its head is prized as a treasure for its beauty.', 'romfs:/sprites/222.png', 65, 55, 95, 65, 95, 35, 'fast', 'hustle', 'natural-cure', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (223, 'Remoraid', 'Water', NULL, 'Johto', 'JOHTO', 'It has superb ac­ curacy. The water it shoots out can strike even moving prey from more than 300 feet.', 'romfs:/sprites/223.png', 35, 65, 35, 65, 35, 65, 'medium', 'hustle', 'sniper', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (224, 'Octillery', 'Water', NULL, 'Johto', 'JOHTO', 'It traps enemies with its suction- cupped tentacles then smashes them with its rock-hard head.', 'romfs:/sprites/224.png', 75, 105, 75, 105, 75, 45, 'medium', 'suction-cups', 'sniper', NULL, 25);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (225, 'Delibird', 'Ice', 'Flying', 'Johto', 'JOHTO', 'It carries food all day long. There are tales about lost people who were saved by the food it had.', 'romfs:/sprites/225.png', 45, 55, 45, 65, 45, 75, 'fast', 'vital-spirit', 'hustle', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (226, 'Mantine', 'Water', 'Flying', 'Johto', 'JOHTO', 'As it majestically swims, it doesn''t care if REMORAID attach to it for scavenging its leftovers.', 'romfs:/sprites/226.png', 85, 40, 70, 80, 140, 70, 'slow', 'swift-swim', 'water-absorb', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (227, 'Skarmory', 'Steel', 'Flying', 'Johto', 'JOHTO', 'Its sturdy wings look heavy, but they are actually hollow and light, allowing it to fly freely in the sky.', 'romfs:/sprites/227.png', 65, 80, 140, 40, 70, 70, 'slow', 'keen-eye', 'sturdy', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (228, 'Houndour', 'Dark', 'Fire', 'Johto', 'JOHTO', 'It uses different kinds of cries for communicating with others of its kind and for pursuing its prey.', 'romfs:/sprites/228.png', 45, 60, 30, 80, 50, 65, 'slow', 'early-bird', 'flash-fire', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (229, 'Houndoom', 'Dark', 'Fire', 'Johto', 'JOHTO', 'If you are burned by the flames it shoots from its mouth, the pain will never go away.', 'romfs:/sprites/229.png', 75, 90, 50, 110, 80, 95, 'slow', 'early-bird', 'flash-fire', NULL, 24);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (230, 'Kingdra', 'Water', 'Dragon', 'Johto', 'JOHTO', 'It is said that it usually hides in underwater caves. It can create whirlpools by yawning.', 'romfs:/sprites/230.png', 75, 95, 95, 95, 95, 85, 'medium', 'swift-swim', 'sniper', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (231, 'Phanpy', 'Ground', NULL, 'Johto', 'JOHTO', 'It swings its long snout around play­ fully, but because it is so strong, that can be dan­ gerous.', 'romfs:/sprites/231.png', 90, 60, 60, 40, 40, 40, 'medium', 'pickup', 'sand-veil', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (232, 'Donphan', 'Ground', NULL, 'Johto', 'JOHTO', 'It has sharp, hard tusks and a rugged hide. Its TACKLE is strong enough to knock down a house.', 'romfs:/sprites/232.png', 90, 120, 120, 60, 60, 50, 'medium', 'sturdy', 'sand-veil', NULL, 25);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (233, 'Porygon2', 'Normal', NULL, 'Johto', 'JOHTO', 'This upgraded version of PORYGON is designed for space exploration. It can''t fly, though.', 'romfs:/sprites/233.png', 85, 80, 90, 105, 95, 60, 'medium', 'trace', 'download', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (234, 'Stantler', 'Normal', NULL, 'Johto', 'JOHTO', 'The curved antlers subtly change the flow of air to create a strange space where real­ ity is distorted.', 'romfs:/sprites/234.png', 73, 95, 62, 85, 65, 85, 'slow', 'intimidate', 'frisk', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (235, 'Smeargle', 'Normal', NULL, 'Johto', 'JOHTO', 'A special fluid oozes from the tip of its tail. It paints the fluid everywhere to mark its territory.', 'romfs:/sprites/235.png', 55, 20, 35, 20, 45, 75, 'fast', 'own-tempo', 'technician', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (236, 'Tyrogue', 'Fighting', NULL, 'Johto', 'JOHTO', 'It is always bursting with en­ ergy. To make it­ self stronger, it keeps on fighting even if it loses.', 'romfs:/sprites/236.png', 35, 35, 35, 35, 35, 35, 'medium', 'guts', 'steadfast', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (237, 'Hitmontop', 'Fighting', NULL, 'Johto', 'JOHTO', 'If you become enchanted by its smooth, elegant, dance-like kicks, you may get drilled hard.', 'romfs:/sprites/237.png', 50, 95, 95, 35, 110, 70, 'medium', 'intimidate', 'technician', NULL, 20);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (238, 'Smoochum', 'Ice', 'Psychic', 'Johto', 'JOHTO', 'Its lips are the most sensitive parts on its body. It always uses its lips first to examine things.', 'romfs:/sprites/238.png', 45, 30, 15, 85, 65, 65, 'medium', 'oblivious', 'forewarn', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (239, 'Elekid', 'Electric', NULL, 'Johto', 'JOHTO', 'It rotates its arms to generate electricity, but it tires easily, so it charges up only a little bit.', 'romfs:/sprites/239.png', 45, 63, 37, 65, 55, 95, 'medium', 'static', 'vital-spirit', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (240, 'Magby', 'Fire', NULL, 'Johto', 'JOHTO', 'Each and every time it inhales and exhales, hot embers dribble out of its mouth and nostrils.', 'romfs:/sprites/240.png', 45, 75, 37, 70, 55, 83, 'medium', 'flame-body', 'vital-spirit', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (241, 'Miltank', 'Normal', NULL, 'Johto', 'JOHTO', 'Its milk is packed with nutrition, making it the ultimate beverage for the sick or weary.', 'romfs:/sprites/241.png', 95, 80, 105, 40, 70, 100, 'slow', 'thick-fat', 'scrappy', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (242, 'Blissey', 'Normal', NULL, 'Johto', 'JOHTO', 'Anyone who takes even one bite of BLISSEY''s egg be­ comes unfailingly caring and pleas­ ant to everyone.', 'romfs:/sprites/242.png', 255, 10, 10, 75, 135, 55, 'fast', 'natural-cure', 'serene-grace', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (243, 'Raikou', 'Electric', NULL, 'Johto', 'JOHTO', 'The rain clouds it carries let it fire thunderbolts at will. They say that it descended with lightning.', 'romfs:/sprites/243.png', 90, 85, 75, 115, 100, 115, 'slow', 'pressure', 'inner-focus', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (244, 'Entei', 'Fire', NULL, 'Johto', 'JOHTO', 'Volcanoes erupt when it barks. Un­ able to restrain its extreme power, it races headlong around the land.', 'romfs:/sprites/244.png', 115, 115, 85, 90, 75, 100, 'slow', 'pressure', 'inner-focus', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (245, 'Suicune', 'Water', NULL, 'Johto', 'JOHTO', 'It races around the world to purify fouled water. It dashes away with the north wind.', 'romfs:/sprites/245.png', 100, 75, 115, 90, 115, 85, 'slow', 'pressure', 'inner-focus', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (246, 'Larvitar', 'Rock', 'Ground', 'Johto', 'JOHTO', 'It feeds on soil. After it has eaten a large mountain, it will fall asleep so it can grow.', 'romfs:/sprites/246.png', 50, 64, 50, 45, 50, 41, 'slow', 'guts', 'sand-veil', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (247, 'Pupitar', 'Rock', 'Ground', 'Johto', 'JOHTO', 'Its shell is as hard as sheet rock, and it is also very strong. Its THRASHING can topple a mountain.', 'romfs:/sprites/247.png', 70, 84, 70, 65, 70, 51, 'slow', 'shed-skin', NULL, NULL, 30);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (248, 'Tyranitar', 'Rock', 'Dark', 'Johto', 'JOHTO', 'Its body can''t be harmed by any sort of attack, so it is very eager to make challenges against enemies.', 'romfs:/sprites/248.png', 100, 134, 110, 95, 100, 61, 'slow', 'sand-stream', 'unnerve', NULL, 55);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (249, 'Lugia', 'Psychic', 'Flying', 'Johto', 'JOHTO', 'It is said that it quietly spends its time deep at the bottom of the sea because its powers are too strong.', 'romfs:/sprites/249.png', 106, 90, 130, 90, 154, 110, 'slow', 'pressure', 'multiscale', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (250, 'Ho-oh', 'Fire', 'Flying', 'Johto', 'JOHTO', 'Legends claim this POKéMON flies the world''s skies con­ tinuously on its magnificent seven- colored wings.', 'romfs:/sprites/250.png', 106, 130, 90, 110, 154, 90, 'slow', 'pressure', 'regenerator', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (251, 'Celebi', 'Psychic', 'Grass', 'Johto', 'JOHTO', 'This POKéMON wan­ ders across time. Grass and trees flourish in the forests in which it has appeared.', 'romfs:/sprites/251.png', 100, 100, 100, 100, 100, 100, 'medium-slow', 'natural-cure', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (252, 'Treecko', 'Grass', NULL, 'Hoenn', 'HOENN', 'TREECKO has small hooks on the bottom of its feet that enable it to scale vertical walls. This POKéMON attacks by slamming foes with its thick tail.', 'romfs:/sprites/252.png', 40, 45, 35, 65, 55, 70, 'medium-slow', 'overgrow', 'unburden', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (253, 'Grovyle', 'Grass', NULL, 'Hoenn', 'HOENN', 'The leaves growing out of GROVYLE’s body are convenient for camouflaging it from enemies in the forest. This POKéMON is a master at climbing trees in jungles.', 'romfs:/sprites/253.png', 50, 65, 45, 85, 65, 95, 'medium-slow', 'overgrow', 'unburden', NULL, 16);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (254, 'Sceptile', 'Grass', NULL, 'Hoenn', 'HOENN', 'The leaves growing on SCEPTILE’s body are very sharp edged. This POKéMON is very agile - it leaps all over the branches of trees and jumps on its foe from above or behind.', 'romfs:/sprites/254.png', 70, 85, 65, 105, 85, 120, 'medium-slow', 'overgrow', 'unburden', NULL, 36);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (255, 'Torchic', 'Fire', NULL, 'Hoenn', 'HOENN', 'TORCHIC sticks with its TRAINER, following behind with unsteady steps. This POKéMON breathes fire of over 1,800 degrees F, including fireballs that leave the foe scorched black.', 'romfs:/sprites/255.png', 45, 60, 40, 70, 50, 45, 'medium-slow', 'blaze', 'speed-boost', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (256, 'Combusken', 'Fire', 'Fighting', 'Hoenn', 'HOENN', 'COMBUSKEN toughens up its legs and thighs by running through fields and mountains. This POKéMON’s legs possess both speed and power, enabling it to dole out ten kicks in one second.', 'romfs:/sprites/256.png', 60, 85, 60, 85, 60, 55, 'medium-slow', 'blaze', 'speed-boost', NULL, 16);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (257, 'Blaziken', 'Fire', 'Fighting', 'Hoenn', 'HOENN', 'In battle, BLAZIKEN blows out intense flames from its wrists and attacks foes courageously. The stronger the foe, the more intensely this POKéMON’s wrists burn.', 'romfs:/sprites/257.png', 80, 120, 70, 110, 70, 80, 'medium-slow', 'blaze', 'speed-boost', NULL, 36);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (258, 'Mudkip', 'Water', NULL, 'Hoenn', 'HOENN', 'The fin on MUDKIP’s head acts as highly sensitive radar. Using this fin to sense movements of water and air, this POKéMON can determine what is taking place around it without using its eyes.', 'romfs:/sprites/258.png', 50, 70, 50, 50, 50, 40, 'medium-slow', 'torrent', 'damp', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (259, 'Marshtomp', 'Water', 'Ground', 'Hoenn', 'HOENN', 'The surface of MARSHTOMP’s body is enveloped by a thin, sticky film that enables it to live on land. This POKéMON plays in mud on beaches when the ocean tide is low.', 'romfs:/sprites/259.png', 70, 85, 70, 60, 70, 50, 'medium-slow', 'torrent', 'damp', NULL, 16);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (260, 'Swampert', 'Water', 'Ground', 'Hoenn', 'HOENN', 'SWAMPERT is very strong. It has enough power to easily drag a boulder weighing more than a ton. This POKéMON also has powerful vision that lets it see even in murky water.', 'romfs:/sprites/260.png', 100, 110, 90, 85, 90, 60, 'medium-slow', 'torrent', 'damp', NULL, 36);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (261, 'Poochyena', 'Dark', NULL, 'Hoenn', 'HOENN', 'At first sight, POOCHYENA takes a bite at anything that moves. This POKéMON chases after prey until the victim becomes exhausted. However, it may turn tail if the prey strikes back.', 'romfs:/sprites/261.png', 35, 55, 35, 30, 30, 35, 'medium', 'run-away', 'quick-feet', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (262, 'Mightyena', 'Dark', NULL, 'Hoenn', 'HOENN', 'MIGHTYENA gives obvious signals when it is preparing to attack. It starts to growl deeply and then flattens its body. This POKéMON will bite savagely with its sharply pointed fangs.', 'romfs:/sprites/262.png', 70, 90, 70, 60, 60, 70, 'medium', 'intimidate', 'quick-feet', NULL, 18);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (263, 'Zigzagoon', 'Normal', NULL, 'Hoenn', 'HOENN', 'ZIGZAGOON restlessly wanders everywhere at all times. This POKéMON does so because it is very curious. It becomes interested in anything that it happens to see.', 'romfs:/sprites/263.png', 38, 30, 41, 30, 41, 60, 'medium', 'pickup', 'gluttony', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (264, 'Linoone', 'Normal', NULL, 'Hoenn', 'HOENN', 'LINOONE always runs full speed and only in straight lines. If facing an obstacle, it makes a right-angle turn to evade it. This POKéMON is very challenged by gently curving roads.', 'romfs:/sprites/264.png', 78, 70, 61, 50, 61, 100, 'medium', 'pickup', 'gluttony', NULL, 20);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (265, 'Wurmple', 'Bug', NULL, 'Hoenn', 'HOENN', 'Using the spikes on its rear end,   WURMPLE peels the bark off trees and feeds on the sap that oozes out. This POKéMON’s feet are tipped with suction pads that allow it to cling to glass without slipping.', 'romfs:/sprites/265.png', 45, 45, 35, 20, 30, 20, 'medium', 'shield-dust', 'run-away', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (266, 'Silcoon', 'Bug', NULL, 'Hoenn', 'HOENN', 'SILCOON tethers itself to a tree branch using silk to keep from falling. There,  this POKéMON hangs quietly while it awaits evolution. It peers out of the silk cocoon through a small hole.', 'romfs:/sprites/266.png', 50, 35, 55, 25, 25, 15, 'medium', 'shed-skin', NULL, NULL, 7);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (267, 'Beautifly', 'Bug', 'Flying', 'Hoenn', 'HOENN', 'BEAUTIFLY’s favorite food is the sweet pollen of flowers. If you want to see this POKéMON, just leave a potted flower by an open window. BEAUTIFLY is sure to come looking for pollen.', 'romfs:/sprites/267.png', 60, 70, 50, 100, 50, 65, 'medium', 'swarm', 'rivalry', NULL, 10);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (268, 'Cascoon', 'Bug', NULL, 'Hoenn', 'HOENN', 'CASCOON makes its protective cocoon by wrapping its body entirely with a fine silk from its mouth. Once the silk goes around its body, it hardens. This POKéMON prepares for its evolution inside the cocoon.', 'romfs:/sprites/268.png', 50, 35, 55, 25, 25, 15, 'medium', 'shed-skin', NULL, NULL, 7);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (269, 'Dustox', 'Bug', 'Poison', 'Hoenn', 'HOENN', 'DUSTOX is instinctively drawn to light. Swarms of this POKéMON are attracted by the bright lights of cities, where they wreak havoc by stripping the leaves off roadside trees for food.', 'romfs:/sprites/269.png', 60, 50, 70, 50, 90, 65, 'medium', 'shield-dust', 'compound-eyes', NULL, 10);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (270, 'Lotad', 'Water', 'Grass', 'Hoenn', 'HOENN', 'It searches about for clean water. If it does not drink water for too long, the leaf on its head wilts.', 'romfs:/sprites/270.png', 40, 30, 30, 40, 50, 30, 'medium-slow', 'swift-swim', 'rain-dish', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (271, 'Lombre', 'Water', 'Grass', 'Hoenn', 'HOENN', 'It lives at the water’s edge where it is sunny. It sleeps on a bed of water grass by day and becomes active at night.', 'romfs:/sprites/271.png', 60, 50, 50, 60, 70, 50, 'medium-slow', 'swift-swim', 'rain-dish', NULL, 14);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (272, 'Ludicolo', 'Water', 'Grass', 'Hoenn', 'HOENN', 'LUDICOLO begins dancing as soon as it hears cheerful, festive music. This POKéMON is said to appear when it hears the singing of children on hiking outings.', 'romfs:/sprites/272.png', 80, 70, 70, 90, 100, 70, 'medium-slow', 'swift-swim', 'rain-dish', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (273, 'Seedot', 'Grass', NULL, 'Hoenn', 'HOENN', 'SEEDOT attaches itself to a tree branch using the top of its head. It sucks moisture from the tree while hanging off the branch. The more water it drinks, the glossier this POKéMON’s body becomes.', 'romfs:/sprites/273.png', 40, 40, 50, 30, 30, 30, 'medium-slow', 'chlorophyll', 'early-bird', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (274, 'Nuzleaf', 'Grass', 'Dark', 'Hoenn', 'HOENN', 'NUZLEAF live in densely overgrown forests. They occasionally venture out of the forest to startle people. This POKéMON dislikes having its long nose pinched.', 'romfs:/sprites/274.png', 70, 70, 40, 60, 40, 60, 'medium-slow', 'chlorophyll', 'early-bird', NULL, 14);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (275, 'Shiftry', 'Grass', 'Dark', 'Hoenn', 'HOENN', 'It lives quietly in the deep forest. It is said to create chilly winter winds with the fans it holds.', 'romfs:/sprites/275.png', 90, 100, 60, 90, 60, 80, 'medium-slow', 'chlorophyll', 'wind-rider', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (276, 'Taillow', 'Normal', 'Flying', 'Hoenn', 'HOENN', 'TAILLOW courageously stands its ground against foes, however strong they may be. This gutsy POKéMON will remain defiant even after a loss. On the other hand, it cries loudly if it becomes hungry.', 'romfs:/sprites/276.png', 40, 55, 30, 30, 30, 85, 'medium-slow', 'guts', 'scrappy', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (277, 'Swellow', 'Normal', 'Flying', 'Hoenn', 'HOENN', 'SWELLOW flies high above our heads, making graceful arcs in the sky. This POKéMON dives at a steep angle as soon as it spots its prey. The hapless prey is tightly grasped by SWELLOW’s clawed feet, preventing escape.', 'romfs:/sprites/277.png', 60, 85, 60, 75, 50, 125, 'medium-slow', 'guts', 'scrappy', NULL, 22);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (278, 'Wingull', 'Water', 'Flying', 'Hoenn', 'HOENN', 'WINGULL has the habit of carrying prey and valuables in its beak and hiding them in all sorts of locations. This POKéMON rides the winds and flies as if it were skating across the sky.', 'romfs:/sprites/278.png', 40, 30, 30, 55, 30, 85, 'medium', 'keen-eye', 'hydration', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (279, 'Pelipper', 'Water', 'Flying', 'Hoenn', 'HOENN', 'It is a messenger of the skies, carrying small Pokémon and eggs to safety in its bill.', 'romfs:/sprites/279.png', 60, 50, 100, 95, 70, 65, 'medium', 'keen-eye', 'drizzle', NULL, 25);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (280, 'Ralts', 'Psychic', 'Fairy', 'Hoenn', 'HOENN', 'RALTS senses the emotions of people using the horns on its head. This POKéMON rarely appears before people. But when it does, it draws closer if it senses that the person has a positive disposition.', 'romfs:/sprites/280.png', 28, 25, 25, 45, 35, 40, 'slow', 'synchronize', 'trace', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (281, 'Kirlia', 'Psychic', 'Fairy', 'Hoenn', 'HOENN', 'It is said that a KIRLIA that is exposed to the positive emotions of its TRAINER grows beautiful. This POKéMON controls psychokinetic powers with its highly developed brain.', 'romfs:/sprites/281.png', 38, 35, 35, 65, 55, 50, 'slow', 'synchronize', 'trace', NULL, 20);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (282, 'Gardevoir', 'Psychic', 'Fairy', 'Hoenn', 'HOENN', 'GARDEVOIR has the ability to read the future. If it senses impending danger to its TRAINER, this POKéMON is said to unleash its psychokinetic energy at full power.', 'romfs:/sprites/282.png', 68, 65, 65, 125, 115, 80, 'slow', 'synchronize', 'trace', NULL, 30);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (283, 'Surskit', 'Bug', 'Water', 'Hoenn', 'HOENN', 'From the tips of its feet, SURSKIT secretes an oil that enables it to walk on water as if it were skating. This POKéMON feeds on microscopic organisms in ponds and lakes.', 'romfs:/sprites/283.png', 40, 30, 32, 50, 52, 65, 'medium', 'swift-swim', 'rain-dish', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (284, 'Masquerain', 'Bug', 'Flying', 'Hoenn', 'HOENN', 'MASQUERAIN intimidates enemies with the eyelike patterns on its antennas. This POKéMON flaps its four wings to freely fly in any direction - even sideways and backwards - as if it were a helicopter.', 'romfs:/sprites/284.png', 70, 60, 62, 100, 82, 80, 'medium', 'intimidate', 'unnerve', NULL, 22);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (285, 'Shroomish', 'Grass', NULL, 'Hoenn', 'HOENN', 'SHROOMISH live in damp soil in the dark depths of forests. They are often found keeping still under fallen leaves. This POKéMON feeds on compost that is made up of fallen, rotted leaves.', 'romfs:/sprites/285.png', 60, 40, 60, 40, 60, 35, 'fast-then-very-slow', 'effect-spore', 'poison-heal', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (286, 'Breloom', 'Grass', 'Fighting', 'Hoenn', 'HOENN', 'BRELOOM closes in on its foe with light and sprightly footwork, then throws punches with its stretchy arms. This POKéMON’s fighting technique puts boxers to shame.', 'romfs:/sprites/286.png', 60, 130, 80, 60, 60, 70, 'fast-then-very-slow', 'effect-spore', 'poison-heal', NULL, 23);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (287, 'Slakoth', 'Normal', NULL, 'Hoenn', 'HOENN', 'SLAKOTH lolls around for over twenty hours every day. Because it moves so little, it does not need much food. This POKéMON’s sole daily meal consists of just three leaves.', 'romfs:/sprites/287.png', 60, 60, 60, 35, 35, 30, 'slow', 'truant', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (288, 'Vigoroth', 'Normal', NULL, 'Hoenn', 'HOENN', 'VIGOROTH is always itching and agitated to go on a wild rampage. It simply can’t tolerate sitting still for even a minute. This POKéMON’s stress level rises if it can’t be moving constantly.', 'romfs:/sprites/288.png', 80, 80, 80, 55, 55, 90, 'slow', 'vital-spirit', NULL, NULL, 18);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (289, 'Slaking', 'Normal', NULL, 'Hoenn', 'HOENN', 'SLAKING spends all day lying down and lolling about. It eats grass growing within its reach. If it eats all the grass it can reach, this POKéMON reluctantly moves to another spot.', 'romfs:/sprites/289.png', 150, 160, 100, 95, 65, 100, 'slow', 'truant', NULL, NULL, 36);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (290, 'Nincada', 'Bug', 'Ground', 'Hoenn', 'HOENN', 'NINCADA lives underground for many years in complete darkness. This POKéMON absorbs nutrients from the roots of trees. It stays motionless as it waits for evolution.', 'romfs:/sprites/290.png', 31, 45, 90, 30, 30, 40, 'slow-then-very-fast', 'compound-eyes', 'run-away', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (291, 'Ninjask', 'Bug', 'Flying', 'Hoenn', 'HOENN', 'NINJASK moves around at such a high speed that it cannot be seen, even while its crying can be clearly heard. For that reason, this POKéMON was long believed to be invisible.', 'romfs:/sprites/291.png', 61, 90, 45, 50, 50, 160, 'slow-then-very-fast', 'speed-boost', 'infiltrator', NULL, 20);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (292, 'Shedinja', 'Bug', 'Ghost', 'Hoenn', 'HOENN', 'SHEDINJA’s hard body doesn’t move - not even a twitch. In fact, its body appears to be merely a hollow shell. It is believed that this POKéMON will steal the spirit of anyone peering into its hollow body from its back.', 'romfs:/sprites/292.png', 1, 90, 45, 30, 30, 40, 'slow-then-very-fast', 'wonder-guard', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (293, 'Whismur', 'Normal', NULL, 'Hoenn', 'HOENN', 'Normally, WHISMUR’s voice is very quiet - it is barely audible even if one is paying close attention. However, if this POKéMON senses danger, it starts crying at an earsplitting volume.', 'romfs:/sprites/293.png', 64, 51, 23, 51, 23, 28, 'medium-slow', 'soundproof', 'rattled', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (294, 'Loudred', 'Normal', NULL, 'Hoenn', 'HOENN', 'LOUDRED’s bellowing can completely decimate a wood-frame house. It uses its voice to punish its foes. This POKéMON’s round ears serve as loudspeakers.', 'romfs:/sprites/294.png', 84, 71, 43, 71, 43, 48, 'medium-slow', 'soundproof', 'scrappy', NULL, 20);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (295, 'Exploud', 'Normal', NULL, 'Hoenn', 'HOENN', 'EXPLOUD triggers earthquakes with the tremors it creates by bellowing. If this POKéMON violently inhales from the ports on its body, it’s a sign that it is preparing to let loose a huge bellow.', 'romfs:/sprites/295.png', 104, 91, 63, 91, 73, 68, 'medium-slow', 'soundproof', 'scrappy', NULL, 40);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (296, 'Makuhita', 'Fighting', NULL, 'Hoenn', 'HOENN', 'MAKUHITA is tenacious - it will keep getting up and attacking its foe however many times it is knocked down. Every time it gets back up, this POKéMON stores more energy in its body for evolving.', 'romfs:/sprites/296.png', 72, 60, 30, 20, 30, 25, 'fast-then-very-slow', 'thick-fat', 'guts', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (297, 'Hariyama', 'Fighting', NULL, 'Hoenn', 'HOENN', 'It has the habit of challenging others without hesitation to tests of strength. It’s been known to stand on train tracks and stop trains using forearm thrusts.', 'romfs:/sprites/297.png', 144, 120, 60, 40, 60, 50, 'fast-then-very-slow', 'thick-fat', 'guts', NULL, 24);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (298, 'Azurill', 'Normal', 'Fairy', 'Hoenn', 'HOENN', 'A Pokémon that lives by water. It moves quickly on land by bouncing on its big tail.', 'romfs:/sprites/298.png', 50, 20, 40, 20, 40, 20, 'fast', 'thick-fat', 'huge-power', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (299, 'Nosepass', 'Rock', NULL, 'Hoenn', 'HOENN', 'NOSEPASS’s magnetic nose is always pointed to the north. If two of these POKéMON meet, they cannot turn their faces to each other when they are close because their magnetic noses repel one another.', 'romfs:/sprites/299.png', 30, 45, 135, 45, 90, 30, 'medium', 'sturdy', 'magnet-pull', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (300, 'Skitty', 'Normal', NULL, 'Hoenn', 'HOENN', 'SKITTY has the habit of becoming fascinated by moving objects and chasing them around. This POKéMON is known to chase after its own tail and become dizzy.', 'romfs:/sprites/300.png', 50, 45, 45, 35, 35, 50, 'fast', 'cute-charm', 'normalize', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (301, 'Delcatty', 'Normal', NULL, 'Hoenn', 'HOENN', 'DELCATTY prefers to live an unfettered existence in which it can do as it pleases at its own pace. Because this POKéMON eats and sleeps whenever it decides, its daily routines are completely random.', 'romfs:/sprites/301.png', 70, 65, 65, 55, 55, 90, 'fast', 'cute-charm', 'normalize', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (302, 'Sableye', 'Dark', 'Ghost', 'Hoenn', 'HOENN', 'SABLEYE lead quiet lives deep inside caverns. They are feared, however, because these POKéMON are thought to steal the spirits of people when their eyes burn with a sinister glow in the darkness.', 'romfs:/sprites/302.png', 50, 75, 75, 65, 65, 50, 'medium-slow', 'keen-eye', 'stall', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (303, 'Mawile', 'Steel', 'Fairy', 'Hoenn', 'HOENN', 'MAWHILE’s huge jaws are actually steel horns that have been transformed. Its docile-looking face serves to lull its foe into letting down its guard. When the foe least expects it, MAWHILE chomps it with its gaping jaws.', 'romfs:/sprites/303.png', 50, 85, 85, 55, 55, 50, 'fast', 'hyper-cutter', 'intimidate', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (304, 'Aron', 'Steel', 'Rock', 'Hoenn', 'HOENN', 'This POKéMON has a body of steel. To make its body, ARON feeds on iron ore that it digs from mountains. Occasionally, it causes major trouble by eating bridges and rails.', 'romfs:/sprites/304.png', 50, 70, 100, 40, 40, 30, 'slow', 'sturdy', 'rock-head', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (305, 'Lairon', 'Steel', 'Rock', 'Hoenn', 'HOENN', 'LAIRON tempers its steel body by drinking highly nutritious mineral springwater until it is bloated. This POKéMON makes its nest close to springs of delicious water.', 'romfs:/sprites/305.png', 60, 90, 140, 50, 50, 40, 'slow', 'sturdy', 'rock-head', NULL, 32);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (306, 'Aggron', 'Steel', 'Rock', 'Hoenn', 'HOENN', 'AGGRON claims an entire mountain as its own territory. It mercilessly beats up anything that violates its environment. This POKéMON vigilantly patrols its territory at all times.', 'romfs:/sprites/306.png', 70, 110, 180, 60, 60, 50, 'slow', 'sturdy', 'rock-head', NULL, 42);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (307, 'Meditite', 'Fighting', 'Psychic', 'Hoenn', 'HOENN', 'MEDITITE undertakes rigorous mental training deep in the mountains. However, whenever it meditates, this POKéMON always loses its concentration and focus. As a result, its training never ends.', 'romfs:/sprites/307.png', 30, 40, 55, 40, 55, 60, 'medium', 'pure-power', 'telepathy', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (308, 'Medicham', 'Fighting', 'Psychic', 'Hoenn', 'HOENN', 'It is said that through meditation, MEDICHAM heightens energy inside its body and sharpens its sixth sense. This POKéMON hides its presence by merging itself with fields and mountains.', 'romfs:/sprites/308.png', 60, 60, 75, 60, 75, 80, 'medium', 'pure-power', 'telepathy', NULL, 37);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (309, 'Electrike', 'Electric', NULL, 'Hoenn', 'HOENN', 'ELECTRIKE stores electricity in its long body hair. This POKéMON stimulates its leg muscles with electric charges. These jolts of power give its legs explosive acceleration performance.', 'romfs:/sprites/309.png', 40, 45, 40, 65, 40, 65, 'slow', 'static', 'lightning-rod', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (310, 'Manectric', 'Electric', NULL, 'Hoenn', 'HOENN', 'MANECTRIC is constantly discharging electricity from its mane. The sparks sometimes ignite forest fires. When it enters a battle, this POKéMON creates thunderclouds.', 'romfs:/sprites/310.png', 70, 75, 60, 105, 60, 105, 'slow', 'static', 'lightning-rod', NULL, 26);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (311, 'Plusle', 'Electric', NULL, 'Hoenn', 'HOENN', 'PLUSLE always acts as a cheerleader for its partners. Whenever a teammate puts out a good effort in battle, this POKéMON shorts out its body to create the crackling noises of sparks to show its joy.', 'romfs:/sprites/311.png', 60, 50, 40, 85, 75, 95, 'medium', 'plus', 'lightning-rod', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (312, 'Minun', 'Electric', NULL, 'Hoenn', 'HOENN', 'MINUN is more concerned about cheering on its partners than its own safety. It shorts out the electricity in its body to create brilliant showers of sparks to cheer on its teammates.', 'romfs:/sprites/312.png', 60, 40, 50, 75, 85, 95, 'medium', 'minus', 'volt-absorb', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (313, 'Volbeat', 'Bug', NULL, 'Hoenn', 'HOENN', 'With the arrival of night, VOLBEAT emits light from its tail. It communicates with others by adjusting the intensity and flashing of its light. This POKéMON is attracted by the sweet aroma of ILLUMISE.', 'romfs:/sprites/313.png', 65, 73, 75, 47, 85, 85, 'slow-then-very-fast', 'illuminate', 'swarm', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (314, 'Illumise', 'Bug', NULL, 'Hoenn', 'HOENN', 'With its sweet aroma, it guides Volbeat to draw signs with light in the night sky.', 'romfs:/sprites/314.png', 65, 47, 75, 73, 85, 85, 'fast-then-very-slow', 'oblivious', 'tinted-lens', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (315, 'Roselia', 'Grass', 'Poison', 'Hoenn', 'HOENN', 'ROSELIA shoots sharp thorns as projectiles at any opponent that tries to steal the flowers on its arms. The aroma of this POKéMON brings serenity to living things.', 'romfs:/sprites/315.png', 50, 60, 45, 100, 80, 65, 'medium-slow', 'natural-cure', 'poison-point', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (316, 'Gulpin', 'Poison', NULL, 'Hoenn', 'HOENN', 'Virtually all of GULPIN’s body is its stomach. As a result, it can swallow something its own size. This POKéMON’s stomach contains a special fluid that digests anything.', 'romfs:/sprites/316.png', 70, 43, 53, 43, 53, 40, 'fast-then-very-slow', 'liquid-ooze', 'sticky-hold', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (317, 'Swalot', 'Poison', NULL, 'Hoenn', 'HOENN', 'When SWALOT spots prey, it spurts out a hideously toxic fluid from its pores and sprays the target. Once the prey has weakened, this POKéMON gulps it down whole with its cavernous mouth.', 'romfs:/sprites/317.png', 100, 73, 83, 73, 83, 55, 'fast-then-very-slow', 'liquid-ooze', 'sticky-hold', NULL, 26);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (318, 'Carvanha', 'Water', 'Dark', 'Hoenn', 'HOENN', 'CARVANHA’s strongly developed jaws and its sharply pointed fangs pack the destructive power to rip out boat hulls. Many boats have been attacked and sunk by this POKéMON.', 'romfs:/sprites/318.png', 45, 90, 20, 65, 20, 65, 'slow', 'rough-skin', 'speed-boost', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (319, 'Sharpedo', 'Water', 'Dark', 'Hoenn', 'HOENN', 'Nicknamed “the bully of the sea,” SHARPEDO is widely feared. Its cruel fangs grow back immediately if they snap off. Just one of these POKéMON can thoroughly tear apart a supertanker.', 'romfs:/sprites/319.png', 70, 120, 40, 95, 40, 95, 'slow', 'rough-skin', 'speed-boost', NULL, 30);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (320, 'Wailmer', 'Water', NULL, 'Hoenn', 'HOENN', 'WAILMER’s nostrils are located above its eyes. This playful POKéMON loves to startle people by forcefully snorting out seawater it stores inside its body out of its nostrils.', 'romfs:/sprites/320.png', 130, 70, 35, 70, 35, 60, 'fast-then-very-slow', 'water-veil', 'oblivious', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (321, 'Wailord', 'Water', NULL, 'Hoenn', 'HOENN', 'WAILORD is the largest of all identified POKéMON up to now. This giant POKéMON swims languorously in the vast open sea, eating massive amounts of food at once with its enormous mouth.', 'romfs:/sprites/321.png', 170, 90, 45, 90, 45, 60, 'fast-then-very-slow', 'water-veil', 'oblivious', NULL, 40);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (322, 'Numel', 'Fire', 'Ground', 'Hoenn', 'HOENN', 'NUMEL is extremely dull witted - it doesn’t notice being hit. However, it can’t stand hunger for even a second. This POKéMON’s body is a seething cauldron of boiling magma.', 'romfs:/sprites/322.png', 60, 60, 40, 65, 45, 35, 'medium', 'oblivious', 'simple', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (323, 'Camerupt', 'Fire', 'Ground', 'Hoenn', 'HOENN', 'CAMERUPT has a volcano inside its body. Magma of 18,000 degrees F courses through its body. Occasionally, the humps on this POKéMON’s back erupt, spewing the superheated magma.', 'romfs:/sprites/323.png', 70, 100, 70, 105, 75, 40, 'medium', 'magma-armor', 'solid-rock', NULL, 33);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (324, 'Torkoal', 'Fire', NULL, 'Hoenn', 'HOENN', 'You can tell how it’s feeling by the smoke spouting from its shell. Tremendous velocity is a sign of good health.', 'romfs:/sprites/324.png', 70, 85, 140, 85, 70, 20, 'medium', 'white-smoke', 'drought', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (325, 'Spoink', 'Psychic', NULL, 'Hoenn', 'HOENN', 'SPOINK bounces around on its tail. The shock of its bouncing makes its heart pump. As a result, this POKéMON cannot afford to stop bouncing - if it stops, its heart will stop.', 'romfs:/sprites/325.png', 60, 25, 35, 70, 80, 60, 'fast', 'thick-fat', 'own-tempo', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (326, 'Grumpig', 'Psychic', NULL, 'Hoenn', 'HOENN', 'GRUMPIG uses the black pearls on its body to amplify its psychic power waves for gaining total control over its foe. When this POKéMON uses its special power, its snorting breath grows labored.', 'romfs:/sprites/326.png', 80, 45, 65, 90, 110, 80, 'fast', 'thick-fat', 'own-tempo', NULL, 32);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (327, 'Spinda', 'Normal', NULL, 'Hoenn', 'HOENN', 'No two Spinda have the same pattern of spots. Its tottering step fouls the aim of foes.', 'romfs:/sprites/327.png', 60, 60, 60, 60, 60, 60, 'fast', 'own-tempo', 'tangled-feet', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (328, 'Trapinch', 'Ground', NULL, 'Hoenn', 'HOENN', 'TRAPINCH’s nest is a sloped, bowl-like pit dug in sand. This POKéMON patiently waits for prey to tumble down the pit. Its giant jaws have enough strength to crush even boulders.', 'romfs:/sprites/328.png', 45, 100, 45, 45, 45, 10, 'medium-slow', 'hyper-cutter', 'arena-trap', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (329, 'Vibrava', 'Ground', 'Dragon', 'Hoenn', 'HOENN', 'To make prey faint, VIBRAVA generates ultrasonic waves by vigorously making its two wings vibrate. This POKéMON’s ultrasonic waves are so powerful, they can bring on headaches in people.', 'romfs:/sprites/329.png', 50, 70, 50, 50, 50, 70, 'medium-slow', 'levitate', NULL, NULL, 35);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (330, 'Flygon', 'Ground', 'Dragon', 'Hoenn', 'HOENN', 'FLYGON is nicknamed “the elemental  spirit of the desert.” Because its flapping wings whip up a cloud of sand, this POKéMON is always enveloped in a sandstorm while flying.', 'romfs:/sprites/330.png', 80, 100, 80, 80, 80, 100, 'medium-slow', 'levitate', NULL, NULL, 45);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (331, 'Cacnea', 'Grass', NULL, 'Hoenn', 'HOENN', 'CACNEA lives in arid locations such as deserts. It releases a strong aroma from its flower to attract prey. When prey comes near, this POKéMON shoots sharp thorns from its body to bring the victim down.', 'romfs:/sprites/331.png', 50, 85, 40, 85, 40, 35, 'medium-slow', 'sand-veil', 'water-absorb', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (332, 'Cacturne', 'Grass', 'Dark', 'Hoenn', 'HOENN', 'During the daytime, CACTURNE remains unmoving so that it does not lose any moisture to the harsh desert sun. This POKéMON becomes active at night when the temperature drops.', 'romfs:/sprites/332.png', 70, 115, 60, 115, 60, 55, 'medium-slow', 'sand-veil', 'water-absorb', NULL, 32);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (333, 'Swablu', 'Normal', 'Flying', 'Hoenn', 'HOENN', 'SWABLU has light and fluffy wings that are like cottony clouds. This POKéMON is not frightened of people. It lands on the heads of people and sits there like a cotton-fluff hat.', 'romfs:/sprites/333.png', 45, 40, 60, 40, 75, 50, 'slow-then-very-fast', 'natural-cure', 'cloud-nine', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (334, 'Altaria', 'Dragon', 'Flying', 'Hoenn', 'HOENN', 'ALTARIA dances and wheels through the sky among billowing, cotton-like clouds. By singing melodies in its crystal-clear voice, this POKéMON makes its listeners experience dreamy wonderment.', 'romfs:/sprites/334.png', 75, 70, 90, 70, 105, 80, 'slow-then-very-fast', 'natural-cure', 'cloud-nine', NULL, 35);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (335, 'Zangoose', 'Normal', NULL, 'Hoenn', 'HOENN', 'Memories of battling its arch-rival SEVIPER are etched into every cell of ZANGOOSE’s body. This POKéMON adroitly dodges attacks with incredible agility.', 'romfs:/sprites/335.png', 73, 115, 60, 60, 60, 90, 'slow-then-very-fast', 'immunity', 'toxic-boost', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (336, 'Seviper', 'Poison', NULL, 'Hoenn', 'HOENN', 'SEVIPER shares a generations-long feud with ZANGOOSE. The scars on its body are evidence of vicious battles. This POKéMON attacks using its sword- edged tail.', 'romfs:/sprites/336.png', 73, 100, 60, 100, 60, 65, 'fast-then-very-slow', 'shed-skin', 'infiltrator', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (337, 'Lunatone', 'Rock', 'Psychic', 'Hoenn', 'HOENN', 'LUNATONE was discovered at a location where a meteorite fell. As a result, some people theorize that this POKéMON came from space. However, no one has been able to prove this theory so far.', 'romfs:/sprites/337.png', 90, 55, 65, 95, 85, 70, 'fast', 'levitate', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (338, 'Solrock', 'Rock', 'Psychic', 'Hoenn', 'HOENN', 'Solar energy is the source of its power, so it is strong during the daytime. When it spins, its body shines.', 'romfs:/sprites/338.png', 90, 95, 85, 55, 65, 70, 'fast', 'levitate', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (339, 'Barboach', 'Water', 'Ground', 'Hoenn', 'HOENN', 'BARBOACH’s sensitive whiskers serve as a superb radar system. This POKéMON hides in mud, leaving only its two whiskers exposed while it waits for prey to come along.', 'romfs:/sprites/339.png', 50, 48, 43, 46, 41, 60, 'medium', 'oblivious', 'anticipation', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (340, 'Whiscash', 'Water', 'Ground', 'Hoenn', 'HOENN', 'WHISCASH is extremely territorial. Just one of these POKéMON will claim a large pond as its exclusive territory. If a foe approaches it, it thrashes about and triggers a massive earthquake.', 'romfs:/sprites/340.png', 110, 78, 73, 76, 71, 60, 'medium', 'oblivious', 'anticipation', NULL, 30);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (341, 'Corphish', 'Water', NULL, 'Hoenn', 'HOENN', 'Its hardy vitality enables it to adapt to any environment. Its pincers will never release prey.', 'romfs:/sprites/341.png', 43, 80, 65, 50, 35, 35, 'fast-then-very-slow', 'hyper-cutter', 'shell-armor', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (342, 'Crawdaunt', 'Water', 'Dark', 'Hoenn', 'HOENN', 'CRAWDAUNT has an extremely violent nature that compels it to challenge other living things to battle. Other life-forms refuse to live in ponds inhabited by this POKéMON, making them desolate places.', 'romfs:/sprites/342.png', 63, 120, 85, 90, 55, 55, 'fast-then-very-slow', 'hyper-cutter', 'shell-armor', NULL, 30);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (343, 'Baltoy', 'Ground', 'Psychic', 'Hoenn', 'HOENN', 'BALTOY moves while spinning around on its one foot. Primitive wall paintings depicting this POKéMON living among people were discovered in some ancient ruins.', 'romfs:/sprites/343.png', 40, 40, 55, 40, 70, 55, 'medium', 'levitate', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (344, 'Claydol', 'Ground', 'Psychic', 'Hoenn', 'HOENN', 'CLAYDOL are said to be dolls of mud made by primitive humans and brought to life by exposure to a mysterious ray. This POKéMON moves about while levitating.', 'romfs:/sprites/344.png', 60, 70, 105, 70, 120, 75, 'medium', 'levitate', NULL, NULL, 36);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (345, 'Lileep', 'Rock', 'Grass', 'Hoenn', 'HOENN', 'LILEEP became extinct approximately a hundred million years ago. This ancient POKéMON attaches itself to a rock on the seafloor and catches approaching prey using tentacles  shaped like flower petals.', 'romfs:/sprites/345.png', 66, 41, 77, 61, 87, 23, 'slow-then-very-fast', 'suction-cups', 'storm-drain', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (346, 'Cradily', 'Rock', 'Grass', 'Hoenn', 'HOENN', 'CRADILY roams around the ocean floor in search of food. This POKéMON freely extends its tree trunk-like neck and captures unwary prey using its eight tentacles.', 'romfs:/sprites/346.png', 86, 81, 97, 81, 107, 43, 'slow-then-very-fast', 'suction-cups', 'storm-drain', NULL, 40);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (347, 'Anorith', 'Rock', 'Bug', 'Hoenn', 'HOENN', 'ANORITH was regenerated from a prehistoric fossil. This primitive POKéMON once lived in warm seas. It grips its prey firmly between its two large claws.', 'romfs:/sprites/347.png', 45, 95, 50, 40, 50, 75, 'slow-then-very-fast', 'battle-armor', 'swift-swim', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (348, 'Armaldo', 'Rock', 'Bug', 'Hoenn', 'HOENN', 'ARMALDO’s tough armor makes all attacks bounce off. This POKéMON’s two enormous claws can be freely extended or contracted. They have the power to punch right through a steel slab.', 'romfs:/sprites/348.png', 75, 125, 100, 70, 80, 45, 'slow-then-very-fast', 'battle-armor', 'swift-swim', NULL, 40);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (349, 'Feebas', 'Water', NULL, 'Hoenn', 'HOENN', 'FEEBAS’s fins are ragged and tattered from the start of its life. Because of its shoddy appearance, this POKéMON is largely ignored. It is capable of living in both the sea and in rivers.', 'romfs:/sprites/349.png', 20, 15, 20, 10, 55, 80, 'slow-then-very-fast', 'swift-swim', 'oblivious', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (350, 'Milotic', 'Water', NULL, 'Hoenn', 'HOENN', 'Its lovely scales are described as rainbow colored. They change color depending on the viewing angle.', 'romfs:/sprites/350.png', 95, 60, 79, 100, 125, 81, 'slow-then-very-fast', 'marvel-scale', 'competitive', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (351, 'Castform', 'Normal', NULL, 'Hoenn', 'HOENN', 'CASTFORM’s appearance changes with the weather. This POKéMON gained the ability to use the vast power of nature to protect its tiny body.', 'romfs:/sprites/351.png', 70, 70, 70, 70, 70, 70, 'medium', 'forecast', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (352, 'Kecleon', 'Normal', NULL, 'Hoenn', 'HOENN', 'It changes body color to blend in with its surroundings. It also changes color if it is happy or sad.', 'romfs:/sprites/352.png', 60, 90, 70, 60, 120, 40, 'medium-slow', 'color-change', 'protean', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (353, 'Shuppet', 'Ghost', NULL, 'Hoenn', 'HOENN', 'SHUPPET is attracted by feelings of jealousy and vindictiveness. If someone develops strong feelings of vengeance, this POKéMON will appear in a swarm and line up beneath the eaves of that person’s home.', 'romfs:/sprites/353.png', 44, 75, 35, 63, 33, 45, 'fast', 'insomnia', 'frisk', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (354, 'Banette', 'Ghost', NULL, 'Hoenn', 'HOENN', 'BANETTE generates energy for laying strong curses by sticking pins into its own body. This POKéMON was originally a pitiful plush doll that was thrown away.', 'romfs:/sprites/354.png', 64, 115, 65, 83, 63, 65, 'fast', 'insomnia', 'frisk', NULL, 37);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (355, 'Duskull', 'Ghost', NULL, 'Hoenn', 'HOENN', 'DUSKULL can pass through any wall no matter how thick it may be. Once this POKéMON chooses a target, it will doggedly pursue the intended victim until the break of dawn.', 'romfs:/sprites/355.png', 20, 40, 90, 30, 90, 25, 'fast', 'levitate', 'frisk', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (356, 'Dusclops', 'Ghost', NULL, 'Hoenn', 'HOENN', 'DUSCLOPS’s body is completely hollow - there is nothing at all inside. It is said that its body is like a black hole. This POKéMON will absorb anything into its body, but nothing will ever come back out.', 'romfs:/sprites/356.png', 40, 70, 130, 60, 130, 25, 'fast', 'pressure', 'frisk', NULL, 37);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (357, 'Tropius', 'Grass', 'Flying', 'Hoenn', 'HOENN', 'The bunches of fruit around TROPIUS’s neck are very popular with children. This POKéMON loves fruit, and eats it continuously. Apparently, its love for fruit resulted in its own outgrowth of fruit.', 'romfs:/sprites/357.png', 99, 68, 83, 72, 87, 51, 'slow', 'chlorophyll', 'solar-power', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (358, 'Chimecho', 'Psychic', NULL, 'Hoenn', 'HOENN', 'CHIMECHO makes its cries echo inside its hollow body. When this POKéMON becomes enraged, its cries result in ultrasonic waves that have the power to knock foes flying.', 'romfs:/sprites/358.png', 75, 50, 80, 95, 90, 65, 'fast', 'levitate', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (359, 'Absol', 'Dark', NULL, 'Hoenn', 'HOENN', 'Every time ABSOL appears before people, it is followed by a disaster such as an earthquake or a tidal wave. As a result, it came to be known as the disaster POKéMON.', 'romfs:/sprites/359.png', 65, 130, 60, 75, 60, 75, 'medium-slow', 'pressure', 'super-luck', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (360, 'Wynaut', 'Psychic', NULL, 'Hoenn', 'HOENN', 'WYNAUT can always be seen with a big, happy smile on its face. Look at its tail to determine if it is angry. When angered, this POKéMON will be slapping the ground with its tail.', 'romfs:/sprites/360.png', 95, 23, 48, 23, 48, 23, 'medium', 'shadow-tag', 'telepathy', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (361, 'Snorunt', 'Ice', NULL, 'Hoenn', 'HOENN', 'SNORUNT live in regions with heavy snowfall. In seasons without snow, such as spring and summer, this POKéMON steals away to live quietly among stalactites and stalagmites deep in caverns.', 'romfs:/sprites/361.png', 50, 50, 50, 50, 50, 50, 'medium', 'inner-focus', 'ice-body', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (362, 'Glalie', 'Ice', NULL, 'Hoenn', 'HOENN', 'GLALIE has a body made of rock, which it hardens with an armor of ice. This POKéMON has the ability to freeze moisture in the atmosphere into any shape it desires.', 'romfs:/sprites/362.png', 80, 80, 80, 80, 80, 80, 'medium', 'inner-focus', 'ice-body', NULL, 42);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (363, 'Spheal', 'Ice', 'Water', 'Hoenn', 'HOENN', 'SPHEAL is much faster rolling than  walking to get around. When groups of this POKéMON eat, they all clap at once to show their pleasure. Because of this, their mealtimes are noisy.', 'romfs:/sprites/363.png', 70, 40, 50, 55, 50, 25, 'medium-slow', 'thick-fat', 'ice-body', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (364, 'Sealeo', 'Ice', 'Water', 'Hoenn', 'HOENN', 'SEALEO has the habit of always juggling on the tip of its nose anything it sees for the first time. This POKéMON occasionally entertains itself by balancing and rolling a SPHEAL on its nose.', 'romfs:/sprites/364.png', 90, 60, 70, 75, 70, 45, 'medium-slow', 'thick-fat', 'ice-body', NULL, 32);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (365, 'Walrein', 'Ice', 'Water', 'Hoenn', 'HOENN', 'It swims through icy seas while shattering ice floes with its large tusks. It is protected by its thick blubber.', 'romfs:/sprites/365.png', 110, 80, 90, 95, 90, 65, 'medium-slow', 'thick-fat', 'ice-body', NULL, 44);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (366, 'Clamperl', 'Water', NULL, 'Hoenn', 'HOENN', 'CLAMPERL’s sturdy shell is not only good for protection - it is also used for clamping and catching prey. A fully grown CLAMPERL’s shell will be scored with nicks and scratches all over.', 'romfs:/sprites/366.png', 35, 64, 85, 74, 55, 32, 'slow-then-very-fast', 'shell-armor', 'rattled', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (367, 'Huntail', 'Water', NULL, 'Hoenn', 'HOENN', 'HUNTAIL’s presence went unnoticed by people for a long time because it lives at extreme depths in the sea. This POKéMON’s eyes can see clearly even in the murky dark depths of the ocean.', 'romfs:/sprites/367.png', 55, 104, 105, 94, 75, 52, 'slow-then-very-fast', 'swift-swim', 'water-veil', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (368, 'Gorebyss', 'Water', NULL, 'Hoenn', 'HOENN', 'GOREBYSS lives in the southern seas at extreme depths. Its body is built to withstand the enormous pressure of water at incredible depths. Because of this, this POKéMON’s body is unharmed by ordinary attacks.', 'romfs:/sprites/368.png', 55, 84, 105, 114, 75, 52, 'slow-then-very-fast', 'swift-swim', 'hydration', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (369, 'Relicanth', 'Water', 'Rock', 'Hoenn', 'HOENN', 'RELICANTH is a POKéMON species that existed for a hundred million years without ever changing its form. This ancient POKéMON feeds on microscopic organisms with its toothless mouth.', 'romfs:/sprites/369.png', 100, 90, 130, 45, 65, 55, 'slow', 'swift-swim', 'rock-head', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (370, 'Luvdisc', 'Water', NULL, 'Hoenn', 'HOENN', 'LUVDISC live in shallow seas in the tropics. This heart-shaped POKéMON earned its name by swimming after loving couples it spotted in the ocean’s waves.', 'romfs:/sprites/370.png', 43, 30, 55, 40, 65, 97, 'fast', 'swift-swim', 'hydration', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (371, 'Bagon', 'Dragon', NULL, 'Hoenn', 'HOENN', 'Dreaming of one day flying, it practices by leaping off cliffs every day.', 'romfs:/sprites/371.png', 45, 75, 60, 40, 30, 50, 'slow', 'rock-head', 'sheer-force', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (372, 'Shelgon', 'Dragon', NULL, 'Hoenn', 'HOENN', 'Inside SHELGON’s armor-like shell, cells are in the midst of transformation to create an entirely new body. This POKéMON’s shell is extremely heavy, making its movements sluggish.', 'romfs:/sprites/372.png', 65, 95, 100, 60, 50, 50, 'slow', 'rock-head', 'overcoat', NULL, 30);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (373, 'Salamence', 'Dragon', 'Flying', 'Hoenn', 'HOENN', 'SALAMENCE came about as a result of a strong, long-held dream of growing wings. It is said that this powerful desire triggered a sudden mutation in this POKéMON’s cells, causing it to sprout its magnificent wings.', 'romfs:/sprites/373.png', 95, 135, 80, 110, 80, 100, 'slow', 'intimidate', 'moxie', NULL, 50);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (374, 'Beldum', 'Steel', 'Psychic', 'Hoenn', 'HOENN', 'Instead of blood, a powerful magnetic force courses throughout BELDUM’s body. This POKéMON communicates with others by sending controlled pulses of magnetism.', 'romfs:/sprites/374.png', 40, 55, 80, 35, 60, 30, 'slow', 'clear-body', 'light-metal', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (375, 'Metang', 'Steel', 'Psychic', 'Hoenn', 'HOENN', 'When two BELDUM fuse together, METANG is formed. The brains of the BELDUM are joined by a magnetic nervous system. By linking its brains magnetically, this POKéMON generates strong psychokinetic power.', 'romfs:/sprites/375.png', 60, 75, 100, 55, 80, 50, 'slow', 'clear-body', 'light-metal', NULL, 20);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (376, 'Metagross', 'Steel', 'Psychic', 'Hoenn', 'HOENN', 'METAGROSS has four brains in total. Combined, the four brains can breeze through difficult calculations faster than a supercomputer. This POKéMON can float in the air by tucking in its four legs.', 'romfs:/sprites/376.png', 80, 135, 130, 95, 90, 70, 'slow', 'clear-body', 'light-metal', NULL, 45);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (377, 'Regirock', 'Rock', NULL, 'Hoenn', 'HOENN', 'Its entire body is made of rock. If any part chips off in battle, it attaches rocks to repair itself.', 'romfs:/sprites/377.png', 80, 100, 200, 50, 100, 50, 'slow', 'clear-body', 'sturdy', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (378, 'Regice', 'Ice', NULL, 'Hoenn', 'HOENN', 'REGICE’s body was made during an ice age. The deep-frozen body can’t be melted, even by fire. This POKéMON controls frigid air of minus 328 degrees F.', 'romfs:/sprites/378.png', 80, 50, 100, 100, 200, 50, 'slow', 'clear-body', 'ice-body', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (379, 'Registeel', 'Steel', NULL, 'Hoenn', 'HOENN', 'REGISTEEL has a body that is harder than any kind of metal. Its body is apparently hollow. No one has any idea what this POKéMON eats.', 'romfs:/sprites/379.png', 80, 75, 150, 75, 150, 50, 'slow', 'clear-body', 'light-metal', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (380, 'Latias', 'Dragon', 'Psychic', 'Hoenn', 'HOENN', 'LATIAS is highly sensitive to the emotions of people. If it senses any hostility, this POKéMON ruffles the feathers all over its body and cries shrilly to intimidate the foe.', 'romfs:/sprites/380.png', 80, 80, 90, 110, 130, 110, 'slow', 'levitate', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (381, 'Latios', 'Dragon', 'Psychic', 'Hoenn', 'HOENN', 'LATIOS has the ability to make its foe see an image of what it has seen or imagines in its head. This POKéMON is intelligent and understands human speech.', 'romfs:/sprites/381.png', 80, 90, 80, 130, 110, 110, 'slow', 'levitate', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (382, 'Kyogre', 'Water', NULL, 'Hoenn', 'HOENN', 'KYOGRE has the power to create massive rain clouds that cover the entire sky and bring about torrential downpours. This POKéMON saved people who were suffering from droughts.', 'romfs:/sprites/382.png', 100, 100, 90, 150, 140, 90, 'slow', 'drizzle', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (383, 'Groudon', 'Ground', NULL, 'Hoenn', 'HOENN', 'GROUDON has long been described in  mythology as the POKéMON that raised lands and expanded continents. This POKéMON took to sleep after a cataclysmic battle with KYOGRE.', 'romfs:/sprites/383.png', 100, 150, 140, 100, 90, 90, 'slow', 'drought', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (384, 'Rayquaza', 'Dragon', 'Flying', 'Hoenn', 'HOENN', 'RAYQUAZA lived for hundreds of millions of years in the earth’s ozone layer,  never descending to the ground. This POKéMON appears to feed on water and particles in the atmosphere.', 'romfs:/sprites/384.png', 105, 150, 90, 150, 90, 95, 'slow', 'air-lock', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (385, 'Jirachi', 'Steel', 'Psychic', 'Hoenn', 'HOENN', 'A legend states that JIRACHI will make true any wish that is written on notes attached to its head when it awakens. If this POKéMON senses danger, it will fight without awakening.', 'romfs:/sprites/385.png', 100, 100, 100, 100, 100, 100, 'slow', 'serene-grace', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (386, 'Deoxys-normal', 'Psychic', NULL, 'Hoenn', 'HOENN', 'The DNA of a space virus underwent a sudden mutation upon exposure to a laser beam and resulted in DEOXYS. The crystalline organ on this POKéMON’s chest appears to be its brain.', 'romfs:/sprites/386.png', 50, 150, 50, 150, 50, 150, 'slow', 'pressure', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (387, 'Turtwig', 'Grass', NULL, 'Sinnoh', 'BDSP', 'Made from soil, the shell on its back hardens when it drinks water. It lives along lakes.', 'romfs:/sprites/387.png', 55, 68, 64, 45, 55, 31, 'medium-slow', 'overgrow', 'shell-armor', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (388, 'Grotle', 'Grass', NULL, 'Sinnoh', 'BDSP', 'It knows where pure water wells up. It carries fellow Pokémon there on its back.', 'romfs:/sprites/388.png', 75, 89, 85, 55, 65, 36, 'medium-slow', 'overgrow', 'shell-armor', NULL, 18);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (389, 'Torterra', 'Grass', 'Ground', 'Sinnoh', 'BDSP', 'Small Pokémon occasionally gather on its unmoving back to begin building their nests.', 'romfs:/sprites/389.png', 95, 109, 105, 75, 85, 56, 'medium-slow', 'overgrow', 'shell-armor', NULL, 32);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (390, 'Chimchar', 'Fire', NULL, 'Sinnoh', 'BDSP', 'It agilely scales sheer cliffs to live atop craggy mountains. Its fire is put out when it sleeps.', 'romfs:/sprites/390.png', 44, 58, 44, 58, 44, 61, 'medium-slow', 'blaze', 'iron-fist', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (391, 'Monferno', 'Fire', 'Fighting', 'Sinnoh', 'BDSP', 'To intimidate attackers, it stretches the fire on its tail to make itself appear bigger.', 'romfs:/sprites/391.png', 64, 78, 52, 78, 52, 81, 'medium-slow', 'blaze', 'iron-fist', NULL, 14);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (392, 'Infernape', 'Fire', 'Fighting', 'Sinnoh', 'BDSP', 'It uses a special kind of martial arts involving all its limbs. Its fire never goes out.', 'romfs:/sprites/392.png', 76, 104, 71, 104, 71, 108, 'medium-slow', 'blaze', 'iron-fist', NULL, 36);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (393, 'Piplup', 'Water', NULL, 'Sinnoh', 'BDSP', 'Because it is very proud, it hates accepting food from people. Its thick down guards it from cold.', 'romfs:/sprites/393.png', 53, 51, 53, 61, 56, 40, 'medium-slow', 'torrent', 'competitive', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (394, 'Prinplup', 'Water', NULL, 'Sinnoh', 'BDSP', 'It lives alone, away from others. Apparently, every one of them believes it is the most important.', 'romfs:/sprites/394.png', 64, 66, 68, 81, 76, 50, 'medium-slow', 'torrent', 'competitive', NULL, 16);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (395, 'Empoleon', 'Water', 'Steel', 'Sinnoh', 'BDSP', 'The three horns that extend from its beak attest to its power. The leader has the biggest horns.', 'romfs:/sprites/395.png', 84, 86, 88, 111, 101, 60, 'medium-slow', 'torrent', 'competitive', NULL, 36);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (396, 'Starly', 'Normal', 'Flying', 'Sinnoh', 'BDSP', 'They flock in great numbers. Though small, they flap their wings with great power.', 'romfs:/sprites/396.png', 40, 55, 30, 30, 30, 60, 'medium-slow', 'keen-eye', 'reckless', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (397, 'Staravia', 'Normal', 'Flying', 'Sinnoh', 'BDSP', 'It flies around forests and fields in search of bug Pokémon. It stays within a huge flock.', 'romfs:/sprites/397.png', 55, 75, 50, 40, 40, 80, 'medium-slow', 'intimidate', 'reckless', NULL, 14);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (398, 'Staraptor', 'Normal', 'Flying', 'Sinnoh', 'BDSP', 'It has a savage nature. It will courageously challenge foes that are much larger.', 'romfs:/sprites/398.png', 85, 120, 70, 50, 60, 100, 'medium-slow', 'intimidate', 'reckless', NULL, 34);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (399, 'Bidoof', 'Normal', NULL, 'Sinnoh', 'BDSP', 'With nerves of steel, nothing can perturb it. It is more agile and active than it appears.', 'romfs:/sprites/399.png', 59, 45, 40, 35, 40, 31, 'medium', 'simple', 'unaware', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (400, 'Bibarel', 'Normal', 'Water', 'Sinnoh', 'BDSP', 'It makes its nest by damming streams with bark and mud. It is known as an industrious worker.', 'romfs:/sprites/400.png', 79, 85, 60, 55, 60, 71, 'medium', 'simple', 'unaware', NULL, 15);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (401, 'Kricketot', 'Bug', NULL, 'Sinnoh', 'BDSP', 'It shakes its head back to front, causing its antennae to hit each other and sound like a xylophone.', 'romfs:/sprites/401.png', 37, 25, 41, 25, 41, 25, 'medium-slow', 'shed-skin', 'run-away', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (402, 'Kricketune', 'Bug', NULL, 'Sinnoh', 'BDSP', 'It crosses its knifelike arms in front of its chest when it cries. It can compose melodies ad lib.', 'romfs:/sprites/402.png', 77, 85, 51, 55, 51, 65, 'medium-slow', 'swarm', 'technician', NULL, 10);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (403, 'Shinx', 'Electric', NULL, 'Sinnoh', 'BDSP', 'All of its fur dazzles if danger is sensed. It flees while the foe is momentarily blinded.', 'romfs:/sprites/403.png', 45, 65, 34, 40, 34, 45, 'medium-slow', 'rivalry', 'intimidate', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (404, 'Luxio', 'Electric', NULL, 'Sinnoh', 'BDSP', 'Its claws loose electricity with enough amperage to cause fainting. They live in small groups.', 'romfs:/sprites/404.png', 60, 85, 49, 60, 49, 60, 'medium-slow', 'rivalry', 'intimidate', NULL, 15);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (405, 'Luxray', 'Electric', NULL, 'Sinnoh', 'BDSP', 'It has eyes that can see through anything. It spots and captures prey hiding behind objects.', 'romfs:/sprites/405.png', 80, 120, 79, 95, 79, 70, 'medium-slow', 'rivalry', 'intimidate', NULL, 30);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (406, 'Budew', 'Grass', 'Poison', 'Sinnoh', 'BDSP', 'Over the winter, it closes its bud and endures the cold. In spring, the bud opens and releases pollen.', 'romfs:/sprites/406.png', 40, 30, 35, 50, 70, 55, 'medium-slow', 'natural-cure', 'poison-point', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (407, 'Roserade', 'Grass', 'Poison', 'Sinnoh', 'BDSP', 'It attracts prey with a sweet aroma, then downs it with thorny whips hidden in its arms.', 'romfs:/sprites/407.png', 60, 70, 65, 125, 105, 90, 'medium-slow', 'natural-cure', 'poison-point', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (408, 'Cranidos', 'Rock', NULL, 'Sinnoh', 'BDSP', 'It lived in jungles around 100 million years ago. Its skull is as hard as iron.', 'romfs:/sprites/408.png', 67, 125, 40, 30, 30, 58, 'slow-then-very-fast', 'mold-breaker', 'sheer-force', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (409, 'Rampardos', 'Rock', NULL, 'Sinnoh', 'BDSP', 'Its powerful head butt has enough power to shatter even the most durable things upon impact.', 'romfs:/sprites/409.png', 97, 165, 60, 65, 50, 58, 'slow-then-very-fast', 'mold-breaker', 'sheer-force', NULL, 30);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (410, 'Shieldon', 'Rock', 'Steel', 'Sinnoh', 'BDSP', 'A Pokémon that lived in jungles around 100 million years ago. Its facial hide is extremely hard.', 'romfs:/sprites/410.png', 30, 42, 118, 42, 88, 30, 'slow-then-very-fast', 'sturdy', 'soundproof', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (411, 'Bastiodon', 'Rock', 'Steel', 'Sinnoh', 'BDSP', 'Any frontal attack is repulsed. It is a docile Pokémon that feeds on grass and berries.', 'romfs:/sprites/411.png', 60, 52, 168, 47, 138, 30, 'slow-then-very-fast', 'sturdy', 'soundproof', NULL, 30);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (412, 'Burmy', 'Bug', NULL, 'Sinnoh', 'BDSP', 'To shelter itself from cold, wintry winds, it covers itself with a cloak made of twigs and leaves.', 'romfs:/sprites/412.png', 40, 29, 45, 29, 45, 36, 'medium', 'shed-skin', 'overcoat', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (413, 'Wormadam-plant', 'Bug', 'Grass', 'Sinnoh', 'BDSP', 'When BURMY evolved, its cloak became a part of this Pokémon’s body. The cloak is never shed.', 'romfs:/sprites/413.png', 60, 59, 85, 79, 105, 36, 'medium', 'anticipation', 'overcoat', NULL, 20);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (414, 'Mothim', 'Bug', 'Flying', 'Sinnoh', 'BDSP', 'It loves the honey of flowers and steals honey collected by COMBEE.', 'romfs:/sprites/414.png', 70, 94, 50, 94, 50, 66, 'medium', 'swarm', 'tinted-lens', NULL, 20);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (415, 'Combee', 'Bug', 'Flying', 'Sinnoh', 'BDSP', 'A Pokémon formed by three others. It busily carries sweet floral honey to VESPIQUEN.', 'romfs:/sprites/415.png', 30, 30, 42, 30, 42, 70, 'medium-slow', 'honey-gather', 'hustle', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (416, 'Vespiquen', 'Bug', 'Flying', 'Sinnoh', 'BDSP', 'Its abdomen is a honeycomb for grubs. It raises its grubs on honey collected by COMBEE.', 'romfs:/sprites/416.png', 70, 80, 102, 80, 102, 40, 'medium-slow', 'pressure', 'unnerve', NULL, 21);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (417, 'Pachirisu', 'Electric', NULL, 'Sinnoh', 'BDSP', 'It makes fur balls that crackle with static electricity. It stores them with berries in tree holes.', 'romfs:/sprites/417.png', 60, 45, 70, 45, 90, 95, 'medium', 'run-away', 'pickup', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (418, 'Buizel', 'Water', NULL, 'Sinnoh', 'BDSP', 'It has a flotation sac that is like an inflatable collar. It floats on water with its head out.', 'romfs:/sprites/418.png', 55, 65, 35, 60, 30, 85, 'medium', 'swift-swim', 'water-veil', NULL, NULL);
