INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (420, 'Cherubi', 'Grass', NULL, 'Sinnoh', 'BDSP', 'The small ball holds the nutrients needed for evolution. Apparently, it is very sweet and tasty.', 'romfs:/sprites/420.png', 45, 35, 45, 62, 53, 35, 'medium', 'chlorophyll', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (421, 'Cherrim', 'Grass', NULL, 'Sinnoh', 'BDSP', 'It blooms during times of strong sunlight. It tries to make up for everything it endured as a bud.', 'romfs:/sprites/421.png', 70, 60, 70, 87, 78, 85, 'medium', 'flower-gift', NULL, NULL, 25);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (422, 'Shellos', 'Water', NULL, 'Sinnoh', 'BDSP', 'Its colors and shapes differ from region to region. In the Sinnoh region, two types are confirmed.', 'romfs:/sprites/422.png', 76, 48, 48, 57, 62, 34, 'medium', 'sticky-hold', 'storm-drain', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (423, 'Gastrodon', 'Water', 'Ground', 'Sinnoh', 'BDSP', 'It has a pliable body without any bones. If any part of its body is torn off, it grows right back.', 'romfs:/sprites/423.png', 111, 83, 68, 92, 82, 39, 'medium', 'sticky-hold', 'storm-drain', NULL, 30);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (424, 'Ambipom', 'Normal', NULL, 'Sinnoh', 'BDSP', 'To eat, it deftly shucks nuts with its two tails. It rarely uses its arms now.', 'romfs:/sprites/424.png', 75, 100, 66, 60, 66, 115, 'fast', 'technician', 'pickup', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (425, 'Drifloon', 'Ghost', 'Flying', 'Sinnoh', 'BDSP', 'A Pokémon formed by the spirits of people and Pokémon. It loves damp, humid seasons.', 'romfs:/sprites/425.png', 90, 50, 34, 60, 44, 70, 'fast-then-very-slow', 'aftermath', 'unburden', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (426, 'Drifblim', 'Ghost', 'Flying', 'Sinnoh', 'BDSP', 'At dusk, swarms of them are carried aloft on winds. When noticed, they suddenly vanish.', 'romfs:/sprites/426.png', 150, 80, 44, 90, 54, 80, 'fast-then-very-slow', 'aftermath', 'unburden', NULL, 28);
