INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (528, 'Swoobat', 'Psychic', 'Flying', 'Unova', 'UNOVA', 'It emits sound waves of various frequencies from its nose, including some powerful enough to destroy rocks.', 'romfs:/sprites/528.png', 67, 57, 55, 77, 55, 114, 'medium', 'unaware', 'klutz', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (529, 'Drilbur', 'Ground', NULL, 'Unova', 'UNOVA', 'It can dig through the ground at a speed of 30 mph. It could give a car running aboveground a good race.', 'romfs:/sprites/529.png', 60, 85, 40, 30, 45, 68, 'medium', 'sand-rush', 'sand-force', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (530, 'Excadrill', 'Ground', 'Steel', 'Unova', 'UNOVA', 'It can help in tunnel construction. Its drill has evolved into steel strong enough to bore through iron plates.', 'romfs:/sprites/530.png', 110, 135, 60, 50, 65, 88, 'medium', 'sand-rush', 'sand-force', NULL, 31);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (531, 'Audino', 'Normal', NULL, 'Unova', 'UNOVA', 'It touches others with the feelers on its ears, using the sound of their heartbeats to tell how they are feeling.', 'romfs:/sprites/531.png', 103, 60, 86, 60, 86, 50, 'fast', 'healer', 'regenerator', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (532, 'Timburr', 'Fighting', NULL, 'Unova', 'UNOVA', 'It fights by swinging a piece of lumber around. It is close to evolving when it can handle the lumber without difficulty.', 'romfs:/sprites/532.png', 75, 80, 55, 25, 35, 35, 'medium-slow', 'guts', 'sheer-force', NULL, NULL);
