INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (534, 'Conkeldurr', 'Fighting', NULL, 'Unova', 'UNOVA', 'It is thought that Conkeldurr taught humans how to make concrete more than 2,000 years ago.', 'romfs:/sprites/534.png', 105, 140, 95, 55, 65, 45, 'medium-slow', 'guts', 'sheer-force', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (535, 'Tympole', 'Water', NULL, 'Unova', 'UNOVA', 'They warn others of danger by vibrating their cheeks to create a high-pitched sound.', 'romfs:/sprites/535.png', 50, 50, 40, 50, 40, 64, 'medium-slow', 'swift-swim', 'hydration', NULL, NULL);
