INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (537, 'Seismitoad', 'Water', 'Ground', 'Unova', 'UNOVA', 'They shoot paralyzing liquid from their head bumps. They use vibration to hurt their opponents.', 'romfs:/sprites/537.png', 105, 95, 75, 85, 75, 74, 'medium-slow', 'swift-swim', 'poison-touch', NULL, 36);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (538, 'Throh', 'Fighting', NULL, 'Unova', 'UNOVA', 'When it tightens its belt, it becomes stronger. Wild Throh use vines to weave their own belts.', 'romfs:/sprites/538.png', 120, 100, 85, 30, 85, 45, 'medium', 'guts', 'inner-focus', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (539, 'Sawk', 'Fighting', NULL, 'Unova', 'UNOVA', 'The sound of Sawk punching boulders and trees can be heard all the way from the mountains where they train.', 'romfs:/sprites/539.png', 75, 125, 75, 30, 75, 85, 'medium', 'sturdy', 'inner-focus', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (540, 'Sewaddle', 'Bug', 'Grass', 'Unova', 'UNOVA', 'Leavanny dress it in clothes they made for it when it hatched. It hides its head in its hood while it is sleeping.', 'romfs:/sprites/540.png', 45, 53, 70, 40, 60, 42, 'medium-slow', 'swarm', 'chlorophyll', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (541, 'Swadloon', 'Bug', 'Grass', 'Unova', 'UNOVA', 'Forests where Swadloon live have superb foliage because the nutrients they make from fallen leaves nourish the plant life.', 'romfs:/sprites/541.png', 55, 63, 90, 50, 80, 42, 'medium-slow', 'leaf-guard', 'chlorophyll', NULL, 20);
