INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (543, 'Venipede', 'Bug', 'Poison', 'Unova', 'UNOVA', 'Its bite injects a potent poison, enough to paralyze large bird Pokémon that try to prey on it.', 'romfs:/sprites/543.png', 30, 45, 59, 30, 39, 57, 'medium-slow', 'poison-point', 'swarm', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (544, 'Whirlipede', 'Bug', 'Poison', 'Unova', 'UNOVA', 'Protected by a hard shell, it spins its body like a wheel and crashes furiously into its enemies.', 'romfs:/sprites/544.png', 40, 55, 99, 40, 79, 47, 'medium-slow', 'poison-point', 'swarm', NULL, 22);
