INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (546, 'Cottonee', 'Grass', 'Fairy', 'Unova', 'UNOVA', 'When attacked, it escapes by shooting cotton from its body. The cotton serves as a decoy to distract the attacker.', 'romfs:/sprites/546.png', 40, 27, 60, 37, 50, 66, 'medium', 'prankster', 'infiltrator', NULL, NULL);
