INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (548, 'Petilil', 'Grass', NULL, 'Unova', 'UNOVA', 'The leaves on its head are very bitter. Eating one of these leaves is known to refresh a tired body.', 'romfs:/sprites/548.png', 45, 35, 50, 70, 50, 30, 'medium', 'chlorophyll', 'own-tempo', NULL, NULL);
