INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (569, 'Garbodor', 'Poison', NULL, 'Unova', 'UNOVA', 'It clenches opponents with its left arm and finishes them off with foul-smelling poison gas belched from its mouth.', 'romfs:/sprites/569.png', 80, 95, 82, 60, 82, 75, 'medium', 'stench', 'weak-armor', NULL, 36);
