INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (575, 'Gothorita', 'Psychic', NULL, 'Unova', 'UNOVA', 'They use hypnosis to control people and Pokémon. Tales of Gothorita leading people astray are told in every corner.', 'romfs:/sprites/575.png', 60, 45, 70, 75, 85, 55, 'medium-slow', 'frisk', 'competitive', NULL, 32);
