INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (577, 'Solosis', 'Psychic', NULL, 'Unova', 'UNOVA', 'They drive away attackers by unleashing psychic power. They can use telepathy to talk with others.', 'romfs:/sprites/577.png', 45, 30, 40, 105, 50, 20, 'medium-slow', 'overcoat', 'magic-guard', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (578, 'Duosion', 'Psychic', NULL, 'Unova', 'UNOVA', 'Since they have two divided brains, at times they suddenly try to take two different actions at once.', 'romfs:/sprites/578.png', 65, 40, 50, 125, 60, 30, 'medium-slow', 'overcoat', 'magic-guard', NULL, 32);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (579, 'Reuniclus', 'Psychic', NULL, 'Unova', 'UNOVA', 'When Reuniclus shake hands, a network forms between their brains, increasing their psychic power.', 'romfs:/sprites/579.png', 110, 65, 75, 125, 85, 30, 'medium-slow', 'overcoat', 'magic-guard', NULL, 41);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (580, 'Ducklett', 'Water', 'Flying', 'Unova', 'UNOVA', 'These bird Pokémon are excellent divers. They swim around in the water eating their favorite food--peat moss.', 'romfs:/sprites/580.png', 62, 44, 50, 44, 50, 55, 'medium', 'keen-eye', 'big-pecks', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (581, 'Swanna', 'Water', 'Flying', 'Unova', 'UNOVA', 'Swanna start to dance at dusk. The one dancing in the middle is the leader of the flock.', 'romfs:/sprites/581.png', 75, 87, 63, 87, 63, 98, 'medium', 'keen-eye', 'big-pecks', NULL, 35);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (582, 'Vanillite', 'Ice', NULL, 'Unova', 'UNOVA', 'The temperature of their breath is -58° F. They create snow crystals and make snow fall in the areas around them.', 'romfs:/sprites/582.png', 36, 50, 50, 65, 60, 44, 'slow', 'ice-body', 'snow-cloak', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (583, 'Vanillish', 'Ice', NULL, 'Unova', 'UNOVA', 'Snowy mountains are this Pokémon’s habitat. During an ancient ice age, they moved to southern areas.', 'romfs:/sprites/583.png', 51, 65, 65, 80, 75, 59, 'slow', 'ice-body', 'snow-cloak', NULL, 35);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (584, 'Vanilluxe', 'Ice', NULL, 'Unova', 'UNOVA', 'Swallowing large amounts of water, they make snow clouds inside their bodies and attack their foes with violent blizzards.', 'romfs:/sprites/584.png', 71, 95, 85, 110, 95, 79, 'slow', 'ice-body', 'snow-warning', NULL, 47);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (585, 'Deerling', 'Normal', 'Grass', 'Unova', 'UNOVA', 'The color and scent of their fur changes to match the mountain grass. When they sense hostility, they hide in the grass.', 'romfs:/sprites/585.png', 60, 60, 50, 40, 50, 75, 'medium', 'chlorophyll', 'sap-sipper', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (586, 'Sawsbuck', 'Normal', 'Grass', 'Unova', 'UNOVA', 'They migrate according to the seasons. People can tell the season by looking at Sawsbuck’s horns.', 'romfs:/sprites/586.png', 80, 100, 70, 60, 70, 95, 'medium', 'chlorophyll', 'sap-sipper', NULL, 34);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (587, 'Emolga', 'Electric', 'Flying', 'Unova', 'UNOVA', 'The energy made in its cheeks’ electric pouches is stored inside its membrane and released while it is gliding.', 'romfs:/sprites/587.png', 55, 75, 60, 75, 60, 103, 'medium', 'static', 'motor-drive', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (588, 'Karrablast', 'Bug', NULL, 'Unova', 'UNOVA', 'These mysterious Pokémon evolve when they receive electrical stimulation while they are in the same place as Shelmet.', 'romfs:/sprites/588.png', 50, 75, 45, 40, 45, 60, 'medium', 'swarm', 'shed-skin', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (589, 'Escavalier', 'Bug', 'Steel', 'Unova', 'UNOVA', 'They fly around at high speed, striking with their pointed spears. Even when in trouble, they face opponents bravely.', 'romfs:/sprites/589.png', 70, 135, 105, 60, 105, 20, 'medium', 'swarm', 'shell-armor', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (590, 'Foongus', 'Grass', 'Poison', 'Unova', 'UNOVA', 'It lures people in with its Poké Ball pattern, then releases poison spores. Why it resembles a Poké Ball is unknown.', 'romfs:/sprites/590.png', 69, 55, 45, 55, 55, 15, 'medium', 'effect-spore', 'regenerator', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (591, 'Amoonguss', 'Grass', 'Poison', 'Unova', 'UNOVA', 'It lures prey close by dancing and waving its arm caps, which resemble Poké Balls, in a swaying motion.', 'romfs:/sprites/591.png', 114, 85, 70, 85, 80, 30, 'medium', 'effect-spore', 'regenerator', NULL, 39);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (592, 'Frillish', 'Water', 'Ghost', 'Unova', 'UNOVA', 'With its thin, veil-like arms wrapped around the body of its opponent, it sinks to the ocean floor.', 'romfs:/sprites/592.png', 55, 40, 50, 65, 85, 40, 'medium', 'water-absorb', 'cursed-body', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (593, 'Jellicent', 'Water', 'Ghost', 'Unova', 'UNOVA', 'The fate of the ships and crew that wander into Jellicent’s habitat: all sunken, all lost, all vanished.', 'romfs:/sprites/593.png', 100, 60, 70, 85, 105, 60, 'medium', 'water-absorb', 'cursed-body', NULL, 40);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (594, 'Alomomola', 'Water', NULL, 'Unova', 'UNOVA', 'The special membrane enveloping Alomomola has the ability to heal wounds.', 'romfs:/sprites/594.png', 165, 75, 80, 40, 45, 65, 'fast', 'healer', 'hydration', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (595, 'Joltik', 'Bug', 'Electric', 'Unova', 'UNOVA', 'Joltik that live in cities have learned a technique for sucking electricity from the outlets in houses.', 'romfs:/sprites/595.png', 50, 47, 50, 57, 50, 65, 'medium', 'compound-eyes', 'unnerve', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (596, 'Galvantula', 'Bug', 'Electric', 'Unova', 'UNOVA', 'When attacked, they create an electric barrier by spitting out many electrically charged threads.', 'romfs:/sprites/596.png', 70, 77, 60, 97, 60, 108, 'medium', 'compound-eyes', 'unnerve', NULL, 36);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (597, 'Ferroseed', 'Grass', 'Steel', 'Unova', 'UNOVA', 'When threatened, it attacks by shooting a barrage of spikes, which gives it a chance to escape by rolling away.', 'romfs:/sprites/597.png', 44, 50, 91, 24, 86, 10, 'medium', 'iron-barbs', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (598, 'Ferrothorn', 'Grass', 'Steel', 'Unova', 'UNOVA', 'It fights by swinging around its three spiky feelers. A hit from these steel spikes can reduce a boulder to rubble.', 'romfs:/sprites/598.png', 74, 94, 131, 54, 116, 20, 'medium', 'iron-barbs', 'anticipation', NULL, 40);
