INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (600, 'Klang', 'Steel', NULL, 'Unova', 'UNOVA', 'By changing the direction in which it rotates, it communicates its feelings to others. When angry, it rotates faster.', 'romfs:/sprites/600.png', 60, 80, 95, 70, 85, 50, 'medium-slow', 'plus', 'minus', NULL, 38);
