INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (613, 'Cubchoo', 'Ice', NULL, 'Unova', 'UNOVA', 'When it is not feeling well, its mucus gets watery and the power of its Ice-type moves decreases.', 'romfs:/sprites/613.png', 55, 70, 40, 60, 40, 40, 'medium', 'snow-cloak', 'slush-rush', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (614, 'Beartic', 'Ice', NULL, 'Unova', 'UNOVA', 'It can make its breath freeze at will. Very able in the water, it swims around in northern seas and catches prey.', 'romfs:/sprites/614.png', 95, 130, 80, 70, 80, 50, 'medium', 'snow-cloak', 'slush-rush', NULL, 37);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (615, 'Cryogonal', 'Ice', NULL, 'Unova', 'UNOVA', 'When its body temperature goes up, it turns into steam and vanishes. When its temperature lowers, it returns to ice.', 'romfs:/sprites/615.png', 80, 50, 50, 95, 135, 105, 'medium', 'levitate', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (616, 'Shelmet', 'Bug', NULL, 'Unova', 'UNOVA', 'When attacked, it defends itself by closing the lid of its shell. It can spit a sticky, poisonous liquid.', 'romfs:/sprites/616.png', 50, 40, 85, 40, 65, 25, 'medium', 'hydration', 'shell-armor', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (617, 'Accelgor', 'Bug', NULL, 'Unova', 'UNOVA', 'When its body dries out, it weakens. So, to prevent dehydration, it wraps itself in many layers of thin membrane.', 'romfs:/sprites/617.png', 80, 70, 40, 100, 60, 145, 'medium', 'hydration', 'sticky-hold', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (618, 'Stunfisk', 'Ground', 'Electric', 'Unova', 'UNOVA', 'Its skin is very hard, so it is unhurt even if stepped on by sumo wrestlers. It smiles when transmitting electricity.', 'romfs:/sprites/618.png', 109, 66, 84, 81, 99, 32, 'medium', 'static', 'limber', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (619, 'Mienfoo', 'Fighting', NULL, 'Unova', 'UNOVA', 'In fights, they dominate with onslaughts of flowing, continuous attacks. With their sharp claws, they cut enemies.', 'romfs:/sprites/619.png', 45, 85, 50, 55, 50, 65, 'medium-slow', 'inner-focus', 'regenerator', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (620, 'Mienshao', 'Fighting', NULL, 'Unova', 'UNOVA', 'It wields the fur on its arms like a whip. Its arm attacks come with such rapidity that they cannot even be seen.', 'romfs:/sprites/620.png', 65, 125, 60, 95, 60, 105, 'medium-slow', 'inner-focus', 'regenerator', NULL, 50);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (621, 'Druddigon', 'Dragon', NULL, 'Unova', 'UNOVA', 'It warms its body by absorbing sunlight with its wings. When its body temperature falls, it can no longer move.', 'romfs:/sprites/621.png', 77, 120, 90, 60, 90, 48, 'medium', 'rough-skin', 'sheer-force', NULL, NULL);
