INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (623, 'Golurk', 'Ground', 'Ghost', 'Unova', 'UNOVA', 'It flies across the sky at Mach speeds. Removing the seal on its chest makes its internal energy go out of control.', 'romfs:/sprites/623.png', 89, 124, 80, 55, 80, 55, 'medium', 'iron-fist', 'klutz', NULL, 43);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (624, 'Pawniard', 'Dark', 'Steel', 'Unova', 'UNOVA', 'Blades comprise this Pokémon’s entire body. If battling dulls the blades, it sharpens them on stones by the river.', 'romfs:/sprites/624.png', 45, 85, 70, 40, 40, 60, 'medium', 'defiant', 'inner-focus', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (625, 'Bisharp', 'Dark', 'Steel', 'Unova', 'UNOVA', 'It leads a group of Pawniard. It battles to become the boss, but will be driven from the group if it loses.', 'romfs:/sprites/625.png', 65, 125, 100, 60, 70, 70, 'medium', 'defiant', 'inner-focus', NULL, 52);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (626, 'Bouffalant', 'Normal', NULL, 'Unova', 'UNOVA', 'Their fluffy fur absorbs damage, even if they strike foes with a fierce headbutt.', 'romfs:/sprites/626.png', 95, 110, 95, 40, 95, 55, 'medium', 'reckless', 'sap-sipper', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (627, 'Rufflet', 'Normal', 'Flying', 'Unova', 'UNOVA', 'They crush berries with their talons. They bravely stand up to any opponent, no matter how strong it is.', 'romfs:/sprites/627.png', 70, 83, 50, 37, 50, 60, 'slow', 'keen-eye', 'sheer-force', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (628, 'Braviary', 'Normal', 'Flying', 'Unova', 'UNOVA', 'They fight for their friends without any thought about danger to themselves. One can carry a car while flying.', 'romfs:/sprites/628.png', 100, 123, 75, 57, 75, 80, 'slow', 'keen-eye', 'sheer-force', NULL, 54);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (629, 'Vullaby', 'Dark', 'Flying', 'Unova', 'UNOVA', 'Their wings are too tiny to allow them to fly. They guard their posteriors with bones that were gathered by Mandibuzz.', 'romfs:/sprites/629.png', 70, 55, 75, 45, 65, 60, 'slow', 'big-pecks', 'overcoat', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (630, 'Mandibuzz', 'Dark', 'Flying', 'Unova', 'UNOVA', 'It makes a nest out of bones it finds. It grabs weakened prey in its talons and hauls it to its nest of bones.', 'romfs:/sprites/630.png', 110, 65, 105, 55, 95, 80, 'slow', 'big-pecks', 'overcoat', NULL, 54);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (631, 'Heatmor', 'Fire', NULL, 'Unova', 'UNOVA', 'It breathes through a hole in its tail while it burns with an internal fire. Durant is its prey.', 'romfs:/sprites/631.png', 85, 97, 66, 105, 66, 65, 'medium', 'gluttony', 'flash-fire', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (632, 'Durant', 'Bug', 'Steel', 'Unova', 'UNOVA', 'They attack in groups, covering themselves in steel armor to protect themselves from Heatmor.', 'romfs:/sprites/632.png', 58, 109, 112, 48, 48, 109, 'medium', 'swarm', 'hustle', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (633, 'Deino', 'Dark', 'Dragon', 'Unova', 'UNOVA', 'It tends to bite everything, and it is not a picky eater. Approaching it carelessly is dangerous.', 'romfs:/sprites/633.png', 52, 65, 50, 45, 50, 38, 'slow', 'hustle', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (634, 'Zweilous', 'Dark', 'Dragon', 'Unova', 'UNOVA', 'After it has eaten up all the food in its territory, it moves to another area. Its two heads do not get along.', 'romfs:/sprites/634.png', 72, 85, 70, 65, 70, 58, 'slow', 'hustle', NULL, NULL, 50);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (635, 'Hydreigon', 'Dark', 'Dragon', 'Unova', 'UNOVA', 'This brutal Pokémon travels the skies on its six wings. Anything that moves seems like a foe to it, triggering its attack.', 'romfs:/sprites/635.png', 92, 105, 90, 125, 90, 98, 'slow', 'levitate', NULL, NULL, 64);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (636, 'Larvesta', 'Bug', 'Fire', 'Unova', 'UNOVA', 'This Pokémon was believed to have been born from the sun. When it evolves, its entire body is engulfed in flames.', 'romfs:/sprites/636.png', 55, 85, 55, 50, 55, 60, 'slow', 'flame-body', 'swarm', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (637, 'Volcarona', 'Bug', 'Fire', 'Unova', 'UNOVA', 'When volcanic ash darkened the atmosphere, it is said that Volcarona’s fire provided a replacement for the sun.', 'romfs:/sprites/637.png', 85, 60, 65, 135, 105, 100, 'slow', 'flame-body', 'swarm', NULL, 59);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (638, 'Cobalion', 'Steel', 'Fighting', 'Unova', 'UNOVA', 'This legendary Pokémon battled against humans to protect Pokémon. Its personality is calm and composed.', 'romfs:/sprites/638.png', 91, 90, 129, 90, 72, 108, 'slow', 'justified', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (639, 'Terrakion', 'Rock', 'Fighting', 'Unova', 'UNOVA', 'This Pokémon came to the defense of Pokémon that had lost their homes in a war among humans.', 'romfs:/sprites/639.png', 91, 129, 90, 72, 90, 108, 'slow', 'justified', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (640, 'Virizion', 'Grass', 'Fighting', 'Unova', 'UNOVA', 'This Pokémon fought humans in order to protect its friends. Legends about it continue to be passed down.', 'romfs:/sprites/640.png', 91, 90, 72, 90, 129, 108, 'slow', 'justified', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (641, 'Tornadus-incarnate', 'Flying', NULL, 'Unova', 'UNOVA', 'The lower half of its body is wrapped in a cloud of energy. It zooms through the sky at 200 mph.', 'romfs:/sprites/641.png', 79, 115, 70, 125, 80, 111, 'slow', 'prankster', 'defiant', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (642, 'Thundurus-incarnate', 'Electric', 'Flying', 'Unova', 'UNOVA', 'Countless charred remains mar the landscape of places through which Thundurus has passed.', 'romfs:/sprites/642.png', 79, 115, 70, 125, 80, 111, 'slow', 'prankster', 'defiant', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (643, 'Reshiram', 'Dragon', 'Fire', 'Unova', 'UNOVA', 'This Pokémon appears in legends. It sends flames into the air from its tail, burning up everything around it.', 'romfs:/sprites/643.png', 100, 120, 100, 150, 120, 90, 'slow', 'turboblaze', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (644, 'Zekrom', 'Dragon', 'Electric', 'Unova', 'UNOVA', 'Concealing itself in lightning clouds, it flies throughout the Unova region. It creates electricity in its tail.', 'romfs:/sprites/644.png', 100, 150, 120, 120, 100, 90, 'slow', 'teravolt', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (645, 'Landorus-incarnate', 'Ground', 'Flying', 'Unova', 'UNOVA', 'Lands visited by Landorus grant such bountiful crops that it has been hailed as “The Guardian of the Fields.”', 'romfs:/sprites/645.png', 89, 125, 90, 115, 80, 101, 'slow', 'sand-force', 'sheer-force', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (646, 'Kyurem', 'Dragon', 'Ice', 'Unova', 'UNOVA', 'It generates a powerful, freezing energy inside itself, but its body became frozen when the energy leaked out.', 'romfs:/sprites/646.png', 125, 130, 90, 130, 90, 95, 'slow', 'pressure', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (647, 'Keldeo-ordinary', 'Water', 'Fighting', 'Unova', 'UNOVA', 'By blasting water from its hooves, it can glide across water. It excels at using leg moves while battling.', 'romfs:/sprites/647.png', 91, 72, 90, 129, 90, 108, 'slow', 'justified', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (648, 'Meloetta-aria', 'Normal', 'Psychic', 'Unova', 'UNOVA', 'Its melodies are sung with a special vocalization method that can control the feelings of those who hear it.', 'romfs:/sprites/648.png', 100, 77, 77, 128, 128, 90, 'slow', 'serene-grace', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (649, 'Genesect', 'Bug', 'Steel', 'Unova', 'UNOVA', 'Over 300 million years ago, it was feared as the strongest of hunters. It has been modified by Team Plasma.', 'romfs:/sprites/649.png', 71, 120, 95, 120, 95, 99, 'slow', 'download', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (650, 'Chespin', 'Grass', NULL, 'Kalos', 'KALOS', 'The quills on its head are usually soft. When it flexes them, the points become so hard and sharp that they can pierce rock.', 'romfs:/sprites/650.png', 56, 61, 65, 48, 45, 38, 'medium-slow', 'overgrow', 'bulletproof', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (651, 'Quilladin', 'Grass', NULL, 'Kalos', 'KALOS', 'It relies on its sturdy shell to deflect predators’ attacks. It counterattacks with its sharp quills.', 'romfs:/sprites/651.png', 61, 78, 95, 56, 58, 57, 'medium-slow', 'overgrow', 'bulletproof', NULL, 16);
