INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (653, 'Fennekin', 'Fire', NULL, 'Kalos', 'KALOS', 'Eating a twig fills it with energy, and its roomy ears give vent to air hotter than 390 degrees Fahrenheit.', 'romfs:/sprites/653.png', 40, 45, 40, 62, 60, 60, 'medium-slow', 'blaze', 'magician', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (654, 'Braixen', 'Fire', NULL, 'Kalos', 'KALOS', 'It has a twig stuck in its tail. With friction from its tail fur, it sets the twig on fire and launches into battle.', 'romfs:/sprites/654.png', 59, 59, 58, 90, 70, 73, 'medium-slow', 'blaze', 'magician', NULL, 16);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (655, 'Delphox', 'Fire', 'Psychic', 'Kalos', 'KALOS', 'It gazes into the flame at the tip of its branch to achieve a focused state, which allows it to see into the future.', 'romfs:/sprites/655.png', 75, 69, 72, 114, 100, 104, 'medium-slow', 'blaze', 'magician', NULL, 36);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (656, 'Froakie', 'Water', NULL, 'Kalos', 'KALOS', 'It secretes flexible bubbles from its chest and back. The bubbles reduce the damage it would otherwise take when attacked.', 'romfs:/sprites/656.png', 41, 56, 40, 62, 44, 71, 'medium-slow', 'torrent', 'protean', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (657, 'Frogadier', 'Water', NULL, 'Kalos', 'KALOS', 'It can throw bubble-covered pebbles with precise control, hitting empty cans up to a hundred feet away.', 'romfs:/sprites/657.png', 54, 63, 52, 83, 56, 97, 'medium-slow', 'torrent', 'protean', NULL, 16);
