INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (659, 'Bunnelby', 'Normal', NULL, 'Kalos', 'KALOS', 'They use their large ears to dig burrows. They will dig the whole night through.', 'romfs:/sprites/659.png', 38, 36, 38, 32, 36, 57, 'medium', 'pickup', 'cheek-pouch', NULL, NULL);
