INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (661, 'Fletchling', 'Normal', 'Flying', 'Kalos', 'KALOS', 'These friendly Pokémon send signals to one another with beautiful chirps and tail-feather movements.', 'romfs:/sprites/661.png', 45, 50, 43, 40, 38, 62, 'medium-slow', 'big-pecks', 'gale-wings', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (662, 'Fletchinder', 'Fire', 'Flying', 'Kalos', 'KALOS', 'From its beak, it expels embers that set the tall grass on fire. Then it pounces on the bewildered prey that pop out of the grass.', 'romfs:/sprites/662.png', 62, 73, 55, 56, 52, 84, 'medium-slow', 'flame-body', 'gale-wings', NULL, 17);
