INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (664, 'Scatterbug', 'Bug', NULL, 'Kalos', 'KALOS', 'When under attack from bird Pokémon, it spews a poisonous black powder that causes paralysis on contact.', 'romfs:/sprites/664.png', 38, 35, 40, 27, 25, 35, 'medium', 'shield-dust', 'compound-eyes', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (665, 'Spewpa', 'Bug', NULL, 'Kalos', 'KALOS', 'It lives hidden within thicket shadows. When predators attack, it quickly bristles the fur covering its body in an effort to threaten them.', 'romfs:/sprites/665.png', 45, 22, 60, 27, 30, 29, 'medium', 'shed-skin', 'friend-guard', NULL, 9);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (666, 'Vivillon', 'Bug', 'Flying', 'Kalos', 'KALOS', 'Vivillon with many different patterns are found all over the world. These patterns are affected by the climate of their habitat.', 'romfs:/sprites/666.png', 80, 52, 50, 90, 50, 89, 'medium', 'shield-dust', 'compound-eyes', NULL, 12);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (667, 'Litleo', 'Fire', 'Normal', 'Kalos', 'KALOS', 'The stronger the opponent it faces, the more heat surges from its mane and the more power flows through its body.', 'romfs:/sprites/667.png', 62, 50, 58, 73, 54, 72, 'medium-slow', 'rivalry', 'unnerve', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (668, 'Pyroar', 'Fire', 'Normal', 'Kalos', 'KALOS', 'The male with the largest mane of fire is the leader of the pride.', 'romfs:/sprites/668.png', 86, 68, 72, 109, 66, 106, 'medium-slow', 'rivalry', 'unnerve', NULL, 35);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (669, 'Flabebe', 'Fairy', NULL, 'Kalos', 'KALOS', 'It draws out and controls the hidden power of flowers. The flower Flabébé holds is most likely part of its body.', 'romfs:/sprites/669.png', 44, 38, 39, 61, 79, 42, 'medium', 'flower-veil', 'symbiosis', NULL, NULL);
