INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (672, 'Skiddo', 'Grass', NULL, 'Kalos', 'KALOS', 'Thought to be one of the first Pokémon to live in harmony with humans, it has a placid disposition.', 'romfs:/sprites/672.png', 66, 65, 48, 62, 57, 52, 'medium', 'sap-sipper', 'grass-pelt', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (673, 'Gogoat', 'Grass', NULL, 'Kalos', 'KALOS', 'It can tell how its Trainer is feeling by subtle shifts in the grip on its horns. This empathic sense lets them run as if one being.', 'romfs:/sprites/673.png', 123, 100, 62, 97, 81, 68, 'medium', 'sap-sipper', 'grass-pelt', NULL, 32);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (674, 'Pancham', 'Fighting', NULL, 'Kalos', 'KALOS', 'It does its best to be taken seriously by its enemies, but its glare is not sufficiently intimidating. Chewing on a leaf is its trademark.', 'romfs:/sprites/674.png', 67, 82, 62, 46, 48, 43, 'medium', 'iron-fist', 'mold-breaker', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (675, 'Pangoro', 'Fighting', 'Dark', 'Kalos', 'KALOS', 'Although it possesses a violent temperament, it won’t put up with bullying. It uses the leaf in its mouth to sense the movements of its enemies.', 'romfs:/sprites/675.png', 95, 124, 78, 69, 71, 58, 'medium', 'iron-fist', 'mold-breaker', NULL, 32);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (676, 'Furfrou', 'Normal', NULL, 'Kalos', 'KALOS', 'Trimming its fluffy fur not only makes it more elegant but also increases the swiftness of its movements.', 'romfs:/sprites/676.png', 75, 80, 60, 65, 90, 102, 'medium', 'fur-coat', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (677, 'Espurr', 'Psychic', NULL, 'Kalos', 'KALOS', 'The organ that emits its intense psychic power is sheltered by its ears to keep power from leaking out.', 'romfs:/sprites/677.png', 62, 48, 54, 63, 60, 68, 'medium', 'keen-eye', 'infiltrator', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (678, 'Meowstic-male', 'Psychic', NULL, 'Kalos', 'KALOS', 'When in danger, it raises its ears and releases enough psychic power to grind a 10-ton truck into dust.', 'romfs:/sprites/678.png', 74, 48, 76, 83, 81, 104, 'medium', 'keen-eye', 'infiltrator', NULL, 25);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (679, 'Honedge', 'Steel', 'Ghost', 'Kalos', 'KALOS', 'Apparently this Pokémon is born when a departed spirit inhabits a sword. It attaches itself to people and drinks their life force.', 'romfs:/sprites/679.png', 45, 80, 100, 35, 37, 28, 'medium', 'no-guard', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (680, 'Doublade', 'Steel', 'Ghost', 'Kalos', 'KALOS', 'When Honedge evolves, it divides into two swords, which cooperate via telepathy to coordinate attacks and slash their enemies to ribbons.', 'romfs:/sprites/680.png', 59, 110, 150, 45, 49, 35, 'medium', 'no-guard', NULL, NULL, 35);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (681, 'Aegislash-shield', 'Steel', 'Ghost', 'Kalos', 'KALOS', 'Generations of kings were attended by these Pokémon, which used their spectral power to manipulate and control people and Pokémon.', 'romfs:/sprites/681.png', 60, 50, 140, 50, 140, 60, 'medium', 'stance-change', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (682, 'Spritzee', 'Fairy', NULL, 'Kalos', 'KALOS', 'It emits a scent that enraptures those who smell it. This fragrance changes depending on what it has eaten.', 'romfs:/sprites/682.png', 78, 52, 60, 63, 65, 23, 'medium', 'healer', 'aroma-veil', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (683, 'Aromatisse', 'Fairy', NULL, 'Kalos', 'KALOS', 'It devises various scents, pleasant and unpleasant, and emits scents that its enemies dislike in order to gain an edge in battle.', 'romfs:/sprites/683.png', 101, 72, 72, 99, 89, 29, 'medium', 'healer', 'aroma-veil', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (684, 'Swirlix', 'Fairy', NULL, 'Kalos', 'KALOS', 'To entangle its opponents in battle, it extrudes white threads as sweet and sticky as cotton candy.', 'romfs:/sprites/684.png', 62, 48, 66, 59, 57, 49, 'medium', 'sweet-veil', 'unburden', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (685, 'Slurpuff', 'Fairy', NULL, 'Kalos', 'KALOS', 'It can distinguish the faintest of scents. It puts its sensitive sense of smell to use by helping pastry chefs in their work.', 'romfs:/sprites/685.png', 82, 80, 86, 85, 75, 72, 'medium', 'sweet-veil', 'unburden', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (686, 'Inkay', 'Dark', 'Psychic', 'Kalos', 'KALOS', 'Opponents who stare at the flashing of the light-emitting spots on its body become dazed and lose their will to fight.', 'romfs:/sprites/686.png', 53, 54, 53, 37, 46, 45, 'medium', 'contrary', 'suction-cups', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (687, 'Malamar', 'Dark', 'Psychic', 'Kalos', 'KALOS', 'It wields the most compelling hypnotic powers of any Pokémon, and it forces others to do whatever it wants.', 'romfs:/sprites/687.png', 86, 92, 88, 68, 75, 73, 'medium', 'contrary', 'suction-cups', NULL, 30);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (688, 'Binacle', 'Rock', 'Water', 'Kalos', 'KALOS', 'Two Binacle live together on one rock. When they fight, one of them will move to a different rock.', 'romfs:/sprites/688.png', 42, 52, 67, 39, 56, 50, 'medium', 'tough-claws', 'sniper', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (689, 'Barbaracle', 'Rock', 'Water', 'Kalos', 'KALOS', 'When they evolve, two Binacle multiply into seven. They fight with the power of seven Binacle.', 'romfs:/sprites/689.png', 72, 105, 115, 54, 86, 68, 'medium', 'tough-claws', 'sniper', NULL, 39);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (690, 'Skrelp', 'Poison', 'Water', 'Kalos', 'KALOS', 'Camouflaged as rotten kelp, they spray liquid poison on prey that approaches unawares and then finish it off.', 'romfs:/sprites/690.png', 50, 60, 60, 60, 60, 30, 'medium', 'poison-point', 'poison-touch', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (691, 'Dragalge', 'Poison', 'Dragon', 'Kalos', 'KALOS', 'Their poison is strong enough to eat through the hull of a tanker, and they spit it indiscriminately at anything that enters their territory.', 'romfs:/sprites/691.png', 65, 75, 90, 97, 123, 44, 'medium', 'poison-point', 'poison-touch', NULL, 48);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (692, 'Clauncher', 'Water', NULL, 'Kalos', 'KALOS', 'They knock down flying prey by firing compressed water from their massive claws like shooting a pistol.', 'romfs:/sprites/692.png', 50, 53, 62, 58, 63, 44, 'slow', 'mega-launcher', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (693, 'Clawitzer', 'Water', NULL, 'Kalos', 'KALOS', 'Their enormous claws launch cannonballs of water powerful enough to pierce tanker hulls.', 'romfs:/sprites/693.png', 71, 73, 88, 120, 89, 59, 'slow', 'mega-launcher', NULL, NULL, 37);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (694, 'Helioptile', 'Electric', 'Normal', 'Kalos', 'KALOS', 'They make their home in deserts. They can generate their energy from basking in the sun, so eating food is not a requirement.', 'romfs:/sprites/694.png', 44, 38, 33, 61, 43, 70, 'medium', 'dry-skin', 'sand-veil', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (695, 'Heliolisk', 'Electric', 'Normal', 'Kalos', 'KALOS', 'They flare their frills and generate energy. A single Heliolisk can generate sufficient electricity to power a skyscraper.', 'romfs:/sprites/695.png', 62, 55, 52, 109, 94, 109, 'medium', 'dry-skin', 'sand-veil', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (696, 'Tyrunt', 'Rock', 'Dragon', 'Kalos', 'KALOS', 'This Pokémon was restored from a fossil. If something happens that it doesn’t like, it throws a tantrum and runs wild.', 'romfs:/sprites/696.png', 58, 89, 77, 45, 45, 48, 'medium', 'strong-jaw', 'sturdy', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (697, 'Tyrantrum', 'Rock', 'Dragon', 'Kalos', 'KALOS', 'Thanks to its gargantuan jaws, which could shred thick metal plates as if they were paper, it was invincible in the ancient world it once inhabited.', 'romfs:/sprites/697.png', 82, 121, 119, 69, 59, 71, 'medium', 'strong-jaw', 'rock-head', NULL, 39);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (698, 'Amaura', 'Rock', 'Ice', 'Kalos', 'KALOS', 'This ancient Pokémon was restored from part of its body that had been frozen in ice for over 100 million years.', 'romfs:/sprites/698.png', 77, 59, 50, 67, 63, 46, 'medium', 'refrigerate', 'snow-warning', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (699, 'Aurorus', 'Rock', 'Ice', 'Kalos', 'KALOS', 'The diamond-shaped crystals on its body expel air as cold as -240 degrees Fahrenheit, surrounding its enemies and encasing them in ice.', 'romfs:/sprites/699.png', 123, 77, 72, 99, 92, 58, 'medium', 'refrigerate', 'snow-warning', NULL, 39);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (700, 'Sylveon', 'Fairy', NULL, 'Kalos', 'KALOS', 'It sends a soothing aura from its ribbonlike feelers to calm fights.', 'romfs:/sprites/700.png', 95, 65, 65, 110, 130, 60, 'medium', 'cute-charm', 'pixilate', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (701, 'Hawlucha', 'Fighting', 'Flying', 'Kalos', 'KALOS', 'Although its body is small, its proficient fighting skills enable it to keep up with big bruisers like Machamp and Hariyama.', 'romfs:/sprites/701.png', 78, 92, 75, 74, 63, 118, 'medium', 'limber', 'unburden', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (702, 'Dedenne', 'Electric', 'Fairy', 'Kalos', 'KALOS', 'Its whiskers serve as antennas. By sending and receiving electrical waves, it can communicate with others over vast distances.', 'romfs:/sprites/702.png', 67, 58, 57, 81, 67, 101, 'medium', 'cheek-pouch', 'pickup', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (703, 'Carbink', 'Rock', 'Fairy', 'Kalos', 'KALOS', 'Born from the temperatures and pressures deep underground, it fires beams from the stone in its head.', 'romfs:/sprites/703.png', 50, 50, 150, 50, 150, 50, 'slow', 'clear-body', 'sturdy', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (704, 'Goomy', 'Dragon', NULL, 'Kalos', 'KALOS', 'The weakest Dragon-type Pokémon, it lives in damp, shady places, so its body doesn’t dry out.', 'romfs:/sprites/704.png', 45, 50, 35, 55, 75, 40, 'slow', 'sap-sipper', 'hydration', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (705, 'Sliggoo', 'Dragon', NULL, 'Kalos', 'KALOS', 'It drives away opponents by excreting a sticky liquid that can dissolve anything. Its eyes devolved, so it can’t see anything.', 'romfs:/sprites/705.png', 68, 75, 53, 83, 113, 60, 'slow', 'sap-sipper', 'hydration', NULL, 40);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (706, 'Goodra', 'Dragon', NULL, 'Kalos', 'KALOS', 'This very friendly Dragon-type Pokémon will hug its beloved Trainer, leaving that Trainer covered in sticky slime.', 'romfs:/sprites/706.png', 90, 100, 70, 110, 150, 80, 'slow', 'sap-sipper', 'hydration', NULL, 50);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (707, 'Klefki', 'Steel', 'Fairy', 'Kalos', 'KALOS', 'These key collectors threaten any attackers by fiercely jingling their keys at them.', 'romfs:/sprites/707.png', 57, 80, 91, 80, 87, 75, 'fast', 'prankster', 'magician', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (708, 'Phantump', 'Ghost', 'Grass', 'Kalos', 'KALOS', 'These Pokémon are created when spirits possess rotten tree stumps. They prefer to live in abandoned forests.', 'romfs:/sprites/708.png', 43, 70, 48, 50, 60, 38, 'medium', 'natural-cure', 'frisk', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (709, 'Trevenant', 'Ghost', 'Grass', 'Kalos', 'KALOS', 'It can control trees at will. It will trap people who harm the forest, so they can never leave.', 'romfs:/sprites/709.png', 85, 110, 76, 65, 82, 56, 'medium', 'natural-cure', 'frisk', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (710, 'Pumpkaboo-average', 'Ghost', 'Grass', 'Kalos', 'KALOS', 'The pumpkin body is inhabited by a spirit trapped in this world. As the sun sets, it becomes restless and active.', 'romfs:/sprites/710.png', 49, 66, 70, 44, 55, 51, 'medium', 'pickup', 'frisk', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (711, 'Gourgeist-average', 'Ghost', 'Grass', 'Kalos', 'KALOS', 'Singing in eerie voices, they wander town streets on the night of the new moon. Anyone who hears their song is cursed.', 'romfs:/sprites/711.png', 65, 90, 122, 58, 75, 84, 'medium', 'pickup', 'frisk', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (712, 'Bergmite', 'Ice', NULL, 'Kalos', 'KALOS', 'It blocks opponents’ attacks with the ice that shields its body. It uses cold air to repair any cracks with new ice.', 'romfs:/sprites/712.png', 55, 69, 85, 32, 35, 28, 'medium', 'own-tempo', 'ice-body', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (713, 'Avalugg', 'Ice', NULL, 'Kalos', 'KALOS', 'Its ice-covered body is as hard as steel. Its cumbersome frame crushes anything that stands in its way.', 'romfs:/sprites/713.png', 95, 117, 184, 44, 46, 28, 'medium', 'own-tempo', 'ice-body', NULL, 37);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (714, 'Noibat', 'Flying', 'Dragon', 'Kalos', 'KALOS', 'They live in pitch-black caves. Their enormous ears can emit ultrasonic waves of 200,000 hertz.', 'romfs:/sprites/714.png', 40, 30, 35, 45, 40, 55, 'medium', 'frisk', 'infiltrator', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (715, 'Noivern', 'Flying', 'Dragon', 'Kalos', 'KALOS', 'They fly around on moonless nights and attack careless prey. Nothing can beat them in a battle in the dark.', 'romfs:/sprites/715.png', 85, 70, 80, 97, 80, 123, 'medium', 'frisk', 'infiltrator', NULL, 48);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (716, 'Xerneas', 'Fairy', NULL, 'Kalos', 'KALOS', 'Legends say it can share eternal life. It slept for a thousand years in the form of a tree before its revival.', 'romfs:/sprites/716.png', 126, 131, 95, 131, 98, 99, 'slow', 'fairy-aura', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (717, 'Yveltal', 'Dark', 'Flying', 'Kalos', 'KALOS', 'When this legendary Pokémon’s wings and tail feathers spread wide and glow red, it absorbs the life force of living creatures.', 'romfs:/sprites/717.png', 126, 131, 95, 131, 98, 99, 'slow', 'dark-aura', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (718, 'Zygarde-50', 'Dragon', 'Ground', 'Kalos', 'KALOS', 'When the Kalos region’s ecosystem falls into disarray, it appears and reveals its secret power.', 'romfs:/sprites/718.png', 108, 100, 121, 81, 95, 95, 'slow', 'aura-break', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (719, 'Diancie', 'Rock', 'Fairy', 'Kalos', 'KALOS', 'A sudden transformation of Carbink, its pink, glimmering body is said to be the loveliest sight in the whole world.', 'romfs:/sprites/719.png', 50, 100, 150, 100, 150, 50, 'slow', 'clear-body', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (720, 'Hoopa', 'Psychic', 'Ghost', 'Kalos', 'KALOS', 'This troublemaker sends anything and everything to faraway places using its loop, which can warp space.', 'romfs:/sprites/720.png', 80, 110, 60, 150, 130, 70, 'slow', 'magician', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (721, 'Volcanion', 'Fire', 'Water', 'Kalos', 'KALOS', 'It lets out billows of steam and disappears into the dense fog. It’s said to live in mountains where humans do not tread.', 'romfs:/sprites/721.png', 80, 110, 120, 130, 90, 70, 'slow', 'water-absorb', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (722, 'Rowlet', 'Grass', 'Flying', 'Alola', 'ALOLA', 'This wary Pokémon uses photosynthesis to store up energy during the day, while becoming active at night.', 'romfs:/sprites/722.png', 68, 55, 55, 50, 50, 42, 'medium-slow', 'overgrow', 'long-reach', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (723, 'Dartrix', 'Grass', 'Flying', 'Alola', 'ALOLA', 'A bit of a dandy, it spends its free time preening its wings. Its preoccupation with any dirt on its plumage can leave it unable to battle.', 'romfs:/sprites/723.png', 78, 75, 75, 70, 70, 52, 'medium-slow', 'overgrow', 'long-reach', NULL, 17);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (724, 'Decidueye', 'Grass', 'Ghost', 'Alola', 'ALOLA', 'It fires arrow quills from its wings with such precision, they can pierce a pebble at distances over a hundred yards.', 'romfs:/sprites/724.png', 78, 107, 75, 100, 100, 70, 'medium-slow', 'overgrow', 'long-reach', NULL, 34);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (725, 'Litten', 'Fire', NULL, 'Alola', 'ALOLA', 'While grooming itself, it builds up fur inside its stomach. It sets the fur alight and spews fiery attacks, which change based on how it coughs.', 'romfs:/sprites/725.png', 45, 65, 40, 60, 40, 70, 'medium-slow', 'blaze', 'intimidate', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (726, 'Torracat', 'Fire', NULL, 'Alola', 'ALOLA', 'At its throat, it bears a bell of fire. The bell rings brightly whenever this Pokémon spits fire.', 'romfs:/sprites/726.png', 65, 85, 50, 80, 50, 90, 'medium-slow', 'blaze', 'intimidate', NULL, 17);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (727, 'Incineroar', 'Fire', 'Dark', 'Alola', 'ALOLA', 'This Pokémon has a violent, selfish disposition. If it’s not in the mood to listen, it will ignore its Trainer’s orders with complete nonchalance.', 'romfs:/sprites/727.png', 95, 115, 90, 80, 90, 60, 'medium-slow', 'blaze', 'intimidate', NULL, 34);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (728, 'Popplio', 'Water', NULL, 'Alola', 'ALOLA', 'This Pokémon snorts body fluids from its nose, blowing balloons to smash into its foes. It’s famous for being a hard worker.', 'romfs:/sprites/728.png', 50, 54, 54, 66, 56, 40, 'medium-slow', 'torrent', 'liquid-voice', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (729, 'Brionne', 'Water', NULL, 'Alola', 'ALOLA', 'A skillful dancer, it creates a sequence of water balloons as it dances, and briskly bombards its enemies.', 'romfs:/sprites/729.png', 60, 69, 69, 91, 81, 50, 'medium-slow', 'torrent', 'liquid-voice', NULL, 17);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (730, 'Primarina', 'Water', 'Fairy', 'Alola', 'ALOLA', 'It controls its water balloons with song. The melody is learned from others of its kind and is passed down from one generation to the next.', 'romfs:/sprites/730.png', 80, 74, 74, 126, 116, 60, 'medium-slow', 'torrent', 'liquid-voice', NULL, 34);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (731, 'Pikipek', 'Normal', 'Flying', 'Alola', 'ALOLA', 'It can peck at a rate of 16 times a second to drill holes in trees. It uses the holes for food storage and for nesting.', 'romfs:/sprites/731.png', 35, 75, 30, 30, 30, 65, 'medium', 'keen-eye', 'skill-link', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (732, 'Trumbeak', 'Normal', 'Flying', 'Alola', 'ALOLA', 'It eats berries and stores their seeds in its beak. When it encounters enemies or prey, it fires off all the seeds in a burst.', 'romfs:/sprites/732.png', 55, 85, 50, 40, 50, 75, 'medium', 'keen-eye', 'skill-link', NULL, 14);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (733, 'Toucannon', 'Normal', 'Flying', 'Alola', 'ALOLA', 'When it battles, its beak heats up. The temperature can easily exceed 212 degrees Fahrenheit, causing severe burns when it hits.', 'romfs:/sprites/733.png', 80, 120, 75, 75, 75, 60, 'medium', 'keen-eye', 'skill-link', NULL, 28);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (734, 'Yungoos', 'Normal', NULL, 'Alola', 'ALOLA', 'With its sharp fangs, it will bite anything. It did not originally live in Alola but was imported from another region.', 'romfs:/sprites/734.png', 48, 70, 30, 30, 30, 45, 'medium', 'stakeout', 'strong-jaw', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (735, 'Gumshoos', 'Normal', NULL, 'Alola', 'ALOLA', 'When it finds a trace of its prey, it patiently stakes out the location...but it’s always snoozing by nightfall.', 'romfs:/sprites/735.png', 88, 110, 60, 55, 60, 45, 'medium', 'stakeout', 'strong-jaw', NULL, 20);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (736, 'Grubbin', 'Bug', NULL, 'Alola', 'ALOLA', 'Its strong jaw enables it to scrape trees and slurp out the sap. It normally lives underground.', 'romfs:/sprites/736.png', 47, 62, 45, 55, 45, 46, 'medium', 'swarm', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (737, 'Charjabug', 'Bug', 'Electric', 'Alola', 'ALOLA', 'Its body is capable of storing electricity. On camping trips, people are grateful to have one around.', 'romfs:/sprites/737.png', 57, 82, 95, 55, 75, 36, 'medium', 'battery', NULL, NULL, 20);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (738, 'Vikavolt', 'Bug', 'Electric', 'Alola', 'ALOLA', 'It zips around, on sharp lookout for an opening. It concentrates electrical energy within its large jaws and uses it to zap its enemies.', 'romfs:/sprites/738.png', 77, 70, 90, 145, 75, 43, 'medium', 'levitate', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (739, 'Crabrawler', 'Fighting', NULL, 'Alola', 'ALOLA', 'While guarding its weak points with its pincers, it looks for an opening and unleashes punches. When it loses, it foams at the mouth and faints.', 'romfs:/sprites/739.png', 47, 82, 57, 42, 47, 63, 'medium', 'hyper-cutter', 'iron-fist', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (740, 'Crabominable', 'Fighting', 'Ice', 'Alola', 'ALOLA', 'It aimed for the top but got lost and ended up on a snowy mountain. Being forced to endure the cold, this Pokémon evolved and grew fur.', 'romfs:/sprites/740.png', 97, 132, 77, 62, 67, 43, 'medium', 'hyper-cutter', 'iron-fist', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (741, 'Oricorio-baile', 'Fire', 'Flying', 'Alola', 'ALOLA', 'It beats its wings together to create fire. As it moves in the steps of its beautiful dance, it bathes opponents in intense flames.', 'romfs:/sprites/741.png', 75, 70, 70, 98, 70, 93, 'medium', 'dancer', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (742, 'Cutiefly', 'Bug', 'Fairy', 'Alola', 'ALOLA', 'It feeds on the nectar and pollen of flowers. Because it’s able to sense auras, it can identify which flowers are about to bloom.', 'romfs:/sprites/742.png', 40, 45, 40, 55, 40, 84, 'medium', 'honey-gather', 'shield-dust', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (743, 'Ribombee', 'Bug', 'Fairy', 'Alola', 'ALOLA', 'It rolls up pollen into puffs. It makes many different varieties, some used as food and others used in battle.', 'romfs:/sprites/743.png', 60, 55, 60, 95, 70, 124, 'medium', 'honey-gather', 'shield-dust', NULL, 25);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (744, 'Rockruff', 'Rock', NULL, 'Alola', 'ALOLA', 'It’s considered to be a good Pokémon for beginners because of its friendliness, but its disposition grows rougher as it grows up.', 'romfs:/sprites/744.png', 45, 65, 40, 30, 40, 60, 'medium', 'keen-eye', 'vital-spirit', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (745, 'Lycanroc-midday', 'Rock', NULL, 'Alola', 'ALOLA', 'Its quick movements confuse its enemies. Well equipped with claws and fangs, it also uses the sharp rocks in its mane as weapons.', 'romfs:/sprites/745.png', 75, 115, 65, 55, 65, 112, 'medium', 'keen-eye', 'sand-rush', NULL, 25);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (746, 'Wishiwashi-solo', 'Water', NULL, 'Alola', 'ALOLA', 'When it’s in trouble, its eyes moisten and begin to shine. The shining light attracts its comrades, and they stand together against their enemies.', 'romfs:/sprites/746.png', 45, 20, 20, 25, 25, 40, 'fast', 'schooling', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (747, 'Mareanie', 'Poison', 'Water', 'Alola', 'ALOLA', 'It plunges the poison spike on its head into its prey. When the prey has weakened, Mareanie deals the finishing blow with its 10 tentacles.', 'romfs:/sprites/747.png', 50, 53, 62, 43, 52, 45, 'medium', 'merciless', 'limber', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (748, 'Toxapex', 'Poison', 'Water', 'Alola', 'ALOLA', 'Toxapex crawls along the ocean floor on its 12 legs. It leaves a trail of Corsola bits scattered in its wake.', 'romfs:/sprites/748.png', 50, 63, 152, 53, 142, 35, 'medium', 'merciless', 'limber', NULL, 38);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (749, 'Mudbray', 'Ground', NULL, 'Alola', 'ALOLA', 'The mud stuck to Mudbray’s hooves enhances its grip and its powerful running gait.', 'romfs:/sprites/749.png', 70, 100, 70, 45, 55, 45, 'medium', 'own-tempo', 'stamina', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (750, 'Mudsdale', 'Ground', NULL, 'Alola', 'ALOLA', 'It spits a mud that provides resistance to both wind and rain, so the walls of old houses were often coated with it.', 'romfs:/sprites/750.png', 100, 125, 100, 55, 85, 35, 'medium', 'own-tempo', 'stamina', NULL, 30);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (751, 'Dewpider', 'Water', 'Bug', 'Alola', 'ALOLA', 'It crawls onto the land in search of food. Its water bubble allows it to breathe and protects its soft head.', 'romfs:/sprites/751.png', 38, 40, 52, 40, 72, 27, 'medium', 'water-bubble', 'water-absorb', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (752, 'Araquanid', 'Water', 'Bug', 'Alola', 'ALOLA', 'It delivers headbutts with the water bubble on its head. Small Pokémon get sucked into the bubble, where they drown.', 'romfs:/sprites/752.png', 68, 70, 92, 50, 132, 42, 'medium', 'water-bubble', 'water-absorb', NULL, 22);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (753, 'Fomantis', 'Grass', NULL, 'Alola', 'ALOLA', 'During the day, it sleeps and soaks up light. When night falls, it walks around looking for a safer place to sleep.', 'romfs:/sprites/753.png', 40, 55, 35, 50, 35, 35, 'medium', 'leaf-guard', 'contrary', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (754, 'Lurantis', 'Grass', NULL, 'Alola', 'ALOLA', 'It requires a lot of effort to maintain Lurantis’s vivid coloring, but some collectors enjoy this work and treat it as their hobby.', 'romfs:/sprites/754.png', 70, 105, 90, 80, 90, 45, 'medium', 'leaf-guard', 'contrary', NULL, 34);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (755, 'Morelull', 'Grass', 'Fairy', 'Alola', 'ALOLA', 'It scatters spores that flicker and glow. Anyone seeing these lights falls into a deep slumber.', 'romfs:/sprites/755.png', 40, 35, 55, 65, 75, 15, 'medium', 'illuminate', 'effect-spore', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (756, 'Shiinotic', 'Grass', 'Fairy', 'Alola', 'ALOLA', 'Forests where Shiinotic live are treacherous to enter at night. People confused by its strange lights can never find their way home again.', 'romfs:/sprites/756.png', 60, 45, 80, 90, 100, 30, 'medium', 'illuminate', 'effect-spore', NULL, 24);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (757, 'Salandit', 'Poison', 'Fire', 'Alola', 'ALOLA', 'It burns its bodily fluids to create a poisonous gas. When its enemies become disoriented from inhaling the gas, it attacks them.', 'romfs:/sprites/757.png', 48, 44, 40, 71, 40, 77, 'medium', 'corrosion', 'oblivious', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (758, 'Salazzle', 'Poison', 'Fire', 'Alola', 'ALOLA', 'For some reason, only females have been found. It creates a reverse harem of male Salandit that it lives with.', 'romfs:/sprites/758.png', 68, 64, 60, 111, 60, 117, 'medium', 'corrosion', 'oblivious', NULL, 33);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (759, 'Stufful', 'Normal', 'Fighting', 'Alola', 'ALOLA', 'Despite its adorable appearance, when it gets angry and flails about, its arms and legs could knock a pro wrestler sprawling.', 'romfs:/sprites/759.png', 70, 75, 50, 45, 50, 50, 'medium', 'fluffy', 'klutz', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (760, 'Bewear', 'Normal', 'Fighting', 'Alola', 'ALOLA', 'This immensely dangerous Pokémon possesses overwhelming physical strength. Its habitat is generally off-limits.', 'romfs:/sprites/760.png', 120, 125, 80, 55, 60, 60, 'medium', 'fluffy', 'klutz', NULL, 27);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (761, 'Bounsweet', 'Grass', NULL, 'Alola', 'ALOLA', 'A delectable aroma pours from its body. They are often swallowed whole by Toucannon lured by that wafting deliciousness.', 'romfs:/sprites/761.png', 42, 30, 38, 30, 38, 32, 'medium-slow', 'leaf-guard', 'oblivious', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (762, 'Steenee', 'Grass', NULL, 'Alola', 'ALOLA', 'The sepals on its head developed to protect its body. These are quite hard, so even if pecked by bird Pokémon, this Pokémon is totally fine.', 'romfs:/sprites/762.png', 52, 40, 48, 40, 48, 62, 'medium-slow', 'leaf-guard', 'oblivious', NULL, 18);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (763, 'Tsareena', 'Grass', NULL, 'Alola', 'ALOLA', 'Its long, striking legs aren’t just for show but to be used to kick with skill. In victory, it shows off by kicking the defeated, laughing boisterously.', 'romfs:/sprites/763.png', 72, 120, 98, 50, 98, 72, 'medium-slow', 'leaf-guard', 'queenly-majesty', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (764, 'Comfey', 'Fairy', NULL, 'Alola', 'ALOLA', 'It attaches flowers to its highly nutritious vine. This revitalizes the flowers, and they give off an aromatic scent.', 'romfs:/sprites/764.png', 51, 52, 90, 82, 110, 100, 'fast', 'flower-veil', 'triage', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (765, 'Oranguru', 'Normal', 'Psychic', 'Alola', 'ALOLA', 'Known for its extreme intelligence, this Pokémon will look down on inexperienced Trainers, so it’s best suited to veteran Trainers.', 'romfs:/sprites/765.png', 90, 60, 80, 90, 110, 60, 'slow', 'inner-focus', 'telepathy', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (766, 'Passimian', 'Fighting', NULL, 'Alola', 'ALOLA', 'They form groups of roughly 20 individuals. Their mutual bond is remarkable—they will never let down a comrade.', 'romfs:/sprites/766.png', 100, 120, 90, 40, 60, 80, 'slow', 'receiver', 'defiant', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (767, 'Wimpod', 'Bug', 'Water', 'Alola', 'ALOLA', 'This Pokémon is a coward. As it desperately dashes off, the flailing of its many legs leaves a sparkling clean path in its wake.', 'romfs:/sprites/767.png', 25, 35, 40, 20, 30, 80, 'medium', 'wimp-out', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (768, 'Golisopod', 'Bug', 'Water', 'Alola', 'ALOLA', 'With a flashing slash of its giant sharp claws, it cleaves seawater—or even air—right in two.', 'romfs:/sprites/768.png', 75, 125, 140, 60, 90, 40, 'medium', 'emergency-exit', NULL, NULL, 30);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (769, 'Sandygast', 'Ghost', 'Ground', 'Alola', 'ALOLA', 'Born from a sand mound playfully built by a child, this Pokémon embodies the grudges of the departed.', 'romfs:/sprites/769.png', 55, 55, 80, 70, 45, 15, 'medium', 'water-compaction', 'sand-veil', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (770, 'Palossand', 'Ghost', 'Ground', 'Alola', 'ALOLA', 'Possessed people controlled by this Pokémon transformed its sand mound into a castle. As it evolved, its power to curse grew ever stronger.', 'romfs:/sprites/770.png', 85, 75, 110, 100, 75, 35, 'medium', 'water-compaction', 'sand-veil', NULL, 42);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (771, 'Pyukumuku', 'Water', NULL, 'Alola', 'ALOLA', 'It’s covered in a slime that keeps its skin moist, allowing it to stay on land for days without drying up.', 'romfs:/sprites/771.png', 55, 60, 130, 30, 130, 5, 'fast', 'innards-out', 'unaware', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (772, 'Type-null', 'Normal', NULL, 'Alola', 'ALOLA', 'The heavy control mask it wears suppresses its intrinsic capabilities. This Pokémon has some hidden special power.', 'romfs:/sprites/772.png', 95, 95, 95, 95, 95, 59, 'slow', 'battle-armor', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (773, 'Silvally', 'Normal', NULL, 'Alola', 'ALOLA', 'Its trust in its partner is what awakens it. This Pokémon is capable of changing its type, a flexibility that is well displayed in battle.', 'romfs:/sprites/773.png', 95, 95, 95, 95, 95, 95, 'slow', 'rks-system', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (774, 'Minior-red-meteor', 'Rock', 'Flying', 'Alola', 'ALOLA', 'Originally making its home in the ozone layer, it hurtles to the ground when the shell enclosing its body grows too heavy.', 'romfs:/sprites/774.png', 60, 60, 100, 60, 100, 60, 'medium-slow', 'shields-down', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (775, 'Komala', 'Normal', NULL, 'Alola', 'ALOLA', 'It is born asleep, and it dies asleep. All its movements are apparently no more than the results of it tossing and turning in its dreams.', 'romfs:/sprites/775.png', 65, 115, 65, 75, 95, 65, 'slow', 'comatose', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (776, 'Turtonator', 'Fire', 'Dragon', 'Alola', 'ALOLA', 'The shell on its back is chemically unstable and explodes violently if struck. The hole in its stomach is its weak point.', 'romfs:/sprites/776.png', 60, 78, 135, 91, 85, 36, 'medium', 'shell-armor', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (777, 'Togedemaru', 'Electric', 'Steel', 'Alola', 'ALOLA', 'The spiny fur on its back is normally at rest. When this Pokémon becomes agitated, its fur stands on end and stabs into its attackers.', 'romfs:/sprites/777.png', 65, 98, 63, 40, 73, 96, 'medium', 'iron-barbs', 'lightning-rod', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (778, 'Mimikyu-disguised', 'Ghost', 'Fairy', 'Alola', 'ALOLA', 'Its actual appearance is unknown. A scholar who saw what was under its rag was overwhelmed by terror and died from the shock.', 'romfs:/sprites/778.png', 55, 90, 80, 50, 105, 96, 'medium', 'disguise', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (779, 'Bruxish', 'Water', 'Psychic', 'Alola', 'ALOLA', 'When it unleashes its psychic power from the protuberance on its head, the grating sound of grinding teeth echoes through the area.', 'romfs:/sprites/779.png', 68, 105, 70, 70, 70, 92, 'medium', 'dazzling', 'strong-jaw', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (780, 'Drampa', 'Normal', 'Dragon', 'Alola', 'ALOLA', 'It has a compassionate personality, but if it is angered, it completely destroys its surroundings with its intense breath.', 'romfs:/sprites/780.png', 78, 60, 85, 135, 91, 36, 'medium', 'berserk', 'sap-sipper', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (781, 'Dhelmise', 'Ghost', 'Grass', 'Alola', 'ALOLA', 'Swinging its massive anchor, it can KO Wailord in a single blow. What appears to be green seaweed is actually its body.', 'romfs:/sprites/781.png', 70, 131, 100, 86, 90, 40, 'medium', 'steelworker', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (782, 'Jangmo-o', 'Dragon', NULL, 'Alola', 'ALOLA', 'It expresses its feelings by smacking its scales. Metallic sounds echo through the tall mountains where Jangmo-o lives.', 'romfs:/sprites/782.png', 45, 55, 65, 45, 45, 45, 'slow', 'bulletproof', 'soundproof', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (783, 'Hakamo-o', 'Dragon', 'Fighting', 'Alola', 'ALOLA', 'It leaps at its prey with a courageous shout. Its scaly punches tear its opponents to shreds.', 'romfs:/sprites/783.png', 55, 75, 90, 65, 70, 65, 'slow', 'bulletproof', 'soundproof', NULL, 35);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (784, 'Kommo-o', 'Dragon', 'Fighting', 'Alola', 'ALOLA', 'When it spots enemies, it threatens them by jingling the scales on its tail. Weak opponents will crack and flee in panic.', 'romfs:/sprites/784.png', 75, 110, 125, 100, 105, 85, 'slow', 'bulletproof', 'soundproof', NULL, 45);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (785, 'Tapu-koko', 'Electric', 'Fairy', 'Alola', 'ALOLA', 'This guardian deity of Melemele is brimming with curiosity. It summons thunderclouds and stores their lightning inside its body.', 'romfs:/sprites/785.png', 70, 115, 85, 95, 75, 130, 'slow', 'electric-surge', 'telepathy', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (786, 'Tapu-lele', 'Psychic', 'Fairy', 'Alola', 'ALOLA', 'This guardian deity of Akala is guilelessly cruel. The fragrant aroma of flowers is the source of its energy.', 'romfs:/sprites/786.png', 70, 85, 75, 130, 115, 95, 'slow', 'psychic-surge', 'telepathy', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (787, 'Tapu-bulu', 'Grass', 'Fairy', 'Alola', 'ALOLA', 'It pulls large trees up by the roots and swings them around. It causes vegetation to grow, and then it absorbs energy from the growth.', 'romfs:/sprites/787.png', 70, 130, 115, 85, 95, 75, 'slow', 'grassy-surge', 'telepathy', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (788, 'Tapu-fini', 'Water', 'Fairy', 'Alola', 'ALOLA', 'The dense fog it creates brings the downfall and destruction of its confused enemies. Ocean currents are the source of its energy.', 'romfs:/sprites/788.png', 70, 75, 115, 95, 130, 85, 'slow', 'misty-surge', 'telepathy', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (789, 'Cosmog', 'Psychic', NULL, 'Alola', 'ALOLA', 'Its body is gaseous and frail. It slowly grows as it collects dust from the atmosphere.', 'romfs:/sprites/789.png', 43, 29, 31, 29, 31, 37, 'slow', 'unaware', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (790, 'Cosmoem', 'Psychic', NULL, 'Alola', 'ALOLA', 'Motionless as if dead, its body is faintly warm to the touch. In the distant past, it was called the cocoon of the stars.', 'romfs:/sprites/790.png', 43, 29, 131, 29, 131, 37, 'slow', 'sturdy', NULL, NULL, 43);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (791, 'Solgaleo', 'Psychic', 'Steel', 'Alola', 'ALOLA', 'It is said to live in another world. The intense light it radiates from the surface of its body can make the darkest of nights light up like midday.', 'romfs:/sprites/791.png', 137, 137, 107, 113, 89, 97, 'slow', 'full-metal-body', NULL, NULL, 53);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (792, 'Lunala', 'Psychic', 'Ghost', 'Alola', 'ALOLA', 'It is said to be a female evolution of Cosmog. When its third eye activates, away it flies to another world.', 'romfs:/sprites/792.png', 137, 113, 89, 137, 107, 97, 'slow', 'shadow-shield', NULL, NULL, 53);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (793, 'Nihilego', 'Rock', 'Poison', 'Alola', 'ALOLA', 'One of several mysterious Ultra Beasts. People on the street report observing those infested by it suddenly becoming violent.', 'romfs:/sprites/793.png', 109, 53, 47, 127, 131, 103, 'slow', 'beast-boost', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (794, 'Buzzwole', 'Bug', 'Fighting', 'Alola', 'ALOLA', 'This Ultra Beast appeared from another world. It shows off its body, but whether that display is a boast or a threat remains unclear.', 'romfs:/sprites/794.png', 107, 139, 139, 53, 53, 79, 'slow', 'beast-boost', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (795, 'Pheromosa', 'Bug', 'Fighting', 'Alola', 'ALOLA', 'One of the dangerous Ultra Beasts, it has been spotted running across the land at terrific speeds.', 'romfs:/sprites/795.png', 71, 137, 37, 137, 37, 151, 'slow', 'beast-boost', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (796, 'Xurkitree', 'Electric', NULL, 'Alola', 'ALOLA', 'One of the mysterious life-forms known as Ultra Beasts. Astonishing electric shocks emanate from its entire body, according to witnesses.', 'romfs:/sprites/796.png', 83, 89, 71, 173, 71, 83, 'slow', 'beast-boost', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (797, 'Celesteela', 'Steel', 'Flying', 'Alola', 'ALOLA', 'It appeared from the Ultra Wormhole. Witnesses observed it flying across the sky at high speed.', 'romfs:/sprites/797.png', 97, 101, 103, 107, 101, 61, 'slow', 'beast-boost', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (798, 'Kartana', 'Grass', 'Steel', 'Alola', 'ALOLA', 'This Ultra Beast came from the Ultra Wormhole. It seems not to attack enemies on its own, but its sharp body is a dangerous weapon in itself.', 'romfs:/sprites/798.png', 59, 181, 131, 59, 31, 109, 'slow', 'beast-boost', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (799, 'Guzzlord', 'Dark', 'Dragon', 'Alola', 'ALOLA', 'It has gobbled mountains and swallowed whole buildings, according to reports. It’s one of the Ultra Beasts.', 'romfs:/sprites/799.png', 223, 101, 53, 97, 53, 43, 'slow', 'beast-boost', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (800, 'Necrozma', 'Psychic', NULL, 'Alola', 'ALOLA', 'Reminiscent of the Ultra Beasts, this life-form, apparently asleep underground, is thought to have come from another world in ancient times.', 'romfs:/sprites/800.png', 97, 107, 101, 127, 89, 79, 'slow', 'prism-armor', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (801, 'Magearna', 'Steel', 'Fairy', 'Alola', 'ALOLA', 'This artificial Pokémon, constructed more than 500 years ago, can understand human speech but cannot itself speak.', 'romfs:/sprites/801.png', 80, 95, 115, 130, 115, 65, 'slow', 'soul-heart', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (802, 'Marshadow', 'Fighting', 'Ghost', 'Alola', 'ALOLA', 'Able to conceal itself in shadows, it never appears before humans, so its very existence was the stuff of myth.', 'romfs:/sprites/802.png', 90, 125, 80, 90, 90, 125, 'slow', 'technician', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (803, 'Poipole', 'Poison', NULL, 'Alola', 'ALOLA', 'This Ultra Beast is well enough liked to be chosen as a first partner in its own world.', 'romfs:/sprites/803.png', 67, 73, 67, 73, 67, 73, 'slow', 'beast-boost', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (804, 'Naganadel', 'Poison', 'Dragon', 'Alola', 'ALOLA', 'It stores hundreds of liters of poisonous liquid inside its body. It is one of the organisms known as UBs.', 'romfs:/sprites/804.png', 73, 73, 73, 127, 73, 121, 'slow', 'beast-boost', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (805, 'Stakataka', 'Rock', 'Steel', 'Alola', 'ALOLA', 'It appeared from an Ultra Wormhole. Each one appears to be made up of many life-forms stacked one on top of each other.', 'romfs:/sprites/805.png', 61, 131, 211, 53, 101, 13, 'slow', 'beast-boost', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (806, 'Blacephalon', 'Fire', 'Ghost', 'Alola', 'ALOLA', 'It slithers toward people. Then, without warning, it triggers the explosion of its own head. It’s apparently one kind of Ultra Beast.', 'romfs:/sprites/806.png', 53, 127, 53, 151, 79, 107, 'slow', 'beast-boost', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (807, 'Zeraora', 'Electric', NULL, 'Alola', 'ALOLA', 'It electrifies its claws and tears its opponents apart with them. Even if they dodge its attack, they’ll be electrocuted by the flying sparks.', 'romfs:/sprites/807.png', 88, 112, 75, 102, 80, 143, 'slow', 'volt-absorb', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (808, 'Meltan', 'Steel', NULL, 'Alola', 'ALOLA', 'It melts particles of iron and other metals found in the subsoil, so it can absorb them into its body of molten steel.', 'romfs:/sprites/808.png', 46, 65, 65, 55, 35, 34, 'slow', 'magnet-pull', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (809, 'Melmetal', 'Steel', NULL, 'Alola', 'ALOLA', 'Revered long ago for its capacity to create iron from nothing, for some reason it has come back to life after 3,000 years.', 'romfs:/sprites/809.png', 135, 143, 143, 80, 65, 34, 'slow', 'iron-fist', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (810, 'Grookey', 'Grass', NULL, 'Galar', 'SWSH', 'When it uses its special stick to strike up a beat, the sound waves produced carry revitalizing energy to the plants and flowers in the area.', 'romfs:/sprites/810.png', 50, 65, 50, 40, 40, 65, 'medium-slow', 'overgrow', 'grassy-surge', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (811, 'Thwackey', 'Grass', NULL, 'Galar', 'SWSH', 'The faster a Thwackey can beat out a rhythm with its two sticks, the more respect it wins from its peers.', 'romfs:/sprites/811.png', 70, 85, 70, 55, 60, 80, 'medium-slow', 'overgrow', 'grassy-surge', NULL, 16);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (812, 'Rillaboom', 'Grass', NULL, 'Galar', 'SWSH', 'By drumming, it taps into the power of its special tree stump. The roots of the stump follow its direction in battle.', 'romfs:/sprites/812.png', 100, 125, 90, 60, 70, 85, 'medium-slow', 'overgrow', 'grassy-surge', NULL, 35);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (813, 'Scorbunny', 'Fire', NULL, 'Galar', 'SWSH', 'A warm-up of running around gets fire energy coursing through this Pokémon’s body. Once that happens, it’s ready to fight at full power.', 'romfs:/sprites/813.png', 50, 71, 40, 40, 40, 69, 'medium-slow', 'blaze', 'libero', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (814, 'Raboot', 'Fire', NULL, 'Galar', 'SWSH', 'Its thick and fluffy fur protects it from the cold and enables it to use hotter fire moves.', 'romfs:/sprites/814.png', 65, 86, 60, 55, 60, 94, 'medium-slow', 'blaze', 'libero', NULL, 16);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (815, 'Cinderace', 'Fire', NULL, 'Galar', 'SWSH', 'It juggles a pebble with its feet, turning it into a burning soccer ball. Its shots strike opponents hard and leave them scorched.', 'romfs:/sprites/815.png', 80, 116, 75, 65, 75, 119, 'medium-slow', 'blaze', 'libero', NULL, 35);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (816, 'Sobble', 'Water', NULL, 'Galar', 'SWSH', 'When scared, this Pokémon cries. Its tears pack the chemical punch of 100 onions, and attackers won’t be able to resist weeping.', 'romfs:/sprites/816.png', 50, 40, 40, 70, 40, 70, 'medium-slow', 'torrent', 'sniper', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (817, 'Drizzile', 'Water', NULL, 'Galar', 'SWSH', 'A clever combatant, this Pokémon battles using water balloons created with moisture secreted from its palms.', 'romfs:/sprites/817.png', 65, 60, 55, 95, 55, 90, 'medium-slow', 'torrent', 'sniper', NULL, 16);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (818, 'Inteleon', 'Water', NULL, 'Galar', 'SWSH', 'It has many hidden capabilities, such as fingertips that can shoot water and a membrane on its back that it can use to glide through the air.', 'romfs:/sprites/818.png', 70, 85, 65, 125, 65, 120, 'medium-slow', 'torrent', 'sniper', NULL, 35);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (819, 'Skwovet', 'Normal', NULL, 'Galar', 'SWSH', 'Found throughout the Galar region, this Pokémon becomes uneasy if its cheeks are ever completely empty of berries.', 'romfs:/sprites/819.png', 70, 55, 55, 35, 35, 25, 'medium', 'cheek-pouch', 'gluttony', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (820, 'Greedent', 'Normal', NULL, 'Galar', 'SWSH', 'It stashes berries in its tail—so many berries that they fall out constantly. But this Pokémon is a bit slow-witted, so it doesn’t notice the loss.', 'romfs:/sprites/820.png', 120, 95, 95, 55, 75, 20, 'medium', 'cheek-pouch', 'gluttony', NULL, 24);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (821, 'Rookidee', 'Flying', NULL, 'Galar', 'SWSH', 'It will bravely challenge any opponent, no matter how powerful. This Pokémon benefits from every battle—even a defeat increases its strength a bit.', 'romfs:/sprites/821.png', 38, 47, 35, 33, 35, 57, 'medium-slow', 'keen-eye', 'unnerve', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (822, 'Corvisquire', 'Flying', NULL, 'Galar', 'SWSH', 'Smart enough to use tools in battle, these Pokémon have been seen picking up rocks and flinging them or using ropes to wrap up enemies.', 'romfs:/sprites/822.png', 68, 67, 55, 43, 55, 77, 'medium-slow', 'keen-eye', 'unnerve', NULL, 18);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (823, 'Corviknight', 'Flying', 'Steel', 'Galar', 'SWSH', 'This Pokémon reigns supreme in the skies of the Galar region. The black luster of its steel body could drive terror into the heart of any foe.', 'romfs:/sprites/823.png', 98, 87, 105, 53, 85, 67, 'medium-slow', 'pressure', 'unnerve', NULL, 38);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (824, 'Blipbug', 'Bug', NULL, 'Galar', 'SWSH', 'A constant collector of information, this Pokémon is very smart. Very strong is what it isn’t.', 'romfs:/sprites/824.png', 25, 20, 20, 25, 45, 45, 'medium', 'swarm', 'compound-eyes', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (825, 'Dottler', 'Bug', 'Psychic', 'Galar', 'SWSH', 'It barely moves, but it’s still alive. Hiding in its shell without food or water seems to have awakened its psychic powers.', 'romfs:/sprites/825.png', 50, 35, 80, 50, 90, 30, 'medium', 'swarm', 'compound-eyes', NULL, 10);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (826, 'Orbeetle', 'Bug', 'Psychic', 'Galar', 'SWSH', 'It’s famous for its high level of intelligence, and the large size of its brain is proof that it also possesses immense psychic power.', 'romfs:/sprites/826.png', 60, 45, 110, 80, 120, 90, 'medium', 'swarm', 'frisk', NULL, 30);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (827, 'Nickit', 'Dark', NULL, 'Galar', 'SWSH', 'Aided by the soft pads on its feet, it silently raids the food stores of other Pokémon. It survives off its ill-gotten gains.', 'romfs:/sprites/827.png', 40, 28, 28, 47, 52, 50, 'fast', 'run-away', 'unburden', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (828, 'Thievul', 'Dark', NULL, 'Galar', 'SWSH', 'It secretly marks potential targets with a scent. By following the scent, it stalks its targets and steals from them when they least expect it.', 'romfs:/sprites/828.png', 70, 58, 58, 87, 92, 90, 'fast', 'run-away', 'unburden', NULL, 18);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (829, 'Gossifleur', 'Grass', NULL, 'Galar', 'SWSH', 'It anchors itself in the ground with its single leg, then basks in the sun. After absorbing enough sunlight, its petals spread as it blooms brilliantly.', 'romfs:/sprites/829.png', 40, 40, 60, 40, 60, 10, 'medium', 'cotton-down', 'regenerator', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (830, 'Eldegoss', 'Grass', NULL, 'Galar', 'SWSH', 'The seeds attached to its cotton fluff are full of nutrients. It spreads them on the wind so that plants and other Pokémon can benefit from them.', 'romfs:/sprites/830.png', 60, 50, 90, 80, 120, 60, 'medium', 'cotton-down', 'regenerator', NULL, 20);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (831, 'Wooloo', 'Normal', NULL, 'Galar', 'SWSH', 'Its curly fleece is such an effective cushion that this Pokémon could fall off a cliff and stand right back up at the bottom, unharmed.', 'romfs:/sprites/831.png', 42, 40, 55, 40, 45, 48, 'medium', 'fluffy', 'run-away', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (832, 'Dubwool', 'Normal', NULL, 'Galar', 'SWSH', 'Weave a carpet from its springy wool, and you end up with something closer to a trampoline. You’ll start to bounce the moment you set foot on it.', 'romfs:/sprites/832.png', 72, 80, 100, 60, 90, 88, 'medium', 'fluffy', 'steadfast', NULL, 24);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (833, 'Chewtle', 'Water', NULL, 'Galar', 'SWSH', 'Apparently the itch of its teething impels it to snap its jaws at anything in front of it.', 'romfs:/sprites/833.png', 50, 64, 50, 38, 38, 44, 'medium', 'strong-jaw', 'shell-armor', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (834, 'Drednaw', 'Water', 'Rock', 'Galar', 'SWSH', 'With jaws that can shear through steel rods, this highly aggressive Pokémon chomps down on its unfortunate prey.', 'romfs:/sprites/834.png', 90, 115, 90, 48, 68, 74, 'medium', 'strong-jaw', 'shell-armor', NULL, 22);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (835, 'Yamper', 'Electric', NULL, 'Galar', 'SWSH', 'This Pokémon is very popular as a herding dog in the Galar region. As it runs, it generates electricity from the base of its tail.', 'romfs:/sprites/835.png', 59, 45, 50, 40, 50, 26, 'fast', 'ball-fetch', 'rattled', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (836, 'Boltund', 'Electric', NULL, 'Galar', 'SWSH', 'This Pokémon generates electricity and channels it into its legs to keep them going strong. Boltund can run nonstop for three full days.', 'romfs:/sprites/836.png', 69, 90, 60, 90, 60, 121, 'fast', 'strong-jaw', 'competitive', NULL, 25);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (837, 'Rolycoly', 'Rock', NULL, 'Galar', 'SWSH', 'Most of its body has the same composition as coal. Fittingly, this Pokémon was first discovered in coal mines about 400 years ago.', 'romfs:/sprites/837.png', 30, 40, 50, 40, 50, 30, 'medium-slow', 'steam-engine', 'heatproof', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (838, 'Carkol', 'Rock', 'Fire', 'Galar', 'SWSH', 'It forms coal inside its body. Coal dropped by this Pokémon once helped fuel the lives of people in the Galar region.', 'romfs:/sprites/838.png', 80, 60, 90, 60, 70, 50, 'medium-slow', 'steam-engine', 'flame-body', NULL, 18);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (839, 'Coalossal', 'Rock', 'Fire', 'Galar', 'SWSH', 'It’s usually peaceful, but the vandalism of mines enrages it. Offenders will be incinerated with flames that reach 2,700 degrees Fahrenheit.', 'romfs:/sprites/839.png', 110, 80, 120, 80, 90, 30, 'medium-slow', 'steam-engine', 'flame-body', NULL, 34);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (840, 'Applin', 'Grass', 'Dragon', 'Galar', 'SWSH', 'It spends its entire life inside an apple. It hides from its natural enemies, bird Pokémon, by pretending it’s just an apple and nothing more.', 'romfs:/sprites/840.png', 40, 40, 80, 40, 40, 20, 'slow-then-very-fast', 'ripen', 'gluttony', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (841, 'Flapple', 'Grass', 'Dragon', 'Galar', 'SWSH', 'It ate a sour apple, and that induced its evolution. In its cheeks, it stores an acid capable of causing chemical burns.', 'romfs:/sprites/841.png', 70, 110, 80, 95, 60, 70, 'slow-then-very-fast', 'ripen', 'gluttony', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (842, 'Appletun', 'Grass', 'Dragon', 'Galar', 'SWSH', 'Eating a sweet apple caused its evolution. A nectarous scent wafts from its body, luring in the bug Pokémon it preys on.', 'romfs:/sprites/842.png', 110, 85, 80, 100, 80, 30, 'slow-then-very-fast', 'ripen', 'gluttony', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (843, 'Silicobra', 'Ground', NULL, 'Galar', 'SWSH', 'As it digs, it swallows sand and stores it in its neck pouch. The pouch can hold more than 17 pounds of sand.', 'romfs:/sprites/843.png', 52, 57, 75, 35, 50, 46, 'medium', 'sand-spit', 'shed-skin', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (844, 'Sandaconda', 'Ground', NULL, 'Galar', 'SWSH', 'When it contracts its body, over 220 pounds of sand sprays from its nose. If it ever runs out of sand, it becomes disheartened.', 'romfs:/sprites/844.png', 72, 107, 125, 65, 70, 71, 'medium', 'sand-spit', 'shed-skin', NULL, 36);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (845, 'Cramorant', 'Flying', 'Water', 'Galar', 'SWSH', 'It’s so strong that it can knock out some opponents in a single hit, but it also may forget what it’s battling midfight.', 'romfs:/sprites/845.png', 70, 85, 55, 85, 95, 85, 'medium', 'gulp-missile', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (846, 'Arrokuda', 'Water', NULL, 'Galar', 'SWSH', 'If it sees any movement around it, this Pokémon charges for it straightaway, leading with its sharply pointed jaw. It’s very proud of that jaw.', 'romfs:/sprites/846.png', 41, 63, 40, 40, 30, 66, 'slow', 'swift-swim', 'propeller-tail', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (847, 'Barraskewda', 'Water', NULL, 'Galar', 'SWSH', 'This Pokémon has a jaw that’s as sharp as a spear and as strong as steel. Apparently Barraskewda’s flesh is surprisingly tasty, too.', 'romfs:/sprites/847.png', 61, 123, 60, 60, 50, 136, 'slow', 'swift-swim', 'propeller-tail', NULL, 26);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (848, 'Toxel', 'Electric', 'Poison', 'Galar', 'SWSH', 'It stores poison in an internal poison sac and secretes that poison through its skin. If you touch this Pokémon, a tingling sensation follows.', 'romfs:/sprites/848.png', 40, 38, 35, 54, 35, 40, 'medium-slow', 'rattled', 'static', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (849, 'Toxtricity-amped', 'Electric', 'Poison', 'Galar', 'SWSH', 'When this Pokémon sounds as if it’s strumming a guitar, it’s actually clawing at the protrusions on its chest to generate electricity.', 'romfs:/sprites/849.png', 75, 98, 70, 114, 70, 75, 'medium-slow', 'punk-rock', 'plus', NULL, 30);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (850, 'Sizzlipede', 'Fire', 'Bug', 'Galar', 'SWSH', 'It stores flammable gas in its body and uses it to generate heat. The yellow sections on its belly get particularly hot.', 'romfs:/sprites/850.png', 50, 65, 45, 50, 50, 45, 'medium', 'flash-fire', 'white-smoke', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (851, 'Centiskorch', 'Fire', 'Bug', 'Galar', 'SWSH', 'When it heats up, its body temperature reaches about 1,500 degrees Fahrenheit. It lashes its body like a whip and launches itself at enemies.', 'romfs:/sprites/851.png', 100, 115, 65, 90, 90, 65, 'medium', 'flash-fire', 'white-smoke', NULL, 28);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (852, 'Clobbopus', 'Fighting', NULL, 'Galar', 'SWSH', 'It’s very curious, but its means of investigating things is to try to punch them with its tentacles. The search for food is what brings it onto land.', 'romfs:/sprites/852.png', 50, 68, 60, 50, 50, 32, 'medium-slow', 'limber', 'technician', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (853, 'Grapploct', 'Fighting', NULL, 'Galar', 'SWSH', 'A body made up of nothing but muscle makes the grappling moves this Pokémon performs with its tentacles tremendously powerful.', 'romfs:/sprites/853.png', 80, 118, 90, 70, 80, 42, 'medium-slow', 'limber', 'technician', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (854, 'Sinistea', 'Ghost', NULL, 'Galar', 'SWSH', 'This Pokémon is said to have been born when a lonely spirit possessed a cold, leftover cup of tea.', 'romfs:/sprites/854.png', 40, 45, 45, 74, 54, 50, 'medium', 'weak-armor', 'cursed-body', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (855, 'Polteageist', 'Ghost', NULL, 'Galar', 'SWSH', 'This species lives in antique teapots. Most pots are forgeries, but on rare occasions, an authentic work is found.', 'romfs:/sprites/855.png', 60, 65, 65, 134, 114, 70, 'medium', 'weak-armor', 'cursed-body', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (856, 'Hatenna', 'Psychic', NULL, 'Galar', 'SWSH', 'Via the protrusion on its head, it senses other creatures’ emotions. If you don’t have a calm disposition, it will never warm up to you.', 'romfs:/sprites/856.png', 42, 30, 45, 56, 53, 39, 'slow', 'healer', 'anticipation', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (857, 'Hattrem', 'Psychic', NULL, 'Galar', 'SWSH', 'No matter who you are, if you bring strong emotions near this Pokémon, it will silence you violently.', 'romfs:/sprites/857.png', 57, 40, 65, 86, 73, 49, 'slow', 'healer', 'anticipation', NULL, 32);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (858, 'Hatterene', 'Psychic', 'Fairy', 'Galar', 'SWSH', 'It emits psychic power strong enough to cause headaches as a deterrent to the approach of others.', 'romfs:/sprites/858.png', 57, 90, 95, 136, 103, 29, 'slow', 'healer', 'anticipation', NULL, 42);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (859, 'Impidimp', 'Dark', 'Fairy', 'Galar', 'SWSH', 'Through its nose, it sucks in the emanations produced by people and Pokémon when they feel annoyed. It thrives off this negative energy.', 'romfs:/sprites/859.png', 45, 45, 30, 55, 40, 50, 'medium', 'prankster', 'frisk', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (860, 'Morgrem', 'Dark', 'Fairy', 'Galar', 'SWSH', 'When it gets down on all fours as if to beg for forgiveness, it’s trying to lure opponents in so that it can stab them with its spear-like hair.', 'romfs:/sprites/860.png', 65, 60, 45, 75, 55, 70, 'medium', 'prankster', 'frisk', NULL, 32);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (861, 'Grimmsnarl', 'Dark', 'Fairy', 'Galar', 'SWSH', 'With the hair wrapped around its body helping to enhance its muscles, this Pokémon can overwhelm even Machamp.', 'romfs:/sprites/861.png', 95, 120, 65, 95, 75, 60, 'medium', 'prankster', 'frisk', NULL, 42);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (862, 'Obstagoon', 'Dark', 'Normal', 'Galar', 'SWSH', 'Its voice is staggering in volume. Obstagoon has a tendency to take on a threatening posture and shout—this move is known as Obstruct.', 'romfs:/sprites/862.png', 93, 90, 101, 60, 81, 95, 'medium', 'reckless', 'guts', NULL, 35);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (863, 'Perrserker', 'Steel', NULL, 'Galar', 'SWSH', 'What appears to be an iron helmet is actually hardened hair. This Pokémon lives for the thrill of battle.', 'romfs:/sprites/863.png', 70, 110, 100, 50, 60, 50, 'medium', 'battle-armor', 'tough-claws', NULL, 28);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (864, 'Cursola', 'Ghost', NULL, 'Galar', 'SWSH', 'Its shell is overflowing with its heightened otherworldly energy. The ectoplasm serves as protection for this Pokémon’s core spirit.', 'romfs:/sprites/864.png', 60, 95, 50, 145, 130, 30, 'fast', 'weak-armor', 'perish-body', NULL, 38);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (865, 'Sirfetchd', 'Fighting', NULL, 'Galar', 'SWSH', 'Only Farfetch’d that have survived many battles can attain this evolution. When this Pokémon’s leek withers, it will retire from combat.', 'romfs:/sprites/865.png', 62, 135, 95, 68, 82, 65, 'medium', 'steadfast', 'scrappy', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (866, 'Mr-rime', 'Ice', 'Psychic', 'Galar', 'SWSH', 'It’s highly skilled at tap-dancing. It waves its cane of ice in time with its graceful movements.', 'romfs:/sprites/866.png', 80, 85, 75, 110, 100, 70, 'medium', 'tangled-feet', 'screen-cleaner', NULL, 42);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (867, 'Runerigus', 'Ground', 'Ghost', 'Galar', 'SWSH', 'A powerful curse was woven into an ancient painting. After absorbing the spirit of a Yamask, the painting began to move.', 'romfs:/sprites/867.png', 58, 95, 145, 50, 105, 30, 'medium', 'wandering-spirit', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (868, 'Milcery', 'Fairy', NULL, 'Galar', 'SWSH', 'This Pokémon was born from sweet-smelling particles in the air. Its body is made of cream.', 'romfs:/sprites/868.png', 45, 40, 40, 50, 61, 34, 'medium', 'sweet-veil', 'aroma-veil', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (869, 'Alcremie', 'Fairy', NULL, 'Galar', 'SWSH', 'When it trusts a Trainer, it will treat them to berries it’s decorated with cream.', 'romfs:/sprites/869.png', 65, 60, 75, 110, 121, 64, 'medium', 'sweet-veil', 'aroma-veil', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (870, 'Falinks', 'Fighting', NULL, 'Galar', 'SWSH', 'Five of them are troopers, and one is the brass. The brass’s orders are absolute.', 'romfs:/sprites/870.png', 65, 100, 100, 70, 60, 75, 'medium', 'battle-armor', 'defiant', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (871, 'Pincurchin', 'Electric', NULL, 'Galar', 'SWSH', 'It feeds on seaweed, using its teeth to scrape it off rocks. Electric current flows from the tips of its spines.', 'romfs:/sprites/871.png', 48, 101, 95, 91, 85, 15, 'medium', 'lightning-rod', 'electric-surge', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (872, 'Snom', 'Ice', 'Bug', 'Galar', 'SWSH', 'It spits out thread imbued with a frigid sort of energy and uses it to tie its body to branches, disguising itself as an icicle while it sleeps.', 'romfs:/sprites/872.png', 30, 25, 35, 45, 30, 20, 'medium', 'shield-dust', 'ice-scales', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (873, 'Frosmoth', 'Ice', 'Bug', 'Galar', 'SWSH', 'Icy scales fall from its wings like snow as it flies over fields and mountains. The temperature of its wings is less than −290 degrees Fahrenheit.', 'romfs:/sprites/873.png', 70, 65, 60, 125, 90, 65, 'medium', 'shield-dust', 'ice-scales', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (874, 'Stonjourner', 'Rock', NULL, 'Galar', 'SWSH', 'It stands in grasslands, watching the sun’s descent from zenith to horizon. This Pokémon has a talent for delivering dynamic kicks.', 'romfs:/sprites/874.png', 100, 125, 135, 20, 20, 70, 'slow', 'power-spot', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (875, 'Eiscue-ice', 'Ice', NULL, 'Galar', 'SWSH', 'It drifted in on the flow of ocean waters from a frigid place. It keeps its head iced constantly to make sure it stays nice and cold.', 'romfs:/sprites/875.png', 75, 80, 110, 65, 90, 50, 'slow', 'ice-face', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (876, 'Indeedee-male', 'Psychic', 'Normal', 'Galar', 'SWSH', 'It uses the horns on its head to sense the emotions of others. Males will act as valets for those they serve, looking after their every need.', 'romfs:/sprites/876.png', 60, 65, 55, 105, 95, 95, 'fast', 'inner-focus', 'synchronize', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (877, 'Morpeko-full-belly', 'Electric', 'Dark', 'Galar', 'SWSH', 'As it eats the seeds stored up in its pocket-like pouches, this Pokémon is not just satisfying its constant hunger. It’s also generating electricity.', 'romfs:/sprites/877.png', 58, 95, 58, 70, 58, 97, 'medium', 'hunger-switch', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (878, 'Cufant', 'Steel', NULL, 'Galar', 'SWSH', 'It digs up the ground with its trunk. It’s also very strong, being able to carry loads of over five tons without any problem at all.', 'romfs:/sprites/878.png', 72, 80, 49, 40, 49, 40, 'medium', 'sheer-force', 'heavy-metal', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (879, 'Copperajah', 'Steel', NULL, 'Galar', 'SWSH', 'They came over from another region long ago and worked together with humans. Their green skin is resistant to water.', 'romfs:/sprites/879.png', 122, 130, 69, 80, 69, 30, 'medium', 'sheer-force', 'heavy-metal', NULL, 34);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (880, 'Dracozolt', 'Electric', 'Dragon', 'Galar', 'SWSH', 'In ancient times, it was unbeatable thanks to its powerful lower body, but it went extinct anyway after it depleted all its plant-based food sources.', 'romfs:/sprites/880.png', 90, 100, 90, 80, 70, 75, 'slow', 'volt-absorb', 'hustle', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (881, 'Arctozolt', 'Electric', 'Ice', 'Galar', 'SWSH', 'The shaking of its freezing upper half is what generates its electricity. It has a hard time walking around.', 'romfs:/sprites/881.png', 90, 100, 90, 90, 80, 55, 'slow', 'volt-absorb', 'static', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (882, 'Dracovish', 'Water', 'Dragon', 'Galar', 'SWSH', 'Powerful legs and jaws made it the apex predator of its time. Its own overhunting of its prey was what drove it to extinction.', 'romfs:/sprites/882.png', 90, 90, 100, 70, 80, 75, 'slow', 'water-absorb', 'strong-jaw', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (883, 'Arctovish', 'Water', 'Ice', 'Galar', 'SWSH', 'Though it’s able to capture prey by freezing its surroundings, it has trouble eating the prey afterward because its mouth is on top of its head.', 'romfs:/sprites/883.png', 90, 90, 100, 80, 90, 55, 'slow', 'water-absorb', 'ice-body', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (884, 'Duraludon', 'Steel', 'Dragon', 'Galar', 'SWSH', 'Its body resembles polished metal, and it’s both lightweight and strong. The only drawback is that it rusts easily.', 'romfs:/sprites/884.png', 70, 95, 115, 120, 50, 85, 'medium', 'light-metal', 'heavy-metal', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (885, 'Dreepy', 'Dragon', 'Ghost', 'Galar', 'SWSH', 'After being reborn as a ghost Pokémon, Dreepy wanders the areas it used to inhabit back when it was alive in prehistoric seas.', 'romfs:/sprites/885.png', 28, 60, 30, 40, 30, 82, 'slow', 'clear-body', 'infiltrator', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (886, 'Drakloak', 'Dragon', 'Ghost', 'Galar', 'SWSH', 'It’s capable of flying faster than 120 mph. It battles alongside Dreepy and dotes on them until they successfully evolve.', 'romfs:/sprites/886.png', 68, 80, 50, 60, 50, 102, 'slow', 'clear-body', 'infiltrator', NULL, 50);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (887, 'Dragapult', 'Dragon', 'Ghost', 'Galar', 'SWSH', 'When it isn’t battling, it keeps Dreepy in the holes on its horns. Once a fight starts, it launches the Dreepy like supersonic missiles.', 'romfs:/sprites/887.png', 88, 120, 75, 100, 75, 142, 'slow', 'clear-body', 'infiltrator', NULL, 60);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (888, 'Zacian', 'Fairy', NULL, 'Galar', 'SWSH', 'Known as a legendary hero, this Pokémon absorbs metal particles, transforming them into a weapon it uses to battle.', 'romfs:/sprites/888.png', 92, 120, 115, 80, 115, 138, 'slow', 'intrepid-sword', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (889, 'Zamazenta', 'Fighting', NULL, 'Galar', 'SWSH', 'In times past, it worked together with a king of the people to save the Galar region. It absorbs metal that it then uses in battle.', 'romfs:/sprites/889.png', 92, 120, 115, 80, 115, 138, 'slow', 'dauntless-shield', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (890, 'Eternatus', 'Poison', 'Dragon', 'Galar', 'SWSH', 'The core on its chest absorbs energy emanating from the lands of the Galar region. This energy is what allows Eternatus to stay active.', 'romfs:/sprites/890.png', 140, 85, 95, 145, 95, 130, 'slow', 'pressure', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (891, 'Kubfu', 'Fighting', NULL, 'Galar', 'SWSH', 'Kubfu trains hard to perfect its moves. The moves it masters will determine which form it takes when it evolves.', 'romfs:/sprites/891.png', 60, 90, 60, 53, 50, 72, 'slow', 'inner-focus', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (892, 'Urshifu-single-strike', 'Fighting', 'Dark', 'Galar', 'SWSH', 'This form of Urshifu is a strong believer in the one-hit KO. Its strategy is to leap in close to foes and land a devastating blow with a hardened fist.', 'romfs:/sprites/892.png', 100, 130, 100, 63, 60, 97, 'slow', 'unseen-fist', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (893, 'Zarude', 'Dark', 'Grass', 'Galar', 'SWSH', 'Within dense forests, this Pokémon lives in a pack with others of its kind. It’s incredibly aggressive, and the other Pokémon of the forest fear it.', 'romfs:/sprites/893.png', 105, 120, 105, 70, 95, 105, 'slow', 'leaf-guard', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (894, 'Regieleki', 'Electric', NULL, 'Galar', 'SWSH', 'This Pokémon is a cluster of electrical energy. It’s said that removing the rings on Regieleki’s body will unleash the Pokémon’s latent power.', 'romfs:/sprites/894.png', 80, 100, 50, 100, 50, 200, 'slow', 'transistor', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (895, 'Regidrago', 'Dragon', NULL, 'Galar', 'SWSH', 'An academic theory proposes that Regidrago’s arms were once the head of an ancient dragon Pokémon. The theory remains unproven.', 'romfs:/sprites/895.png', 200, 100, 50, 100, 50, 80, 'slow', 'dragons-maw', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (896, 'Glastrier', 'Ice', NULL, 'Galar', 'SWSH', 'Glastrier emits intense cold from its hooves. It’s also a belligerent Pokémon—anything it wants, it takes by force.', 'romfs:/sprites/896.png', 100, 145, 130, 65, 110, 30, 'slow', 'chilling-neigh', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (897, 'Spectrier', 'Ghost', NULL, 'Galar', 'SWSH', 'It probes its surroundings with all its senses save one—it doesn’t use its sense of sight. Spectrier’s kicks are said to separate soul from body.', 'romfs:/sprites/897.png', 100, 65, 60, 145, 80, 130, 'slow', 'grim-neigh', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (898, 'Calyrex', 'Psychic', 'Grass', 'Galar', 'SWSH', 'Calyrex is a merciful Pokémon, capable of providing healing and blessings. It reigned over the Galar region in times of yore.', 'romfs:/sprites/898.png', 100, 80, 80, 80, 80, 80, 'slow', 'unnerve', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (899, 'Wyrdeer', 'Normal', 'Psychic', 'Hisui', 'PLA', 'The black orbs shine with an uncanny light when the Pokémon is erecting invisible barriers. The fur shed from its beard retains heat well and is a highly useful material for winter clothing.', 'romfs:/sprites/899.png', 103, 105, 72, 105, 75, 65, 'slow', 'intimidate', 'frisk', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (900, 'Kleavor', 'Bug', 'Rock', 'Hisui', 'PLA', 'A violent creature that fells towering trees with its crude axes and shields itself with hard stone. If one should chance upon this Pokémon in the wilds, one''s only recourse is to flee.', 'romfs:/sprites/900.png', 70, 135, 95, 45, 70, 85, 'medium', 'swarm', 'sheer-force', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (901, 'Ursaluna', 'Ground', 'Normal', 'Hisui', 'PLA', 'I believe it was Hisui''s swampy terrain that gave Ursaluna its burly physique and newfound capacity to manipulate peat at will.', 'romfs:/sprites/901.png', 130, 140, 105, 45, 80, 50, 'medium', 'guts', 'bulletproof', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (902, 'Basculegion-male', 'Water', 'Ghost', 'Hisui', 'PLA', 'Clads itself in the souls of comrades that perished before fulfilling their goals of journeying upstream. No other species throughout all Hisui''s rivers is Basculegion''s equal.', 'romfs:/sprites/902.png', 120, 112, 65, 80, 75, 78, 'medium', 'swift-swim', 'adaptability', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (903, 'Sneasler', 'Fighting', 'Poison', 'Hisui', 'PLA', 'Because of Sneasler''s virulent poison and daunting physical prowess, no other species could hope to best it on the frozen highlands. Preferring solitude, this species does not form packs.', 'romfs:/sprites/903.png', 80, 130, 60, 40, 80, 120, 'medium-slow', 'pressure', 'unburden', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (904, 'Overqwil', 'Dark', 'Poison', 'Hisui', 'PLA', 'Its lancelike spikes and savage temperament have earned it the nickname ”sea fiend.” It slurps up poison to nourish itself.', 'romfs:/sprites/904.png', 85, 115, 95, 65, 65, 85, 'medium', 'poison-point', 'swift-swim', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (905, 'Enamorus-incarnate', 'Fairy', 'Flying', 'Hisui', 'PLA', 'When it flies to this land from across the sea, the bitter winter comes to an end. According to legend, this Pokémon''s love gives rise to the budding of fresh life across Hisui.', 'romfs:/sprites/905.png', 74, 115, 70, 135, 80, 106, 'slow', 'cute-charm', 'contrary', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (906, 'Sprigatito', 'Grass', NULL, 'Paldea', 'SV', 'Its fluffy fur is similar in composition to plants. This Pokémon frequently washes its face to keep it from drying out.', 'romfs:/sprites/906.png', 40, 61, 54, 45, 45, 65, 'medium-slow', 'overgrow', 'protean', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (907, 'Floragato', 'Grass', NULL, 'Paldea', 'SV', 'Floragato deftly wields the vine hidden beneath its long fur, slamming the hard flower bud against its opponents.', 'romfs:/sprites/907.png', 61, 80, 63, 60, 63, 83, 'medium-slow', 'overgrow', 'protean', NULL, 16);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (908, 'Meowscarada', 'Grass', 'Dark', 'Paldea', 'SV', 'This Pokémon uses the reflective fur lining its cape to camouflage the stem of its flower, creating the illusion that the flower is floating.', 'romfs:/sprites/908.png', 76, 110, 70, 81, 70, 123, 'medium-slow', 'overgrow', 'protean', NULL, 36);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (909, 'Fuecoco', 'Fire', NULL, 'Paldea', 'SV', 'It lies on warm rocks and uses the heat absorbed by its square-shaped scales to create fire energy.', 'romfs:/sprites/909.png', 67, 45, 59, 63, 40, 36, 'medium-slow', 'blaze', 'unaware', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (910, 'Crocalor', 'Fire', NULL, 'Paldea', 'SV', 'The combination of Crocalor’s fire energy and overflowing vitality has caused an egg-shaped fireball to appear on the Pokémon’s head.', 'romfs:/sprites/910.png', 81, 55, 78, 90, 58, 49, 'medium-slow', 'blaze', 'unaware', NULL, 16);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (911, 'Skeledirge', 'Fire', 'Ghost', 'Paldea', 'SV', 'The fiery bird changes shape when Skeledirge sings. Rumor has it that the bird was born when the fireball on Skeledirge’s head gained a soul.', 'romfs:/sprites/911.png', 104, 75, 100, 110, 75, 66, 'medium-slow', 'blaze', 'unaware', NULL, 36);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (912, 'Quaxly', 'Water', NULL, 'Paldea', 'SV', 'This Pokémon migrated to Paldea from distant lands long ago. The gel secreted by its feathers repels water and grime."', 'romfs:/sprites/912.png', 55, 65, 45, 50, 45, 50, 'medium-slow', 'torrent', 'moxie', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (913, 'Quaxwell', 'Water', NULL, 'Paldea', 'SV', 'These Pokémon constantly run through shallow waters to train their legs, then compete with each other to see which of them kicks most gracefully.', 'romfs:/sprites/913.png', 70, 85, 65, 65, 60, 65, 'medium-slow', 'torrent', 'moxie', NULL, 16);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (914, 'Quaquaval', 'Water', 'Fighting', 'Paldea', 'SV', 'A single kick from a Quaquaval can send a truck rolling. This Pokémon uses its powerful legs to perform striking dances from far-off lands.', 'romfs:/sprites/914.png', 85, 120, 80, 85, 75, 85, 'medium-slow', 'torrent', 'moxie', NULL, 36);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (915, 'Lechonk', 'Normal', NULL, 'Paldea', 'SV', 'It searches for food all day. It possesses a keen sense of smell but doesn’t use it for anything other than foraging.', 'romfs:/sprites/915.png', 54, 45, 40, 35, 45, 35, 'medium', 'aroma-veil', 'gluttony', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (916, 'Oinkologne-male', 'Normal', NULL, 'Paldea', 'SV', 'Oinkologne is proud of its fine, glossy skin. It emits a concentrated scent from the tip of its tail.', 'romfs:/sprites/916.png', 110, 100, 75, 59, 80, 65, 'medium', 'lingering-aroma', 'gluttony', NULL, 18);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (917, 'Tarountula', 'Bug', NULL, 'Paldea', 'SV', 'The ball of threads wrapped around its body is elastic enough to deflect the scythes of Scyther, this Pokémon’s natural enemy.', 'romfs:/sprites/917.png', 35, 41, 45, 29, 40, 20, 'slow-then-very-fast', 'insomnia', 'stakeout', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (918, 'Spidops', 'Bug', NULL, 'Paldea', 'SV', 'It clings to branches and ceilings using its threads and moves without a sound. It takes out its prey before the prey even notices it.', 'romfs:/sprites/918.png', 60, 79, 92, 52, 86, 35, 'slow-then-very-fast', 'insomnia', 'stakeout', NULL, 15);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (919, 'Nymble', 'Bug', NULL, 'Paldea', 'SV', 'It has its third set of legs folded up. When it’s in a tough spot, this Pokémon jumps over 30 feet using the strength of its legs.', 'romfs:/sprites/919.png', 33, 46, 40, 21, 25, 45, 'medium', 'swarm', 'tinted-lens', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (920, 'Lokix', 'Bug', 'Dark', 'Paldea', 'SV', 'When it decides to fight all out, it stands on its previously folded legs to enter Showdown Mode. It neutralizes its enemies in short order.', 'romfs:/sprites/920.png', 71, 102, 78, 52, 55, 92, 'medium', 'swarm', 'tinted-lens', NULL, 24);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (921, 'Pawmi', 'Electric', NULL, 'Paldea', 'SV', 'It has underdeveloped electric sacs on its cheeks. These sacs can produce electricity only if Pawmi rubs them furiously with the pads on its forepaws.', 'romfs:/sprites/921.png', 45, 50, 20, 40, 25, 60, 'medium', 'static', 'natural-cure', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (922, 'Pawmo', 'Electric', 'Fighting', 'Paldea', 'SV', 'When its group is attacked, Pawmo is the first to leap into battle, defeating enemies with a fighting technique that utilizes electric shocks.', 'romfs:/sprites/922.png', 60, 75, 40, 50, 40, 85, 'medium', 'volt-absorb', 'natural-cure', NULL, 18);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (923, 'Pawmot', 'Electric', 'Fighting', 'Paldea', 'SV', 'This Pokémon normally is slow to react, but once it enters battle, it will strike down its enemies with lightning-fast movements.', 'romfs:/sprites/923.png', 70, 115, 70, 70, 60, 105, 'medium', 'volt-absorb', 'natural-cure', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (924, 'Tandemaus', 'Normal', NULL, 'Paldea', 'SV', 'Exhibiting great teamwork, they use their incisors to cut pieces out of any material that might be useful for a nest, then make off with them.', 'romfs:/sprites/924.png', 50, 50, 45, 40, 45, 75, 'fast', 'run-away', 'pickup', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (925, 'Maushold-family-of-four', 'Normal', NULL, 'Paldea', 'SV', 'The two little ones just appeared one day. The group might be a family of related Pokémon, but nobody knows for sure.', 'romfs:/sprites/925.png', 74, 75, 70, 65, 75, 111, 'fast', 'friend-guard', 'cheek-pouch', NULL, 25);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (926, 'Fidough', 'Fairy', NULL, 'Paldea', 'SV', 'This Pokémon is smooth and moist to the touch. Yeast in Fidough’s breath induces fermentation in the Pokémon’s vicinity.', 'romfs:/sprites/926.png', 37, 55, 70, 30, 55, 65, 'medium-slow', 'own-tempo', 'klutz', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (927, 'Dachsbun', 'Fairy', NULL, 'Paldea', 'SV', 'The pleasant aroma that emanates from this Pokémon’s body helps wheat grow, so Dachsbun has been treasured by farming villages.', 'romfs:/sprites/927.png', 57, 80, 115, 50, 80, 95, 'medium-slow', 'well-baked-body', 'aroma-veil', NULL, 26);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (928, 'Smoliv', 'Grass', 'Normal', 'Paldea', 'SV', 'It protects itself from enemies by emitting oil from the fruit on its head. This oil is bitter and astringent enough to make someone flinch.', 'romfs:/sprites/928.png', 41, 35, 45, 58, 51, 30, 'medium-slow', 'early-bird', 'harvest', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (929, 'Dolliv', 'Grass', 'Normal', 'Paldea', 'SV', 'Dolliv shares its tasty, fresh-scented oil with others. This species has coexisted with humans since times long gone.', 'romfs:/sprites/929.png', 52, 53, 60, 78, 78, 33, 'medium-slow', 'early-bird', 'harvest', NULL, 25);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (930, 'Arboliva', 'Grass', 'Normal', 'Paldea', 'SV', 'This calm Pokémon is very compassionate. It will share its delicious, nutrient-rich oil with weakened Pokémon.', 'romfs:/sprites/930.png', 78, 69, 90, 125, 109, 39, 'medium-slow', 'seed-sower', 'harvest', NULL, 35);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (931, 'Squawkabilly-green-plumage', 'Normal', 'Flying', 'Paldea', 'SV', 'These Pokémon prefer to live in cities. They form flocks based on the color of their feathers, and they fight over territory.', 'romfs:/sprites/931.png', 82, 96, 51, 45, 51, 92, 'slow-then-very-fast', 'intimidate', 'hustle', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (932, 'Nacli', 'Rock', NULL, 'Paldea', 'SV', 'It was born in a layer of rock salt deep under the earth. This species was particularly treasured in the old days, as they would share precious salt.', 'romfs:/sprites/932.png', 55, 55, 75, 35, 35, 25, 'medium-slow', 'purifying-salt', 'sturdy', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (933, 'Naclstack', 'Rock', NULL, 'Paldea', 'SV', 'This Pokémon dry cures its prey by spraying salt over them. The curing process steals away the water in the prey’s body.', 'romfs:/sprites/933.png', 60, 60, 100, 35, 65, 35, 'medium-slow', 'purifying-salt', 'sturdy', NULL, 24);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (934, 'Garganacl', 'Rock', NULL, 'Paldea', 'SV', 'Garganacl will rub its fingertips together and sprinkle injured Pokémon with salt. Even severe wounds will promptly heal afterward.', 'romfs:/sprites/934.png', 100, 100, 130, 45, 90, 35, 'medium-slow', 'purifying-salt', 'sturdy', NULL, 38);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (935, 'Charcadet', 'Fire', NULL, 'Paldea', 'SV', 'Burnt charcoal came to life and became a Pokémon. Possessing a fiery fighting spirit, Charcadet will battle even tough opponents.', 'romfs:/sprites/935.png', 40, 50, 40, 50, 40, 35, 'slow', 'flash-fire', 'flame-body', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (936, 'Armarouge', 'Fire', 'Psychic', 'Paldea', 'SV', 'Armarouge evolved through the use of a set of armor that belonged to a distinguished warrior. This Pokémon is incredibly loyal.', 'romfs:/sprites/936.png', 85, 60, 100, 125, 80, 75, 'slow', 'flash-fire', 'weak-armor', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (937, 'Ceruledge', 'Fire', 'Ghost', 'Paldea', 'SV', 'The fiery blades on its arms burn fiercely with the lingering resentment of a sword wielder who fell before accomplishing their goal.', 'romfs:/sprites/937.png', 75, 125, 80, 60, 100, 85, 'slow', 'flash-fire', 'weak-armor', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (938, 'Tadbulb', 'Electric', NULL, 'Paldea', 'SV', 'Tadbulb shakes its tail to generate electricity. If it senses danger, it will make its head blink on and off to alert its allies.', 'romfs:/sprites/938.png', 61, 31, 41, 59, 35, 45, 'medium', 'own-tempo', 'static', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (939, 'Bellibolt', 'Electric', NULL, 'Paldea', 'SV', 'When this Pokémon expands and contracts its wobbly body, the belly-button dynamo in its stomach produces a huge amount of electricity.', 'romfs:/sprites/939.png', 109, 64, 91, 103, 83, 45, 'medium', 'electromorphosis', 'static', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (940, 'Wattrel', 'Electric', 'Flying', 'Paldea', 'SV', 'When its wings catch the wind, the bones within produce electricity. This Pokémon dives into the ocean, catching prey by electrocuting them.', 'romfs:/sprites/940.png', 40, 40, 35, 55, 40, 70, 'medium-slow', 'wind-power', 'volt-absorb', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (941, 'Kilowattrel', 'Electric', 'Flying', 'Paldea', 'SV', 'Kilowattrel inflates its throat sac to amplify its electricity. By riding the wind, this Pokémon can fly over 430 miles in a day.', 'romfs:/sprites/941.png', 70, 70, 60, 105, 60, 125, 'medium-slow', 'wind-power', 'volt-absorb', NULL, 25);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (942, 'Maschiff', 'Dark', NULL, 'Paldea', 'SV', 'It always scowls in an attempt to make opponents take it seriously, but even crying children will burst into laughter when they see Maschiff’s face.', 'romfs:/sprites/942.png', 60, 78, 60, 40, 51, 51, 'medium-slow', 'intimidate', 'run-away', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (943, 'Mabosstiff', 'Dark', NULL, 'Paldea', 'SV', 'This Pokémon can store energy in its large dewlap. Mabosstiff unleashes this energy all at once to blow away enemies.', 'romfs:/sprites/943.png', 80, 120, 90, 60, 70, 85, 'medium-slow', 'intimidate', 'guard-dog', NULL, 30);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (944, 'Shroodle', 'Poison', 'Normal', 'Paldea', 'SV', 'Though usually a mellow Pokémon, it will sink its sharp, poison-soaked front teeth into any that anger it, causing paralysis in the object of its ire.', 'romfs:/sprites/944.png', 40, 65, 35, 40, 35, 75, 'medium-slow', 'unburden', 'pickpocket', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (945, 'Grafaiai', 'Poison', 'Normal', 'Paldea', 'SV', 'The color of the poisonous saliva depends on what the Pokémon eats. Grafaiai covers its fingers in its saliva and draws patterns on trees in forests.', 'romfs:/sprites/945.png', 63, 95, 65, 80, 72, 110, 'medium-slow', 'unburden', 'poison-touch', NULL, 28);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (946, 'Bramblin', 'Grass', 'Ghost', 'Paldea', 'SV', 'A soul unable to move on to the afterlife was blown around by the wind until it got tangled up with dried grass and became a Pokémon.', 'romfs:/sprites/946.png', 40, 65, 30, 45, 35, 60, 'medium', 'wind-rider', 'infiltrator', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (947, 'Brambleghast', 'Grass', 'Ghost', 'Paldea', 'SV', 'It will open the branches of its head to envelop its prey. Once it absorbs all the life energy it needs, it expels the prey and discards it.', 'romfs:/sprites/947.png', 55, 115, 70, 80, 70, 90, 'medium', 'wind-rider', 'infiltrator', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (948, 'Toedscool', 'Ground', 'Grass', 'Paldea', 'SV', 'Toedscool lives in muggy forests. The flaps that fall from its body are chewy and very delicious.', 'romfs:/sprites/948.png', 40, 40, 35, 50, 100, 70, 'medium-slow', 'mycelium-might', 'mycelium-might', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (949, 'Toedscruel', 'Ground', 'Grass', 'Paldea', 'SV', 'These Pokémon gather into groups and form colonies deep within forests. They absolutely hate it when strangers approach.', 'romfs:/sprites/949.png', 80, 70, 65, 80, 120, 100, 'medium-slow', 'mycelium-might', 'mycelium-might', NULL, 30);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (950, 'Klawf', 'Rock', NULL, 'Paldea', 'SV', 'Klawf hangs upside-down from cliffs, waiting for prey. But Klawf can’t remain in this position for long because its blood rushes to its head.', 'romfs:/sprites/950.png', 70, 100, 115, 35, 55, 75, 'medium', 'anger-shell', 'shell-armor', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (951, 'Capsakid', 'Grass', NULL, 'Paldea', 'SV', 'The more sunlight this Pokémon bathes in, the more spicy chemicals are produced by its body, and thus the spicier its moves become.', 'romfs:/sprites/951.png', 50, 62, 40, 62, 40, 50, 'medium', 'chlorophyll', 'insomnia', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (952, 'Scovillain', 'Grass', 'Fire', 'Paldea', 'SV', 'The red head converts spicy chemicals into fire energy and blasts the surrounding area with a super spicy stream of flame.', 'romfs:/sprites/952.png', 65, 108, 65, 108, 65, 75, 'medium', 'chlorophyll', 'insomnia', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (953, 'Rellor', 'Bug', NULL, 'Paldea', 'SV', 'This Pokémon creates a mud ball by mixing sand and dirt with psychic energy. It treasures its mud ball more than its own life.', 'romfs:/sprites/953.png', 41, 50, 60, 31, 58, 30, 'fast', 'compound-eyes', 'shed-skin', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (954, 'Rabsca', 'Bug', 'Psychic', 'Paldea', 'SV', 'The body that supports the ball barely moves. Therefore, it is thought that the true body of this Pokémon is actually inside the ball.', 'romfs:/sprites/954.png', 75, 50, 85, 115, 100, 45, 'fast', 'synchronize', 'telepathy', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (955, 'Flittle', 'Psychic', NULL, 'Paldea', 'SV', 'Flittle’s toes levitate about half an inch above the ground because of the psychic power emitted from the frills on the Pokémon’s belly.', 'romfs:/sprites/955.png', 30, 35, 30, 55, 30, 75, 'medium-slow', 'anticipation', 'frisk', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (956, 'Espathra', 'Psychic', NULL, 'Paldea', 'SV', 'It immobilizes opponents by bathing them in psychic power from its large eyes. Despite its appearance, it has a vicious temperament.', 'romfs:/sprites/956.png', 95, 60, 60, 101, 60, 105, 'medium-slow', 'opportunist', 'frisk', NULL, 35);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (957, 'Tinkatink', 'Fairy', 'Steel', 'Paldea', 'SV', 'It swings its handmade hammer around to protect itself, but the hammer is often stolen by Pokémon that eat metal.', 'romfs:/sprites/957.png', 50, 45, 45, 35, 64, 58, 'medium-slow', 'mold-breaker', 'own-tempo', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (958, 'Tinkatuff', 'Fairy', 'Steel', 'Paldea', 'SV', 'This Pokémon will attack groups of Pawniard and Bisharp, gathering metal from them in order to create a large and sturdy hammer.', 'romfs:/sprites/958.png', 65, 55, 55, 45, 82, 78, 'medium-slow', 'mold-breaker', 'own-tempo', NULL, 24);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (959, 'Tinkaton', 'Fairy', 'Steel', 'Paldea', 'SV', 'This intelligent Pokémon has a very daring disposition. It knocks rocks into the sky with its hammer, aiming for flying Corviknight.', 'romfs:/sprites/959.png', 85, 75, 77, 70, 105, 94, 'medium-slow', 'mold-breaker', 'own-tempo', NULL, 38);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (960, 'Wiglett', 'Water', NULL, 'Paldea', 'SV', 'This Pokémon can pick up the scent of a Veluza just over 65 feet away and will hide itself in the sand.', 'romfs:/sprites/960.png', 10, 55, 25, 35, 25, 95, 'medium', 'gooey', 'rattled', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (961, 'Wugtrio', 'Water', NULL, 'Paldea', 'SV', 'It has a vicious temperament, contrary to what its appearance may suggest. It wraps its long bodies around prey, then drags the prey into its den.', 'romfs:/sprites/961.png', 35, 100, 50, 50, 70, 120, 'medium', 'gooey', 'rattled', NULL, 26);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (962, 'Bombirdier', 'Flying', 'Dark', 'Paldea', 'SV', 'It gathers things up in an apron made from shed feathers added to the Pokémon’s chest feathers, then drops those things from high places for fun.', 'romfs:/sprites/962.png', 70, 103, 85, 60, 85, 82, 'slow', 'big-pecks', 'keen-eye', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (963, 'Finizen', 'Water', NULL, 'Paldea', 'SV', 'It likes playing with others of its kind using the water ring on its tail. It uses ultrasonic waves to sense the emotions of other living creatures.', 'romfs:/sprites/963.png', 70, 45, 40, 45, 40, 75, 'slow', 'water-veil', 'water-veil', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (964, 'Palafin-zero', 'Water', NULL, 'Paldea', 'SV', 'This Pokémon changes its appearance if it hears its allies calling for help. Palafin will never show anybody its moment of transformation.', 'romfs:/sprites/964.png', 100, 70, 72, 53, 62, 100, 'slow', 'zero-to-hero', 'zero-to-hero', NULL, 38);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (965, 'Varoom', 'Steel', 'Poison', 'Paldea', 'SV', 'It is said that this Pokémon was born when an unknown poison Pokémon entered and inspirited an engine left at a scrap-processing factory.', 'romfs:/sprites/965.png', 45, 70, 63, 30, 45, 47, 'medium', 'overcoat', 'slow-start', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (966, 'Revavroom', 'Steel', 'Poison', 'Paldea', 'SV', 'It creates a gas out of poison and minerals from rocks. It then detonates the gas in its cylinders—now numbering eight—to generate energy.', 'romfs:/sprites/966.png', 80, 119, 90, 54, 67, 90, 'medium', 'overcoat', 'filter', NULL, 40);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (967, 'Cyclizar', 'Dragon', 'Normal', 'Paldea', 'SV', 'Apparently Cyclizar has been allowing people to ride on its back since ancient times. Depictions of this have been found in 10,000-year-old murals.', 'romfs:/sprites/967.png', 70, 95, 65, 85, 65, 121, 'medium-slow', 'shed-skin', 'regenerator', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (968, 'Orthworm', 'Steel', NULL, 'Paldea', 'SV', 'When attacked, this Pokémon will wield the tendrils on its body like fists and pelt the opponent with a storm of punches.', 'romfs:/sprites/968.png', 70, 85, 145, 60, 55, 65, 'slow', 'earth-eater', 'sand-veil', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (969, 'Glimmet', 'Rock', 'Poison', 'Paldea', 'SV', 'It absorbs nutrients from cave walls. The petals it wears are made of crystallized poison.', 'romfs:/sprites/969.png', 48, 35, 42, 105, 60, 60, 'medium-slow', 'toxic-debris', 'corrosion', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (970, 'Glimmora', 'Rock', 'Poison', 'Paldea', 'SV', 'When this Pokémon detects danger, it will open up its crystalline petals and fire beams from its conical body.', 'romfs:/sprites/970.png', 83, 55, 90, 130, 81, 86, 'medium-slow', 'toxic-debris', 'corrosion', NULL, 35);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (971, 'Greavard', 'Ghost', NULL, 'Paldea', 'SV', 'It is said that a dog Pokémon that died in the wild without ever interacting with a human was reborn as this Pokémon.', 'romfs:/sprites/971.png', 50, 61, 60, 30, 55, 34, 'medium-slow', 'pickup', 'fluffy', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (972, 'Houndstone', 'Ghost', NULL, 'Paldea', 'SV', 'Houndstone spends most of its time sleeping in graveyards. Among all the dog Pokémon, this one is most loyal to its master.', 'romfs:/sprites/972.png', 72, 101, 100, 50, 97, 68, 'medium-slow', 'sand-rush', 'fluffy', NULL, 30);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (973, 'Flamigo', 'Flying', 'Fighting', 'Paldea', 'SV', 'This Pokémon apparently ties the base of its neck into a knot so that energy stored in its belly does not escape from its beak.', 'romfs:/sprites/973.png', 82, 115, 74, 75, 64, 90, 'medium-slow', 'scrappy', 'tangled-feet', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (974, 'Cetoddle', 'Ice', NULL, 'Paldea', 'SV', 'This species left the ocean and began living on land a very long time ago. It seems to be closely related to Wailmer.', 'romfs:/sprites/974.png', 108, 68, 45, 30, 40, 43, 'medium-slow', 'thick-fat', 'snow-cloak', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (975, 'Cetitan', 'Ice', NULL, 'Paldea', 'SV', 'This Pokémon wanders around snowy, icy areas. It protects its body with powerful muscles and a thick layer of fat under its skin.', 'romfs:/sprites/975.png', 170, 113, 65, 45, 55, 73, 'medium-slow', 'thick-fat', 'slush-rush', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (976, 'Veluza', 'Water', 'Psychic', 'Paldea', 'SV', 'When Veluza discards unnecessary flesh, its mind becomes honed and its psychic power increases. The spare flesh has a mild but delicious flavor.', 'romfs:/sprites/976.png', 90, 102, 73, 78, 65, 70, 'fast', 'mold-breaker', 'sharpness', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (977, 'Dondozo', 'Water', NULL, 'Paldea', 'SV', 'This Pokémon is a glutton, but it’s bad at getting food. It teams up with a Tatsugiri to catch prey.', 'romfs:/sprites/977.png', 150, 100, 115, 65, 65, 35, 'slow', 'unaware', 'oblivious', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (978, 'Tatsugiri-curly', 'Dragon', 'Water', 'Paldea', 'SV', 'This is a small dragon Pokémon. It lives inside the mouth of Dondozo to protect itself from enemies on the outside.', 'romfs:/sprites/978.png', 68, 50, 60, 120, 95, 82, 'medium-slow', 'commander', 'storm-drain', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (979, 'Annihilape', 'Fighting', 'Ghost', 'Paldea', 'SV', 'When its anger rose beyond a critical point, this Pokémon gained power that is unfettered by the limits of its physical body.', 'romfs:/sprites/979.png', 110, 115, 80, 50, 90, 90, 'medium', 'vital-spirit', 'inner-focus', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (980, 'Clodsire', 'Poison', 'Ground', 'Paldea', 'SV', 'When attacked, this Pokémon will retaliate by sticking thick spines out from its body. It’s a risky move that puts everything on the line.', 'romfs:/sprites/980.png', 130, 75, 60, 45, 100, 20, 'medium', 'poison-point', 'water-absorb', NULL, 20);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (981, 'Farigiraf', 'Normal', 'Psychic', 'Paldea', 'SV', 'Now that the brain waves from the head and tail are synced up, the psychic power of this Pokémon is 10 times stronger than Girafarig’s.', 'romfs:/sprites/981.png', 120, 90, 70, 110, 70, 60, 'medium', 'cud-chew', 'armor-tail', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (982, 'Dudunsparce-two-segment', 'Normal', NULL, 'Paldea', 'SV', 'This Pokémon uses its hard tail to make its nest by boring holes into bedrock deep underground. The nest can reach lengths of over six miles.', 'romfs:/sprites/982.png', 125, 100, 80, 85, 75, 55, 'medium', 'serene-grace', 'run-away', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (983, 'Kingambit', 'Dark', 'Steel', 'Paldea', 'SV', 'Only a Bisharp that stands above all others in its vast army can evolve into Kingambit.', 'romfs:/sprites/983.png', 100, 135, 120, 60, 85, 50, 'medium', 'defiant', 'supreme-overlord', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (984, 'Great-tusk', 'Ground', 'Fighting', 'Paldea', 'SV', 'Sightings of this Pokémon have occurred in recent years. The name Great Tusk was taken from a creature listed in a certain book.', 'romfs:/sprites/984.png', 115, 131, 131, 53, 53, 87, 'slow', 'protosynthesis', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (985, 'Scream-tail', 'Fairy', 'Psychic', 'Paldea', 'SV', 'There has been only one reported sighting of this Pokémon. It resembles a mysterious creature depicted in an old expedition journal.', 'romfs:/sprites/985.png', 115, 65, 99, 65, 115, 111, 'slow', 'protosynthesis', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (986, 'Brute-bonnet', 'Grass', 'Dark', 'Paldea', 'SV', 'It is possible that the creature listed as Brute Bonnet in a certain book could actually be this Pokémon.', 'romfs:/sprites/986.png', 111, 127, 99, 79, 99, 55, 'slow', 'protosynthesis', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (987, 'Flutter-mane', 'Ghost', 'Fairy', 'Paldea', 'SV', 'This Pokémon has characteristics similar to those of Flutter Mane, a creature mentioned in a certain book.', 'romfs:/sprites/987.png', 55, 55, 55, 135, 135, 135, 'slow', 'protosynthesis', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (988, 'Slither-wing', 'Bug', 'Fighting', 'Paldea', 'SV', 'This mysterious Pokémon has some similarities to a creature that an old book introduced as Slither Wing.', 'romfs:/sprites/988.png', 85, 135, 79, 85, 105, 81, 'slow', 'protosynthesis', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (989, 'Sandy-shocks', 'Electric', 'Ground', 'Paldea', 'SV', 'No records exist of this Pokémon being caught. Data is lacking, but the Pokémon’s traits match up with a creature shown in an expedition journal.', 'romfs:/sprites/989.png', 85, 81, 97, 121, 85, 101, 'slow', 'protosynthesis', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (990, 'Iron-treads', 'Ground', 'Steel', 'Paldea', 'SV', 'This Pokémon closely resembles a scientific weapon that a paranormal magazine claimed was sent to this planet by aliens.', 'romfs:/sprites/990.png', 90, 112, 120, 72, 70, 106, 'slow', 'quark-drive', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (991, 'Iron-bundle', 'Ice', 'Water', 'Paldea', 'SV', 'Its shape is similar to a robot featured in a paranormal magazine article. The robot was said to have been created by an ancient civilization.', 'romfs:/sprites/991.png', 56, 80, 114, 124, 60, 136, 'slow', 'quark-drive', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (992, 'Iron-hands', 'Fighting', 'Electric', 'Paldea', 'SV', 'It is very similar to a cyborg covered exclusively by a paranormal magazine. The cyborg was said to be the modified form of a certain athlete.', 'romfs:/sprites/992.png', 154, 140, 108, 50, 68, 50, 'slow', 'quark-drive', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (993, 'Iron-jugulis', 'Dark', 'Flying', 'Paldea', 'SV', 'It resembles a certain Pokémon introduced in a paranormal magazine, described as the offspring of a Hydreigon that fell in love with a robot.', 'romfs:/sprites/993.png', 94, 80, 86, 122, 80, 108, 'slow', 'quark-drive', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (994, 'Iron-moth', 'Fire', 'Poison', 'Paldea', 'SV', 'This Pokémon resembles an unknown object described in a paranormal magazine as a UFO sent to observe humanity.', 'romfs:/sprites/994.png', 80, 70, 60, 140, 110, 110, 'slow', 'quark-drive', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (995, 'Iron-thorns', 'Rock', 'Electric', 'Paldea', 'SV', 'It has some similarities to a Pokémon introduced in a dubious magazine as a Tyranitar from one billion years into the future.', 'romfs:/sprites/995.png', 100, 134, 110, 70, 84, 72, 'slow', 'quark-drive', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (996, 'Frigibax', 'Dragon', 'Ice', 'Paldea', 'SV', 'Frigibax absorbs heat through its dorsal fin and converts the heat into ice energy. The higher the temperature, the more energy Frigibax stores.', 'romfs:/sprites/996.png', 65, 75, 45, 35, 45, 55, 'slow', 'thermal-exchange', 'ice-body', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (997, 'Arctibax', 'Dragon', 'Ice', 'Paldea', 'SV', 'Arctibax freezes the air around it, protecting its face with an ice mask and turning its dorsal fin into a blade of ice.', 'romfs:/sprites/997.png', 90, 95, 66, 45, 65, 62, 'slow', 'thermal-exchange', 'ice-body', NULL, 35);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (998, 'Baxcalibur', 'Dragon', 'Ice', 'Paldea', 'SV', 'This Pokémon blasts cryogenic air out from its mouth. This air can instantly freeze even liquid-hot lava.', 'romfs:/sprites/998.png', 115, 145, 92, 75, 86, 87, 'slow', 'thermal-exchange', 'ice-body', NULL, 54);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (999, 'Gimmighoul', 'Ghost', NULL, 'Paldea', 'SV', 'This Pokémon was born inside a treasure chest about 1,500 years ago. It sucks the life-force out of scoundrels who try to steal the treasure.', 'romfs:/sprites/999.png', 45, 30, 70, 75, 70, 10, 'slow', 'rattled', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (1000, 'Gholdengo', 'Steel', 'Ghost', 'Paldea', 'SV', 'Its body seems to be made up of 1,000 coins. This Pokémon gets along well with others and is quick to make friends with anybody.', 'romfs:/sprites/1000.png', 87, 60, 95, 133, 91, 84, 'slow', 'good-as-gold', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (1001, 'Wo-chien', 'Dark', 'Grass', 'Paldea', 'SV', 'The grudge of a person punished for writing the king’s evil deeds upon wooden tablets has clad itself in dead leaves to become a Pokémon.', 'romfs:/sprites/1001.png', 85, 85, 100, 95, 135, 70, 'slow', 'tablets-of-ruin', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (1002, 'Chien-pao', 'Dark', 'Ice', 'Paldea', 'SV', 'This Pokémon can control 100 tons of fallen snow. It plays around innocently by leaping in and out of avalanches it has caused.', 'romfs:/sprites/1002.png', 80, 120, 80, 90, 65, 135, 'slow', 'sword-of-ruin', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (1003, 'Ting-lu', 'Dark', 'Ground', 'Paldea', 'SV', 'The fear poured into an ancient ritual vessel has clad itself in rocks and dirt to become a Pokémon.', 'romfs:/sprites/1003.png', 155, 110, 125, 55, 80, 45, 'slow', 'vessel-of-ruin', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (1004, 'Chi-yu', 'Dark', 'Fire', 'Paldea', 'SV', 'It controls flames burning at over 5,400 degrees Fahrenheit. It casually swims through the sea of lava it creates by melting rock and sand.', 'romfs:/sprites/1004.png', 55, 80, 80, 135, 120, 100, 'slow', 'beads-of-ruin', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (1005, 'Roaring-moon', 'Dragon', 'Dark', 'Paldea', 'SV', 'It is possible that this is the creature listed as Roaring Moon in an expedition journal that still holds many mysteries.', 'romfs:/sprites/1005.png', 105, 139, 71, 55, 101, 119, 'slow', 'protosynthesis', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (1006, 'Iron-valiant', 'Fairy', 'Fighting', 'Paldea', 'SV', 'It has some similarities to a mad scientist’s invention covered in a paranormal magazine.', 'romfs:/sprites/1006.png', 74, 130, 90, 120, 60, 116, 'slow', 'quark-drive', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (1007, 'Koraidon', 'Fighting', 'Dragon', 'Paldea', 'SV', 'This seems to be the Winged King mentioned in an old expedition journal. It was said to have split the land with its bare fists.', 'romfs:/sprites/1007.png', 100, 135, 115, 85, 100, 135, 'slow', 'orichalcum-pulse', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (1008, 'Miraidon', 'Electric', 'Dragon', 'Paldea', 'SV', 'Much remains unknown about this creature. It resembles Cyclizar, but it is far more ruthless and powerful.', 'romfs:/sprites/1008.png', 100, 85, 100, 135, 115, 135, 'slow', 'hadron-engine', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (1009, 'Walking-wake', 'Water', 'Dragon', 'Paldea', 'SV', 'This ferocious creature is shrouded in mystery. It''s named after an aquatic monster mentioned in an old expedition journal.', 'romfs:/sprites/1009.png', 99, 83, 91, 125, 83, 109, 'slow', 'protosynthesis', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (1010, 'Iron-leaves', 'Grass', 'Psychic', 'Paldea', 'SV', 'Many of its physical characteristics match those of a Virizion from the future that was covered in a paranormal magazine.', 'romfs:/sprites/1010.png', 90, 130, 88, 70, 108, 104, 'slow', 'quark-drive', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (1011, 'Dipplin', 'Grass', 'Dragon', 'Paldea', 'SV', 'Dipplin is two creatures in one Pokémon. Its evolution was triggered by a special apple grown only in one place.', 'romfs:/sprites/1011.png', 80, 80, 110, 95, 80, 40, 'slow', 'supersweet-syrup', 'gluttony', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (1012, 'Poltchageist', 'Grass', 'Ghost', 'Paldea', 'SV', 'Supposedly, the regrets of a tea ceremony master who died before perfecting his craft lingered in some matcha and became a Pokémon.', 'romfs:/sprites/1012.png', 40, 45, 45, 74, 54, 50, 'slow', 'hospitality', 'heatproof', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (1013, 'Sinistcha', 'Grass', 'Ghost', 'Paldea', 'SV', 'It pretends to be tea, trying to fool people into drinking it so it can drain their life-force. Its ruse is generally unsuccessful.', 'romfs:/sprites/1013.png', 71, 60, 106, 121, 80, 70, 'slow', 'hospitality', 'heatproof', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (1014, 'Okidogi', 'Poison', 'Fighting', 'Paldea', 'SV', 'After all its muscles were stimulated by the toxic chain around its neck, Okidogi transformed and gained a powerful physique.', 'romfs:/sprites/1014.png', 88, 128, 115, 58, 86, 80, 'slow', 'toxic-chain', 'guard-dog', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (1015, 'Munkidori', 'Poison', 'Psychic', 'Paldea', 'SV', 'The chain is made from toxins that enhance capabilities. It stimulated Munkidori''s brain and caused the Pokémon''s psychic powers to bloom.', 'romfs:/sprites/1015.png', 88, 75, 66, 130, 90, 106, 'slow', 'toxic-chain', 'frisk', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (1016, 'Fezandipiti', 'Poison', 'Fairy', 'Paldea', 'SV', 'Fezandipiti owes its beautiful looks and lovely voice to the toxic stimulants emanating from the chain wrapped around its body.', 'romfs:/sprites/1016.png', 88, 91, 82, 70, 125, 99, 'slow', 'toxic-chain', 'technician', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (1017, 'Ogerpon', 'Grass', NULL, 'Paldea', 'SV', 'This Pokémon''s type changes based on which mask it''s wearing. It confounds its enemies with nimble movements and kicks.', 'romfs:/sprites/1017.png', 80, 120, 84, 60, 96, 110, 'slow', 'defiant', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (1018, 'Archaludon', 'Steel', 'Dragon', 'Paldea', 'SV', 'It gathers static electricity from its surroundings. The beams it launches when down on all fours are tremendously powerful.', 'romfs:/sprites/1018.png', 90, 105, 130, 125, 65, 85, 'medium', 'stamina', 'sturdy', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (1019, 'Hydrapple', 'Grass', 'Dragon', 'Paldea', 'SV', 'Seven syrpents live inside an apple made of syrup. The syrpent in the center is the commander.', 'romfs:/sprites/1019.png', 106, 80, 110, 120, 80, 44, 'slow-then-very-fast', 'supersweet-syrup', 'regenerator', NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (1020, 'Gouging-fire', 'Fire', 'Dragon', 'Paldea', 'SV', 'There are scant few reports of this creature being sighted. One short video shows it rampaging and spouting pillars of flame.', 'romfs:/sprites/1020.png', 105, 115, 121, 65, 93, 91, 'slow', 'protosynthesis', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (1021, 'Raging-bolt', 'Electric', 'Dragon', 'Paldea', 'SV', 'It''s said to incinerate everything around it with lightning launched from its fur. Very little is known about this creature.', 'romfs:/sprites/1021.png', 125, 73, 91, 137, 89, 75, 'slow', 'protosynthesis', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (1022, 'Iron-boulder', 'Rock', 'Psychic', 'Paldea', 'SV', 'It resembles a Pokémon described in a dubious magazine as a Terrakion that had been modified by an evil organization.', 'romfs:/sprites/1022.png', 90, 120, 80, 68, 108, 124, 'slow', 'quark-drive', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (1023, 'Iron-crown', 'Steel', 'Psychic', 'Paldea', 'SV', 'It resembles a mysterious object introduced in a paranormal magazine as a cutting-edge weapon shaped like a Cobalion.', 'romfs:/sprites/1023.png', 90, 72, 100, 122, 108, 98, 'slow', 'quark-drive', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (1024, 'Terapagos', 'Normal', NULL, 'Paldea', 'SV', 'Terapagos protects itself using its power to transform energy into hard crystals. This Pokémon is the source of the Terastal phenomenon.', 'romfs:/sprites/1024.png', 90, 65, 85, 65, 85, 60, 'slow', 'tera-shift', NULL, NULL, NULL);
INSERT OR REPLACE INTO pokemon (species_id, name, type1, type2, region, game_code, description, sprite_path, hp, attack, defense, sp_attack, sp_defense, speed, growth_rate, ability1, ability2, hidden_ability, evolve_level) VALUES (1025, 'Pecharunt', 'Poison', 'Ghost', 'Paldea', 'SV', 'It feeds others toxic mochi that draw out desires and capabilities. Those who eat the mochi fall under Pecharunt’s control, chained to its will.', 'romfs:/sprites/1025.png', 88, 88, 160, 88, 88, 88, 'slow', 'poison-puppeteer', NULL, NULL, NULL);
COMMIT;